window.BASAIR_QUESTIONS=[{"id":"s1-1","number":1,"surah":1,"verses":[1],"verseLabel":"1","question":"ما سرّ التعبير بقوله تعالى: ﴿بِسْمِ اللَّهِ﴾ من غير أن يُذكر الفعل: «أبدأ» أو «أقرأ»؟","answer":"حذف العامل يجعل البسملة صالحة لكل مقام؛ فالقارئ يقدّر «أقرأ»، والكاتب «أكتب»، والمسافر «أسافر». وفي الحذف إيجاز مع تقديم اسم الله عنايةً وابتداءً به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص43–45، تحت الفاتحة: 1.","url":""}]},{"id":"s1-2","number":2,"surah":1,"verses":[1],"verseLabel":"1","question":"لماذا اجتمع الاسمان ﴿الرَّحْمَنِ الرَّحِيمِ﴾، ولم يُكتفَ بأحدهما؟","answer":"«الرحمن» أبلغ في الاتصاف بالرحمة، و«الرحيم» يدل على ثبوتها وتعلّقها بالمرحوم؛ فجمع الاسمان بين كمال صفة الرحمة وظهور أثرها في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص50–51، تحت الفاتحة: 1.","url":""}]},{"id":"s1-3","number":3,"surah":1,"verses":[1],"verseLabel":"1","question":"ما سرّ تقديم ﴿الرَّحْمَنِ﴾ على ﴿الرَّحِيمِ﴾؟","answer":"قُدِّم «الرحمن» لأنه أبلغ، ويتناول عظائم النعم وأصولها، ثم أُتبع بـ«الرحيم» ليتناول ما دقّ منها ولطف؛ فكان الانتقال من الأعم والأعلى إلى ما يتممه ويفصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص49–50، تحت الفاتحة: 1.","url":""}]},{"id":"s1-4","number":4,"surah":1,"verses":[2],"verseLabel":"2","question":"لماذا اختير ﴿الْحَمْدُ﴾ بدل «الشكر»؟","answer":"اختير ﴿الْحَمْدُ﴾ دون الشكر؛ لأن الحمد يعمّ الفضائل والفواضل، بخلاف الشكر فإنه خاص بالفواضل؛ أي إن الحمد يكون على صفات الكمال وعلى النِّعم، أما الشكر فيكون على النِّعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص56، تحت الفاتحة: 2.","url":""}]},{"id":"s1-5","number":5,"surah":1,"verses":[2],"verseLabel":"2","question":"لماذا اختير ﴿الْحَمْدُ﴾ بدل «المدح»؟","answer":"المدح قد يتعلق بجماد أو صفة بلا محبة، أما الحمد فثناء على الجميل الاختياري مع المحبة والتعظيم، وهو أليق بالثناء على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص56، تحت الفاتحة: 2.","url":""}]},{"id":"s1-6","number":6,"surah":1,"verses":[2],"verseLabel":"2","question":"ما سرّ التعبير بقوله تعالى: ﴿الْحَمْدُ لِلَّهِ﴾ جملةً اسمية، ولم يقل: «أحمد الله» أو «نحمد الله»؟","answer":"الجملة الاسمية تثبت استحقاق الحمد وتطلقه من فاعل وزمن محددين؛ فالله محمود قبل حمد الحامدين وبعده، أما الفعل فيقيد الحمد بفاعل وزمن وقدر محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص56–58، تحت الفاتحة: 2.","url":""}]},{"id":"s1-7","number":7,"surah":1,"verses":[2],"verseLabel":"2","question":"لماذا رُفع ﴿الْحَمْدُ﴾ وعُرِّف، ولم يقل: «حمدًا لله»؟","answer":"الرفع يبني جملة اسمية تدل على ثبوت الحمد واستمراره، و«أل» تفيد استغراق جنس الحمد؛ أما النصب فيقدّر معه فعل، فتغلب عليه دلالة التجدد والحدوث ولا يؤدي العموم والثبوت نفسيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص56–59، تحت الفاتحة: 2.","url":""}]},{"id":"s1-8","number":8,"surah":1,"verses":[2],"verseLabel":"2","question":"ما سرّ التعبير بقوله تعالى: ﴿الْحَمْدُ لِلَّهِ﴾ لا «لله الحمد»؟","answer":"تقديم «لله» يفيد قصرًا يناسب مقام إزالة الإنكار، كما في سياق الجاثية مع الكافرين؛ أما الفاتحة فمقام تعليم المؤمنين، فجاء الأصل الهادئ من غير إبراز معنى الرد على منكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص59–60، تحت الفاتحة: 2، في المقارنة بالجاثية: 36.","url":""}]},{"id":"s1-9","number":9,"surah":1,"verses":[2],"verseLabel":"2","question":"لماذا أُظهر اسم الجلالة في ﴿الْحَمْدُ لِلَّهِ﴾ ولم يقل: «الحمد له»؟","answer":"أُظهر اسم الجلالة مع سبق ذكره في البسملة، فعدل عن الضمير للتلذذ والتبرك بذكر اسم الله الصريح وتعظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص59، تحت الفاتحة: 2.","url":""}]},{"id":"s1-10","number":10,"surah":1,"verses":[2],"verseLabel":"2","question":"لماذا اختير اسم ﴿اللَّهِ﴾ لا اسم آخر من أسمائه؟","answer":"اختير اسم ﴿اللَّهِ﴾ لأنه يدل بمفرده على صفات الجلال والجمال والكمال، وعلى استحقاق الحمد لذاته؛ ولو عُلّق الحمد باسم آخر فقد يُتوهم اختصاصه بالصفة التي يدل عليها ذلك الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص60، تحت الفاتحة: 2.","url":""}]},{"id":"s1-11","number":11,"surah":1,"verses":[2],"verseLabel":"2","question":"لماذا أتبع اسم الله بوصف ﴿رَبِّ الْعَالَمِينَ﴾؟","answer":"لأن «الرب» هو المالك والسيد والمصلح والمدبر والمنعم والمربي؛ ومن انفرد بربوبية العالمين والقيام على شؤونهم كان مستحقًا لجميع المحامد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص53–55، تحت الفاتحة: 2.","url":""}]},{"id":"s1-12","number":12,"surah":1,"verses":[2],"verseLabel":"2","question":"ما سرّ التعبير بقوله تعالى: ﴿الْعَالَمِينَ﴾ لا «العوالم»؟","answer":"عُدل عن «العوالم» إلى ﴿الْعَالَمِينَ﴾ تغليبًا للعقلاء على غيرهم، وليشمل اللفظ الأجناس المختلفة؛ وفي جمعه جمعَ العقلاء تنبيه إلى شرفهم مع دخول سائر الخلق في عموم ربوبية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص60–61، تحت الفاتحة: 2.","url":""}]},{"id":"s1-13","number":13,"surah":1,"verses":[3],"verseLabel":"3","question":"لماذا تكرر ﴿الرَّحْمَنِ الرَّحِيمِ﴾ بعد ورودهما في البسملة؟","answer":"في البسملة جاء الاسمان في افتتاح القراءة والاستعانة، ثم عادا بعد ﴿رَبِّ الْعَالَمِينَ﴾ لبيان أن ربوبيته قائمة على الرحمة، ولتأكيد العناية بها؛ فاختلف موقعهما وغرضهما، ولم يكن التكرار خاليًا من فائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص64–65، تحت الفاتحة: 3.","url":""}]},{"id":"s1-14","number":14,"surah":1,"verses":[3,4],"verseLabel":"3–4","question":"لماذا تقدمت الرحمة في ﴿الرَّحْمَنِ الرَّحِيمِ﴾ على الملك والجزاء في ﴿مَالِكِ يَوْمِ الدِّينِ﴾؟","answer":"تقدمت الرحمة لتبعث على الرجاء، ثم ذُكر ملك يوم الدين ليبعث على الخوف والاستعداد للجزاء؛ فجمع السياق للعبد بين الرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص64–67، تحت الفاتحة: 3–4.","url":""}]},{"id":"s1-15","number":15,"surah":1,"verses":[4],"verseLabel":"4","question":"ماذا يضيف اجتماع القراءتين المتواترتين: ﴿مَالِكِ﴾ و﴿مَلِكِ يَوْمِ الدِّينِ﴾؟","answer":"تبرز قراءة ﴿مَالِكِ﴾ معنى التملك والتصرف، وتبرز قراءة ﴿مَلِكِ﴾ معنى السلطان والحكم؛ ولكل منهما جهة عموم وجهة خصوص، وباجتماع القراءتين يتكامل المعنيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص71–72، تحت الفاتحة: 4.","url":""}]},{"id":"s1-16","number":16,"surah":1,"verses":[4],"verseLabel":"4","question":"لماذا اختير ﴿مَالِكِ﴾ هنا لا «رب يوم الدين»؟","answer":"لأن وصف المالك أشعر بإقامة الجزاء على وفق أعمال العباد، أما وصف الرب ففيه معنى التربية والرحمة، وقد يطمع المفسد في العفو؛ فناسب مقام الجزاء وصف ﴿مَالِكِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص68–69، تحت الفاتحة: 4.","url":""}]},{"id":"s1-17","number":17,"surah":1,"verses":[4],"verseLabel":"4","question":"لماذا أضيف الملك إلى اليوم نفسه: ﴿مَالِكِ يَوْمِ الدِّينِ﴾، مع أن اليوم زمن؟","answer":"لأن ملك الظرف يستلزم ملك جميع ما يقع فيه؛ فملكية يوم الدين كناية عن ملك كل ما يشتمل عليه ذلك اليوم، وهي أبلغ من ذكر بعض ما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص69، تحت الفاتحة: 4.","url":""}]},{"id":"s1-18","number":18,"surah":1,"verses":[4],"verseLabel":"4","question":"ما سرّ التعبير بقوله تعالى: ﴿يَوْمِ الدِّينِ﴾ لا «يوم القيامة»؟","answer":"لأن ﴿يَوْمِ الدِّينِ﴾ أعم من «يوم القيامة»؛ فالدين هنا الجزاء والحساب، ويشمل أحوال الآخرة من ابتداء النشور إلى الاستقرار الأبدي، أما القيامة فتدل على قيام الناس من قبورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص71، تحت الفاتحة: 4.","url":""}]},{"id":"s1-19","number":19,"surah":1,"verses":[4],"verseLabel":"4","question":"لماذا خُص يوم الدين بالملك، ولم تُذكر الدنيا معه؟","answer":"سبق وصف الله بأنه ﴿رَبِّ الْعَالَمِينَ﴾، فشمل ملكه وتصرفه في الدنيا والآخرة. ثم خُص يوم الدين بالذكر عنايةً به وتنبيهًا إلى الاستعداد له؛ وذكره لا ينفي ملك الله لما عداه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص69–70، تحت الفاتحة: 4.","url":""}]},{"id":"s1-20","number":20,"surah":1,"verses":[2,3,4],"verseLabel":"2–4","question":"كيف استوعبت أوصاف الحمد في مطلع الفاتحة الأزمنة كلها؟","answer":"دلّ إطلاق ﴿الحمد لله﴾ على استحقاقه الحمد قبل وجود الخلق، ودلّ ﴿رب العالمين﴾ على حمده منذ إنشاء العالم وتدبيره، ودلّ ﴿الرحمن الرحيم﴾ على رحمته المستمرة، ودلّ ﴿مالك يوم الدين﴾ على حمده في يوم الجزاء وما بعده؛ فاستغرق الحمد الأزل والحياة والآخرة.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 07:00 إلى 09:54، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-21","number":21,"surah":1,"verses":[5],"verseLabel":"5","question":"ما سرّ الانتقال من الغيبة في ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ إلى الخطاب في ﴿إِيَّاكَ نَعْبُدُ﴾؟","answer":"لما أثنى العبد على الله بأسمائه وصفاته ارتقى من الحديث عنه إلى مناجاته ومواجهته بالعبادة والاستعانة؛ فالالتفات يصور قرب العبد وحضوره بين يدي ربه بعد الثناء.","sources":[{"label":"تفسير ابن كثير ضمن موسوعة القرآن، الفاتحة: 5، https://quranpedia.net/tafsir/al-fatiha/5","url":""}]},{"id":"s1-22","number":22,"surah":1,"verses":[5],"verseLabel":"5","question":"ما سرّ تقديم ﴿إِيَّاكَ﴾ في ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾؟","answer":"تقديم المفعول يفيد الاختصاص والقصر؛ أي نخصك وحدك بالعبادة والاستعانة، بخلاف «نعبدك» التي تثبت العبادة له من غير أن تنفيها عمن سواه.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 10:26 إلى 15:04، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-23","number":23,"surah":1,"verses":[5],"verseLabel":"5","question":"ما سرّ تكرار ﴿إِيَّاكَ﴾ في ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾؟","answer":"أعيد الضمير لينص على أن المستعان به هو الله كما أن المعبود هو الله، وليجعل العبادة والاستعانة جملتين مستقلتين يمكن أن يقع كل منهما منفردًا، مع تقوية معنى الحصر بالتكرار.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 15:31 إلى 20:55، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-24","number":24,"surah":1,"verses":[5],"verseLabel":"5","question":"ما دلالة التعبير بنون الجماعة في ﴿نَعْبُدُ﴾ و﴿نَسْتَعِينُ﴾؟","answer":"صيغة الجمع تدخل القارئ في جماعة المؤمنين، وتبرز مكانة الجماعة في العبادة والاستعانة، فلا يقف العبد في الدعاء منعزلًا عن إخوانه.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 22:55 إلى 25:12، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-25","number":25,"surah":1,"verses":[5],"verseLabel":"5","question":"ما سرّ تقديم العبادة على الاستعانة؟","answer":"العبادة هي الغاية التي خُلق لها الإنس والجن، والاستعانة وسيلة إليها؛ وحق الله مقدّم على طلب العبد. كما جاورت العبادة ذكر الجزاء في ﴿مالك يوم الدين﴾، وجاورت الاستعانة طلب الهداية بعدها.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 27:12 إلى 30:40، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-26","number":26,"surah":1,"verses":[5],"verseLabel":"5","question":"ما دلالة إطلاق فعل ﴿نَسْتَعِينُ﴾ من غير تقييده بالعبادة أو الطاعة؟","answer":"حذف المتعلَّق يعمّم الاستعانة في كل ما يحتاجه العبد من أمر الدين والدنيا؛ ولو قُيدت بشيء لبقي حكم ما عداه خارج العبارة.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 21:14 إلى 22:31، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-27","number":27,"surah":1,"verses":[4,5],"verseLabel":"4–5","question":"ما مناسبة مجيء ﴿إِيَّاكَ نَعْبُدُ﴾ بعد ﴿مَالِكِ يَوْمِ الدِّينِ﴾؟","answer":"يوم الدين يوم الجزاء على الطاعة والعبادة، فناسب أن يعقب ذكر مالكه إقرار العبد بأنه يعبده وحده؛ ثم جاءت الاستعانة ملائمة لطلب الهداية بعدها.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية: إياك نعبد وإياك نستعين»، التفريغ من 29:17 إلى 30:17، https://baheth.ieasybooks.com/ar/media/لمسات-بيانية-004-سورة-الفاتحة-إياك-نعبد-وإياك-نستعين-أ-د-فاضل-السامرائي","url":""}]},{"id":"s1-28","number":28,"surah":1,"verses":[6],"verseLabel":"6","question":"ما سرّ طلب المؤمن الهداية في كل صلاة مع أنه مهتدٍ؟","answer":"المطلوب دوام التوفيق والثبات على الحق، والهداية إلى تفاصيله فيما يستقبل من العمر؛ فحاجة المؤمن إلى المعونة والهداية لا تنقطع بإيمانه الأول.","sources":[{"label":"الطبري، «جامع البيان»، تفسير الفاتحة: 6، ضمن https://quranpedia.net/tafsir/al-fatiha/6","url":""}]},{"id":"s1-29","number":29,"surah":1,"verses":[6],"verseLabel":"6","question":"ما دلالة اختيار ﴿الصِّرَاطَ﴾ في طلب الهداية؟","answer":"الصراط هو الطريق الواضح الذي لا اعوجاج فيه؛ فاختياره يصور الدين طريقًا بيّنًا مستقيمًا يوصل سالكه إلى الله وجنته.","sources":[{"label":"الطبري والسعدي، تفسير الفاتحة: 6، ضمن https://quranpedia.net/tafsir/al-fatiha/6","url":""}]},{"id":"s1-30","number":30,"surah":1,"verses":[6],"verseLabel":"6","question":"ما دلالة وصف الصراط بأنه ﴿الْمُسْتَقِيمَ﴾؟","answer":"الاستقامة تنفي الاعوجاج عن الطريق، وتدل على وضوحه وإيصاله إلى الغاية؛ فهو طريق الحق الذي يجمع معرفته والعمل به.","sources":[{"label":"الطبري والسعدي، تفسير الفاتحة: 6، ضمن https://quranpedia.net/tafsir/al-fatiha/6","url":""}]},{"id":"s1-31","number":31,"surah":1,"verses":[6,7],"verseLabel":"6–7","question":"ما سرّ إعادة لفظ ﴿صِرَاطَ﴾ في ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾؟","answer":"أعيد اللفظ لبيان الصراط المطلوب وتفسيره بطريق أهل النعمة؛ فالثاني بدل يوضح الأول ويعيّن نموذجه العملي.","sources":[{"label":"الطبري، «جامع البيان»، تفسير الفاتحة: 7، ضمن https://quranpedia.net/tafsir/al-fatiha/7","url":""}]},{"id":"s1-32","number":32,"surah":1,"verses":[7],"verseLabel":"7","question":"ما دلالة تعريف الصراط بأهله في ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾؟","answer":"لم يكتف بوصف الطريق نظريًا، بل عرّفه بمن سلكوه من النبيين والصديقين والشهداء والصالحين؛ ليظهر في قدوة بشرية معلومة ويُرغّب في صحبتهم واتباع سبيلهم.","sources":[{"label":"الطبري، «جامع البيان»، تفسير الفاتحة: 7، ضمن https://quranpedia.net/tafsir/al-fatiha/7","url":""}]},{"id":"s1-33","number":33,"surah":1,"verses":[7],"verseLabel":"7","question":"ما سرّ التعبير بـ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ﴾ بدل «لا المغضوب عليهم»؟","answer":"جاءت ﴿غير﴾ وصفًا للذين أُنعم عليهم، فبيّنت أن طريقهم منزّه عن طريق أهل الغضب والضلال، وجمعت تعريف أهل الصراط ونفي صفات مخالفيهم في تركيب واحد.","sources":[{"label":"الطبري، «جامع البيان»، تفسير الفاتحة: 7، ضمن https://quranpedia.net/tafsir/al-fatiha/7","url":""}]},{"id":"s1-34","number":34,"surah":1,"verses":[7],"verseLabel":"7","question":"ما دلالة زيادة ﴿لَا﴾ قبل ﴿الضَّالِّينَ﴾؟","answer":"أكدت ﴿لا﴾ نفي طريق الضالين بعد نفي طريق المغضوب عليهم، وجعلت كل فريق مقصودًا بالنفي استقلالًا؛ فليس المطلوب اجتناب وصف مركب فقط، بل اجتناب كل واحد من الطريقين.","sources":[{"label":"الطبري، «جامع البيان»، تفسير الفاتحة: 7، ضمن https://quranpedia.net/tafsir/al-fatiha/7","url":""}]},{"id":"s2-1","number":1,"surah":2,"verses":[1],"verseLabel":"البقرة: 1","question":"لماذا افتُتحت سورة البقرة بـ﴿الم﴾؟ وما أثر هذا المطلع في السامع؟","answer":"في افتتاح السورة بالحروف المقطعة غرابة تستدعي التفات السامع وتشرفه لمعرفة ما بعدها، فيقع الكلام الآتي في قلبٍ مستعد للإصغاء. وهي كذلك تلوّح بتحدي العرب وإعجاز القرآن؛ فالقرآن مؤلف من جنس الحروف التي يستعملونها في كلامهم، ومع ذلك عجزوا عن معارضته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص103–107، تحت البقرة: 1.","url":""}]},{"id":"s2-2","number":2,"surah":2,"verses":[2],"verseLabel":"البقرة: 2","question":"ما سرّ الإشارة إلى القرآن باسم البعيد في قوله تعالى: ﴿ذلك الكتاب﴾، مع أنه حاضر؟","answer":"أشير إليه باسم البعيد للإيماء إلى علو مكانه وسمو منزلته عن أن يشابه كلام البشر، فهو بُعد منزلة لا بُعد مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص107، تحت البقرة: 2.","url":""}]},{"id":"s2-3","number":3,"surah":2,"verses":[2],"verseLabel":"البقرة: 2","question":"ما الفرق بين الريب والشك في قوله تعالى: ﴿لا ريب فيه﴾؟","answer":"الريب أخص من الشك؛ فهو شك معه تهمة، أو شك تزيد عليه إساءة الظن، وحقيقته قلق النفس واضطرابها. فنفي الريب عن القرآن ينفي عنه الشك المصحوب بالتهمة والقلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص113–114، تحت الفرق المعجمي بين الريب والشك.","url":""}]},{"id":"s2-4","number":4,"surah":2,"verses":[2],"verseLabel":"البقرة: 2","question":"ما أثر توالي أوصاف القرآن في قوله تعالى: ﴿ذلك الكتاب لا ريب فيه هدى للمتقين﴾؟","answer":"يقوي بعض هذه الأوصاف بعضًا في الدلالة على كمال القرآن: فقوله ﴿ذلك الكتاب﴾ يدل على كماله، ويعزز ذلك نفي الريب عنه، ثم يأتي ﴿هدى﴾ منكّرًا للدلالة على عظيم هدايته. وجاءت الجمل مفصولًا بعضها عن بعض للإيماء إلى كمال الاتصال بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص111، تحت «بلاغة الأوصاف المتوالية».","url":""}]},{"id":"s2-5","number":5,"surah":2,"verses":[2],"verseLabel":"البقرة: 2","question":"ما دلالة تنكير ﴿هدى﴾ في قوله تعالى: ﴿هدى للمتقين﴾؟","answer":"نُكّر الهدى لتعظيمه وتفخيمه؛ فهو هدى عظيم لا يُسبر غوره ولا يُدرك منتهاه، وهو فخم لا يليق إلا بالمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص111، تحت «فائدة تنكير لفظ هدى لتعظيم القرآن».","url":""}]},{"id":"s2-6","number":6,"surah":2,"verses":[2],"verseLabel":"البقرة: 2","question":"لماذا خُصّ المتقون بالذكر في قوله تعالى: ﴿هدى للمتقين﴾، مع أن القرآن هدى للناس؟","answer":"خُصّ المتقون بالذكر لكونهم المنتفعين به، وإلا فالقرآن في نفسه هادٍ للناس وبيان لهم جميعًا، كما قال تعالى: ﴿هدى للناس﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص112، تحت «توجيه المخصوص بالذكر».","url":""}]},{"id":"s2-7","number":7,"surah":2,"verses":[2],"verseLabel":"البقرة: 2، ولقمان: 2","question":"لماذا بدأ في البقرة بقوله: ﴿ذلك الكتاب﴾، وفي لقمان بقوله: ﴿تلك آيات الكتاب الحكيم﴾؟","answer":"في البقرة لم تكن الآيات قد ذُكرت قبل، فمدح الكتاب برمته بقوله: ﴿ذلك الكتاب﴾. أما في لقمان فلما سبقت في الخطاب آيات كثيرة أشار إلى عظمة تلك الآيات؛ ليبين كمال الكتاب في كل جزء من أجزائه، لا في مجموعه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص619–620، تحت لقمان: 2، في المقارنة بالبقرة: 2.","url":""}]},{"id":"s2-8","number":8,"surah":2,"verses":[3,4,5],"verseLabel":"البقرة: 2–5، ولقمان: 3–5","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿هدى للمتقين﴾، وقوله في لقمان: ﴿هدى ورحمة للمحسنين﴾؟","answer":"تقدّم آية البقرة دعاء الفاتحة: ﴿اهدنا الصراط المستقيم﴾، فكان السياق متعلقًا بالهداية، فناسب قوله: ﴿هدى للمتقين﴾. أما سورة لقمان فتقدمها في ختام الروم ذكر الذين لا يعلمون ولا يوقنون وتهديدهم بوعد الله؛ فناسب أن تُخص هداية الله ورحمته بمن علموا وعده وآمنوا به وأيقنوا، فوصلوا إلى درجة الإحسان، فقيل: ﴿هدى ورحمة للمحسنين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص639–640، تحت «توجيه المتشابه اللفظي في الآية».","url":""}]},{"id":"s2-9","number":9,"surah":2,"verses":[3],"verseLabel":"البقرة: 3","question":"لماذا بدأ صفات المتقين بالإيمان بالغيب قبل الصلاة والإنفاق؟","answer":"لأن الإيمان بالغيب أُسّ متين وركن من مقومات الاعتقاد الإسلامي؛ فبدأ بالأصل الذي تقوم عليه سائر الخصال العملية، ثم ذكر إقامة الصلاة والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص119، تحت «فائدة الوصف بالاسم الموصول».","url":""}]},{"id":"s2-10","number":10,"surah":2,"verses":[3],"verseLabel":"البقرة: 3","question":"ما الذي يفيده قوله تعالى: ﴿يقيمون الصلاة﴾ فوق مجرد فعل الصلاة؟","answer":"إقامة الصلاة هي المداومة عليها، وإظهارها، والإتيان بها مع المحافظة على أركانها وشروطها ومكملاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص117 و120–121، تحت البقرة: 3.","url":""}]},{"id":"s2-11","number":11,"surah":2,"verses":[3],"verseLabel":"البقرة: 3","question":"لماذا عبّر بقوله: ﴿ومما رزقناهم ينفقون﴾، ولم يقل: ومن أموالهم؟","answer":"لأن حمل الرزق على العموم أولى وأنسب بوفرة معاني القرآن؛ فيشمل المال والقوة والجاه والعلم ونحو ذلك، والإنفاق قد يكون بالمال وقد يكون بغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص118، تحت شرح ﴿رزقناهم﴾ و﴿ينفقون﴾.","url":""}]},{"id":"s2-12","number":12,"surah":2,"verses":[3],"verseLabel":"البقرة: 3","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿ومما رزقناهم ينفقون﴾؟","answer":"﴿من﴾ للتبعيض؛ فهي تدل على أن المطلوب إنفاق بعض ما أُعطوا لا كله، حذرًا من الإسراف وتضييع من يعولون.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص122–123، تحت «فائدة تقديم الجار والمجرور».","url":""}]},{"id":"s2-13","number":13,"surah":2,"verses":[3],"verseLabel":"البقرة: 3","question":"ما سرّ تقديم قوله تعالى: ﴿ومما رزقناهم﴾ على فعل الإنفاق؟","answer":"قُدّم المنفَق منه للاهتمام بما أعطاهم الله، وتوجيه نظر المؤمن إلى نعمة الله عليه، بما يدعوه إلى تقييدها بالشكر إنفاقًا، وفيه إشارة إلى أنهم ينفقون مع ما للرزق من معزة على النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص122، تحت «فائدة تقديم الجار والمجرور».","url":""}]},{"id":"s2-14","number":14,"surah":2,"verses":[3],"verseLabel":"البقرة: 3","question":"لماذا لم يبيّن قوله تعالى: ﴿ينفقون﴾ مَن ينفقون عليهم؟","answer":"للدلالة على تنوع المستحقين للنفقة، فيدخل في ذلك كل من يصلح أن يُنفق عليه، كمصارف الزكاة، والأهل والأولاد والوالدين والضيف والجار وغيرهم. وفي الحذف أيضًا إشارة إلى أن النفقة مقصودة من حيث هي قربة إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص123، تحت «براعة حذف المتعلق في الإشارة إلى المقاصد».","url":""}]},{"id":"s2-15","number":15,"surah":2,"verses":[4],"verseLabel":"البقرة: 4","question":"لماذا كرر الاسم الموصول فقال: ﴿والذين يؤمنون بما أنزل إليك﴾ بعد قوله: ﴿الذين يؤمنون بالغيب﴾؟","answer":"ليجعل اختلاف الصفات بمنزلة اختلاف الذوات، وفي ذلك مدح للمؤمنين وثناء عليهم. فالصفة الثانية جليلة مستقلة لها شأنها، وليست مجرد تتمة للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص126–127، تحت «تكرار الاسم الموصول للدلالة على تغاير الصفات» و«فائدة تكرار فعل يؤمنون».","url":""}]},{"id":"s2-16","number":16,"surah":2,"verses":[4],"verseLabel":"البقرة: 4","question":"ما فائدة ذكر الضمير ﴿هم﴾ في قوله تعالى: ﴿وبالآخرة هم يوقنون﴾؟","answer":"فيه توكيد للخبر واهتمام بأمر الآخرة؛ لأن نسبة الإيقان أُسندت إليهم مرتين: مرة بضمير ﴿هم﴾ ومرة بواو الجماعة في ﴿يوقنون﴾. وفي التركيب أيضًا تعريض بمن عداهم ممن كانت معتقداتهم في الآخرة مضطربة لا تبلغ رتبة اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص129–131، تحت «نكتة إسناد فعل الإيقان إلى فاعله مرتين» و«بلاغة ذكر الضمير».","url":""}]},{"id":"s2-17","number":17,"surah":2,"verses":[4],"verseLabel":"البقرة: 4","question":"لماذا عبّر عن الآخرة باليقين، مع أنه عبّر عن الغيب والوحي بالإيمان؟","answer":"لأن الآخرة حياة غائبة عن المشاهدة، غريبة بحسب المتعارف، وقد كثرت الشبه التي جرّت المشركين والدهريين إلى نفيها؛ فكان الإيمان بها جديرًا بمادة الإيقان، وهي أخص من مطلق الإيمان وأدل على العلم الذي لا يتطرق إليه الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص130–131، تحت دلالة التعبير بالإيقان.","url":""}]},{"id":"s2-18","number":18,"surah":2,"verses":[5],"verseLabel":"البقرة: 5","question":"لماذا كرر اسم الإشارة في قوله تعالى: ﴿أولئك على هدى من ربهم وأولئك هم المفلحون﴾؟","answer":"للتنبيه على أن كل حكم مستقل عن الآخر؛ تكثيرًا لفضل الله الذي حصّلوه، وزيادة في الثناء عليهم وتكريمهم. فجُعل ثبوت الهدى لهم منزلة مستقلة، وثبوت الفلاح منزلة أخرى مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص136، تحت «دلالة تكرير اسم الإشارة».","url":""}]},{"id":"s2-19","number":19,"surah":2,"verses":[5],"verseLabel":"البقرة: 5","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿على هدى﴾؟","answer":"شُبّه حال المتقين في تمسكهم بالهدى واستقرارهم عليه بحال من اعتلى شيئًا وتمكن منه؛ لأن أفعالهم كانت على مقتضى الهدى، فكان تصرفهم به كتصرف الراكب فيما يركب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص134–135، تحت «دلالة الاستعلاء في قوله: على هدى».","url":""}]},{"id":"s2-20","number":20,"surah":2,"verses":[5],"verseLabel":"البقرة: 5","question":"ماذا أفاد قوله تعالى: ﴿من ربهم﴾ بعد وصف المتقين بأنهم ﴿على هدى﴾؟","answer":"أفاد أن هذا الهدى صادر من الله سبحانه وبتوفيقه، وفي إضافة الرب إليهم تعظيم لشأن المتقين وتشريف لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص135، تحت دلالة ﴿من ربهم﴾.","url":""}]},{"id":"s2-21","number":21,"surah":2,"verses":[5],"verseLabel":"البقرة: 5","question":"ما دلالة تعريف ﴿المفلحون﴾ وذكر الضمير ﴿هم﴾ في قوله تعالى: ﴿وأولئك هم المفلحون﴾؟","answer":"تعريف طرفي الجملة، ﴿أولئك﴾ و﴿المفلحون﴾، يفيد القصر؛ أي إن المتقين منفردون بالفلاح الحقيقي. وجاء ضمير الفصل ﴿هم﴾ لتقوية هذا القصر وتوكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص136–137، تحت «القصر بتعريف طرفي الجملة» و«دور الضمير هم».","url":""}]},{"id":"s2-22","number":22,"surah":2,"verses":[6],"verseLabel":"البقرة: 6","question":"كيف يستوي إنذار الكافرين وعدم إنذارهم في قوله تعالى: ﴿سواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون﴾؟","answer":"المراد الذين جحدوا ما أُنزل إلى النبي ﷺ استكبارًا وإعراضًا وعنادًا؛ فلن يؤتي تخويفهم من عذاب الله ثمرته فيهم، ولذلك استوى عندهم الإنذار وعدمه، وبيّن قوله: ﴿لا يؤمنون﴾ حقيقة هذا الاستواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص141 و146، تحت المعنى الإجمالي وتوجيه ﴿لا يؤمنون﴾.","url":""}]},{"id":"s2-23","number":23,"surah":2,"verses":[6],"verseLabel":"البقرة: 6","question":"لماذا ذُكر الإنذار دون البشارة في شأن هؤلاء الكافرين؟","answer":"لأن المتحدث عنهم ليسوا أهلًا للبشارة، ولأن الإنذار أشد وقعًا وتأثيرًا في القلب؛ فإذا لم ينتفعوا بالإنذار كان عدم انتفاعهم بالبشارة من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص145، تحت «نكتة الاكتفاء بالنذارة عن البشارة».","url":""}]},{"id":"s2-24","number":24,"surah":2,"verses":[7],"verseLabel":"البقرة: 7","question":"ما الفرق بين الختم والطبع في الاستعمال القرآني؟","answer":"للعلماء قولان مشهوران: أحدهما أن الختم والطبع بمعنى واحد، والآخر أن الطبع أقوى؛ لأن فيه معنى الثبات، فهو أثر يثبت في المطبوع ولا يزول. ويؤيد القول الثاني أن مشتقات الختم وردت في القرآن في الخير والشر، أما الطبع فلم يرد إلا في الشر والذم. ومع ذلك، إذا جاء الختم والطبع فعلين فإن دلالتهما تكاد تكون متقاربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص156–157، تحت «ختم وطبع».","url":""}]},{"id":"s2-25","number":25,"surah":2,"verses":[7],"verseLabel":"البقرة: 7","question":"لماذا أُفرد السمع وجُمعت القلوب والأبصار في قوله تعالى: ﴿على قلوبهم وعلى سمعهم وعلى أبصارهم﴾؟","answer":"لأن السمع مصدر، والمصدر يقع على القليل والكثير من جنسه، فلا يُجمع في الأصل. أما القلب والبصر فاسمان للجارحتين، فصح جمعهما، وجاء الجمع مناسبًا لأن الحديث عن جماعة من الكافرين، فيُرد كل قلب وبصر إلى صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص153–154، تحت «نكتة إفراد السمع وجمع القلوب والأبصار».","url":""}]},{"id":"s2-26","number":26,"surah":2,"verses":[7],"verseLabel":"البقرة: 7","question":"لماذا جُعل الختم على القلوب والأسماع، وجُعلت الغشاوة على الأبصار؟","answer":"لأن القلوب والأسماع تشبه الأوعية، فيتصور فيها معنى السد والختم، أما الأبصار فاختصت بالغشاوة لأنها تمنع أصل الرؤية. والمقصود حجب رؤية الاعتبار المؤدية إلى الإيمان، لا منع الرؤية الحسية مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص154–155، تحت «انتقاء الألفاظ تابع لدقة المعنى».","url":""}]},{"id":"s2-27","number":27,"surah":2,"verses":[7],"verseLabel":"البقرة: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿ولهم عذاب عظيم﴾، فقُدّم ﴿لهم﴾ ووُصف العذاب بالعِظم؟","answer":"قُدّم ﴿لهم﴾ على ﴿عذاب﴾ لإفادة اختصاصهم بهذا العذاب، ووُصف بأنه ﴿عظيم﴾ لعِظم جرمهم، وهو الكفر بآيات الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص155–156، تحت البقرة: 7.","url":""}]},{"id":"s2-28","number":28,"surah":2,"verses":[9],"verseLabel":"البقرة: 7، والسجدة: 9","question":"ما سرّ البدء في البقرة بالقلوب: ﴿ختم الله على قلوبهم وعلى سمعهم﴾، وبدأ في السجدة بالسمع ثم الأبصار ثم الأفئدة؟","answer":"روعي في آية السجدة ترتيب حصول وسائل الإدراك في الوجود؛ فالمسموعات والمبصرات تُكتسب قبل اكتمال التعقل. أما في البقرة فبدأ بالقلوب؛ لأنها الأنسب بسياق مرض القلوب، كما قال بعد ذلك: ﴿في قلوبهم مرض﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص253–254، تحت السجدة: 9، في المقارنة بالبقرة: 7.","url":""}]},{"id":"s2-29","number":29,"surah":2,"verses":[23],"verseLabel":"البقرة: 7، والجاثية: 23","question":"ما سر اختلاف ترتيب القلب والسمع بين قوله في البقرة: ﴿ختم الله على قلوبهم وعلى سمعهم﴾، وقوله في الجاثية: ﴿وختم على سمعه وقلبه﴾؟","answer":"قُدّم السمع في الجاثية لأن السياق سبق بالحديث عن القرآن بوصفه بصائر وهدى، وبالحث على الاتعاظ به؛ فناسب تقديم السمع لبيان عدم قبول النصح والمواعظ الواصلة إليهم. أما البقرة فسياقها الإيمان والكفر، وموضعهما القلب، فقدم القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج55، ص108، تحت الجاثية: 23، في المقارنة بالبقرة: 7.","url":""}]},{"id":"s2-30","number":30,"surah":2,"verses":[46],"verseLabel":"البقرة: 7، والأنعام: 46","question":"ما سرّ تقديم البقرة الختم على القلوب، بينما أخرت الأنعام القلوب في قوله: ﴿أخذ الله سمعكم وأبصاركم وختم على قلوبكم﴾؟","answer":"في البقرة الحديث عن كافرين لا يؤمنون مع الإنذار، والقلب محل الإيمان ووسيلة الإدراك؛ فناسب تقديم الختم عليه. وفي الأنعام المقام مقام تهديد وتخويف، والسمع والبصر آلتا توصيل الأدلة إلى الإيمان؛ فبدأ بأخذهما، وإذا سُلبت الآلة تعطّل عمل القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص699–700، تحت الأنعام: 46.","url":""}]},{"id":"s2-31","number":31,"surah":2,"verses":[8],"verseLabel":"البقرة: 8","question":"لماذا حكى قول المنافقين: ﴿آمنا بالله وباليوم الآخر﴾، ثم قال: ﴿وما هم بمؤمنين﴾؟","answer":"لأنهم قالوا بألسنتهم ما ليس في قلوبهم؛ فحكى دعواهم أولًا، ثم نفى عنهم حقيقة الإيمان. وجاء النفي بالجملة الاسمية ليدل على دوام انتفاء الإيمان عنهم، ماضيًا وحالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص159–164، تحت البقرة: 8.","url":""}]},{"id":"s2-32","number":32,"surah":2,"verses":[8],"verseLabel":"البقرة: 8","question":"ما فائدة الباء في قوله: ﴿وما هم بمؤمنين﴾؟","answer":"دخول الباء على خبر ﴿ما﴾ يؤكد نفي الإيمان عنهم. كما أن حذف متعلَّق الإيمان يفيد العموم؛ فهم ليسوا مؤمنين بشيء مما من شأنه الإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص164، تحت البقرة: 8.","url":""}]},{"id":"s2-33","number":33,"surah":2,"verses":[9],"verseLabel":"البقرة: 9","question":"كيف نُسب إلى المنافقين أنهم ﴿يخادعون الله﴾ مع أن الله لا يُخدع؟","answer":"سمّى فعلهم مخادعةً لله لأنهم أظهروا الإيمان وأبطنوا خلافه، فكانت معاملتهم لله ورسوله معاملة المخادع. والمخادعة من جانب الله هي مجازاتهم على خداعهم، لا أن خداعهم يبلغ الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص165–170، تحت البقرة: 9.","url":""}]},{"id":"s2-34","number":34,"surah":2,"verses":[9],"verseLabel":"البقرة: 9","question":"لماذا عُطف المؤمنون على اسم الله في قوله: ﴿يخادعون الله والذين آمنوا﴾؟","answer":"لأن قول المنافقين: ﴿آمنا بالله وباليوم الآخر﴾ كان خداعًا للمؤمنين، فذُكر المؤمنون الذين توجه إليهم ذلك الخداع، مع بيان أن خداعهم لله ليس على الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص165–170، وج8، ص259–260.","url":""}]},{"id":"s2-35","number":35,"surah":2,"verses":[9],"verseLabel":"البقرة: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يخدعون إلا أنفسهم﴾ مع أنهم يقصدون خداع غيرهم؟","answer":"لأن دائرة الخداع رجعت عليهم؛ فخداعهم أوقعهم في ضرر الدنيا وعذاب الآخرة، ولم يضروا الله ولا المؤمنين. وعلى قراءة ﴿وما يخادعون﴾ يكون الخداع واقعًا منهم وإليهم، فكأن أنفسهم خدعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص165–170، تحت البقرة: 9.","url":""}]},{"id":"s2-36","number":36,"surah":2,"verses":[9],"verseLabel":"البقرة: 9","question":"ما سرّ ختم بقوله: ﴿وما يشعرون﴾؟","answer":"الشعور هو العلم الدقيق أو مبادئ الإدراك؛ فنفى عنهم الشعور لأن خداعهم لأنفسهم أمر خفي لا يتفطنون له.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص165–170، تحت البقرة: 9.","url":""}]},{"id":"s2-37","number":37,"surah":2,"verses":[142],"verseLabel":"البقرة: 9، والنساء: 142","question":"ما سرّ ذكر المؤمنون في قوله بالبقرة: ﴿يخادعون الله والذين آمنوا﴾، ولم يُذكروا في قوله بالنساء: ﴿إن المنافقين يخادعون الله وهو خادعهم﴾؟","answer":"ذُكر المؤمنون في البقرة لأن قول المنافقين قبلها: ﴿آمنا بالله وباليوم الآخر﴾ كان صادرًا منهم خداعًا للذين آمنوا. أما موضع النساء فسبقه وعيد المنافقين والكافرين باجتماعهم في جهنم، ولم يسبق فيه ذكر خداعهم للمؤمنين صراحة؛ لذلك لم يُذكروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص259–260، تحت النساء: 142.","url":""}]},{"id":"s2-38","number":38,"surah":2,"verses":[142],"verseLabel":"البقرة: 9، والنساء: 142","question":"ما الذي يضيفه قوله في النساء: ﴿وهو خادعهم﴾ إلى بيان الخداع في سورة البقرة؟","answer":"بينت البقرة أن خداعهم لا يعود إلا على أنفسهم، وبيّنت النساء أن الله مجازيهم ومعاقبهم على خداعهم. وجاءت ﴿وهو خادعهم﴾ جملة اسمية للدلالة على ثبوت هذه المجازاة واستمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص259–260، تحت النساء: 142.","url":""}]},{"id":"s2-39","number":39,"surah":2,"verses":[10],"verseLabel":"البقرة: 10","question":"ما سرّ التعبير عن النفاق بالمرض في قوله: ﴿في قلوبهم مرض﴾؟","answer":"المرض هنا مرض النفاق والشك، وأصله نقص القوة؛ فحال قلوبهم كحال البدن المريض: ناقصة القوة، مضطربة بين التصديق والإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص171–173، تحت البقرة: 10.","url":""}]},{"id":"s2-40","number":40,"surah":2,"verses":[10],"verseLabel":"البقرة: 10","question":"ما معنى قوله: ﴿فزادهم الله مرضًا﴾؟","answer":"لما كان في قلوبهم مرض النفاق والشك زادهم الله مرضًا؛ أي زادوا شكًّا ونفاقًا بما يتجدد من كفرهم وتكذيبهم، وكانت الزيادة جزاءً لهم على اختيارهم وإصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص171–176، تحت البقرة: 10.","url":""}]},{"id":"s2-41","number":41,"surah":2,"verses":[10],"verseLabel":"البقرة: 10","question":"ما سرّ وصف عذاب المنافقين هنا بأنه ﴿أليم﴾، ووصف عذاب الكافرين قبلها بأنه ﴿عظيم﴾؟","answer":"﴿العظيم﴾ ظاهر العِظم، فناسب مقام الكافرين الظاهرين. أما ﴿الأليم﴾ فهو وجع غير ظاهر، فناسب المنافقين الذين يُبطنون الكفر، كما أن أخلاقهم المنحرفة مؤلمة للمجتمع المسلم؛ فناسب كل لفظ مقامه ومعناه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص176–177، تحت البقرة: 10.","url":""}]},{"id":"s2-42","number":42,"surah":2,"verses":[10],"verseLabel":"البقرة: 10","question":"ما دلالة قوله: ﴿بما كانوا يكذبون﴾؟","answer":"الباء سببية؛ أي لهم عذاب أليم بسبب كذبهم. وتدل ﴿كانوا﴾ مع المضارع على استمرار كذب المنافقين، لا على وقوعه مرة واحدة. وتشمل القراءتان كذبهم في دعوى الإيمان وتكذيبهم النبي والقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص177–178، تحت البقرة: 10.","url":""}]},{"id":"s2-43","number":43,"surah":2,"verses":[11],"verseLabel":"البقرة: 11","question":"لماذا نُص على الأرض في قوله: ﴿لا تفسدوا في الأرض﴾؟","answer":"ذُكرت الأرض لأنها محل نشأة الناس وتصرفهم، ومنها مادة حياتهم، وهي جديرة بأن تكون محل إصلاح لا محل إفساد. ويحتمل أن يراد بها المدينة أولًا، أو جنس الأرض؛ تنبيهًا إلى أن طمع المفسدين لا يقف عند موضع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص181–182، تحت البقرة: 11.","url":""}]},{"id":"s2-44","number":44,"surah":2,"verses":[11],"verseLabel":"البقرة: 11","question":"ما الذي أفاده القصر في قولهم: ﴿إنما نحن مصلحون﴾؟","answer":"أفاد قصر صفة الإصلاح عليهم قصرًا ادعائيًا؛ فكأنهم لا صفة لهم إلا الإصلاح. وهو قصر قلب، لأن الناصح وصف فعلهم بالفساد، فقلبوا الحكم وزعموا أنهم المصلحون. ولم يكتفوا بنفي الفساد، بل أثبتوا لأنفسهم الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص182–183، تحت البقرة: 11.","url":""}]},{"id":"s2-45","number":45,"surah":2,"verses":[12],"verseLabel":"البقرة: 12","question":"ما أثر التوكيد في قوله: ﴿ألا إنهم هم المفسدون﴾؟","answer":"﴿ألا﴾ للاستفتاح والتنبيه، و﴿إن﴾ لتوكيد الحكم، وضمير الفصل ﴿هم﴾ يفيد قصر الإفساد عليهم قصرًا ادعائيًا؛ فجاء الرد أبلغ في إبطال دعواهم أنهم مصلحون.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص184–187، تحت البقرة: 12.","url":""}]},{"id":"s2-46","number":46,"surah":2,"verses":[12],"verseLabel":"البقرة: 12","question":"ما سرّ ختم آية الإفساد بقوله: ﴿ولكن لا يشعرون﴾؟","answer":"لأنهم لا يدركون أن ما يفعلونه هو الإفساد بعينه؛ فنُفي عنهم الشعور، وهو إدراك الأمر الدقيق، لتصوير خفاء حقيقة فسادهم عنهم مع وضوحه في نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص184–187، تحت البقرة: 12.","url":""}]},{"id":"s2-47","number":47,"surah":2,"verses":[13],"verseLabel":"البقرة: 13","question":"من المراد بالناس في قوله: ﴿آمنوا كما آمن الناس﴾؟ وما سرّ التعبير عنهم بهذا اللفظ؟","answer":"المراد بالناس المؤمنون، ولا سيما أصحاب النبي ﷺ. وعُبّر عنهم باسم الناس تعظيمًا لإيمانهم؛ فكأن من عداهم ليسوا من الناس الكاملين، أو لأنهم الناس المعهودون في الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص188–193، تحت البقرة: 13.","url":""}]},{"id":"s2-48","number":48,"surah":2,"verses":[13],"verseLabel":"البقرة: 13","question":"ما سرّ وصف المنافقون المؤمنين بالسفه، ثم رد القرآن الوصف عليهم بقوله: ﴿ألا إنهم هم السفهاء﴾؟","answer":"زعم المنافقون أن إيمان المؤمنين سفه، فرد الله عليهم بأن السفه ثابت فيهم هم؛ لأنهم أضاعوا أنفسهم وخسروا الهدى. وجاء الرد مؤكدًا بـ﴿ألا﴾ و﴿إن﴾ وضمير الفصل ﴿هم﴾ لإبطال دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص188–193، تحت البقرة: 13.","url":""}]},{"id":"s2-49","number":49,"surah":2,"verses":[12,13],"verseLabel":"البقرة: 12–13","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الإفساد: ﴿لا يشعرون﴾، وقوله تعالى في السفه: ﴿لا يعلمون﴾؟","answer":"لأن الإفساد من الأمور المحسوسة التي تدرك آثارها بالشعور، فنفى عنهم الشعور. أما السفه فصفة معنوية لا تُعرف إلا بالنظر والعلم، فناسبها نفي العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص192–193، تحت البقرة: 13.","url":""}]},{"id":"s2-50","number":50,"surah":2,"verses":[14],"verseLabel":"البقرة: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا لقوا الذين آمنوا﴾، وقيل في جانب شياطينهم: ﴿وإذا خلوا إلى شياطينهم﴾؟","answer":"اللقاء بالمؤمنين لا يقتضي موافقتهم، أما الخلو إلى شياطينهم فيكشف صريح ما في نفوسهم ومكان اعتقاداتهم الخبيثة. وتعدية ﴿خلوا﴾ بـ﴿إلى﴾ تفيد انصرافهم وإيواءهم وانتهاءهم إلى شياطينهم، وفي ذلك إيماء إلى مشابهتهم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص195–198، تحت البقرة: 14.","url":""}]},{"id":"s2-51","number":51,"surah":2,"verses":[14],"verseLabel":"البقرة: 14","question":"ما دلالة اختلاف تعبير المنافقين، إذ قالوا للمؤمنين: ﴿آمنا﴾، وقالوا لشياطينهم: ﴿إنا معكم﴾؟","answer":"قصدهم مع المؤمنين الإخبار بتحصيل مطلق الإيمان، فجاءت جملة فعلية. أما مع شياطينهم فأخبروا بحقيقة أمرهم على جهة الثبوت واللزوم، فجاءت الجملة الاسمية المؤكدة: ﴿إنا معكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص198–200، تحت البقرة: 14.","url":""}]},{"id":"s2-52","number":52,"surah":2,"verses":[14],"verseLabel":"البقرة: 14","question":"ما فائدة التوكيد والقصر في قول المنافقين لشياطينهم: ﴿إنا معكم إنما نحن مستهزئون﴾؟","answer":"أكدوا كونهم مع شياطينهم بـ﴿إن﴾ والجملة الاسمية لإفادة الثبوت والدوام. ثم قصروا حالهم مع المؤمنين على الاستهزاء بقولهم: ﴿إنما نحن مستهزئون﴾؛ دفعًا لما قد يقع في نفوس شياطينهم من الشك في حقيقة ولائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص198–200، تحت البقرة: 14.","url":""}]},{"id":"s2-53","number":53,"surah":2,"verses":[15],"verseLabel":"البقرة: 15","question":"كيف يُفهم قوله: ﴿الله يستهزئ بهم﴾؟","answer":"لما ذكر استهزاء المنافقين بالمؤمنين جاء الجواب بأن الله ينتقم منهم ويجازيهم على استهزائهم. فسُمّيت المجازاة باسم فعلهم للمقابلة، وليس المراد وصفًا من أوصاف النقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص202–204، تحت البقرة: 15.","url":""}]},{"id":"s2-54","number":54,"surah":2,"verses":[15],"verseLabel":"البقرة: 15","question":"ما معنى قوله: ﴿ويمدهم في طغيانهم﴾؟","answer":"من معاني المد الزيادة؛ أي يزيدهم في طغيانهم جزاءً على إعراضهم بعد علمهم بالحق. ويحتمل أن يكون المعنى زيادة مدة حياتهم، وهي سبب لازديادهم في الطغيان، وفي ذلك استدراج وإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص204–205، تحت البقرة: 15.","url":""}]},{"id":"s2-55","number":55,"surah":2,"verses":[15],"verseLabel":"البقرة: 15","question":"ما الفرق بين العمه والعمى في قوله: ﴿يعمهون﴾؟","answer":"العمه خاص بالرأي، ومعناه التحير والتردد، فهو أخص من العمى؛ أما العمى فيكون في البصر ويكون في الرأي. فاختير ﴿يعمهون﴾ لوصف حيرتهم في طغيانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص205–206، تحت «العمه والعمى».","url":""}]},{"id":"s2-56","number":56,"surah":2,"verses":[16],"verseLabel":"البقرة: 16","question":"لماذا صُوّر أخذ المنافقين الضلالة وتركهم الهدى بالشراء؟","answer":"شُبّه استبدالهم الضلالة بالهدى بالشراء؛ لأنهم رغبوا في الضلالة رغبة المشتري في السلعة، حتى بذلوا الهدى ثمنًا لها، فكانت تجارتهم أعظم الخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص207–210، تحت البقرة: 16.","url":""}]},{"id":"s2-57","number":57,"surah":2,"verses":[16],"verseLabel":"البقرة: 16","question":"لماذا جُعلت الضلالة مُشترًى وجُعل الهدى ثمنًا في قوله: ﴿اشتروا الضلالة بالهدى﴾؟","answer":"لأن رغبتهم اتجهت إلى الضلالة، فهي السلعة التي طلبوها، وبذلوا في سبيل تحصيلها الهدى رغبةً عنه؛ فصُوّر الهدى ثمنًا والضلالة مشترًى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص208–210، تحت البقرة: 16.","url":""}]},{"id":"s2-58","number":58,"surah":2,"verses":[16],"verseLabel":"البقرة: 16","question":"لماذا أُسند الربح إلى التجارة في قوله: ﴿فما ربحت تجارتهم﴾؟","answer":"هذا إسناد مجازي؛ لأن الذي يربح حقيقة هو التاجر، وإنما أُسند الربح إلى التجارة لتلبسها بالفاعل، أو لأنها سبب الربح والخسارة. وفيه إشارة إلى ترك هذه البيعة؛ فإذا كانت لا تربح، فكيف يُقدم عليها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص210–211، تحت البقرة: 16.","url":""}]},{"id":"s2-59","number":59,"surah":2,"verses":[16],"verseLabel":"البقرة: 16","question":"ماذا أضاف قوله: ﴿وما كانوا مهتدين﴾ بعد قوله: ﴿فما ربحت تجارتهم﴾؟","answer":"نفى عنهم الربح أولًا، ثم نفى عنهم الهداية نفيًا مؤكدًا بالجملة الاسمية و﴿كانوا﴾ الدالة على الدوام والاستمرار؛ فليس من شأن من هذه حاله أن يُتصور منه الاهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص210–212، تحت البقرة: 16.","url":""}]},{"id":"s2-60","number":60,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما سرّ مجيء الموصول مفردًا في قوله: ﴿مثلهم كمثل الذي استوقد نارًا﴾ مع أن الحديث عن جماعة؟","answer":"لأن ﴿الذي﴾ وإن كان مفردًا في اللفظ فهو يعم أفراده، فهو في المعنى جمع. ويحتمل أن يكون التقدير: كمثل الفريق الذي استوقد، ثم روعي لفظ الموصول فأُفرد الضمير، وروعي معناه فجمع بعد ذلك في ﴿بنورهم﴾ و﴿تركهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص217–218، تحت البقرة: 17.","url":""}]},{"id":"s2-61","number":61,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما الذي يفيده لفظ ﴿استوقد﴾ في مشهد المثل؟","answer":"يفيد طلب وقود النار، ويعزز معنى علو النار وارتفاع لهبها وشدة إضاءتها؛ فقد طلب صاحب المثل إيقاد نار عظيمة، ثم ذهبت منفعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص218–219، تحت البقرة: 17.","url":""}]},{"id":"s2-62","number":62,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما دلالة قوله: ﴿أضاءت ما حوله﴾ في المثل؟","answer":"يحتمل أن تكون ﴿ما﴾ مفعولًا به؛ أي أضاءت النار الأماكن والأشياء المحيطة به. ويحتمل أن تكون فاعلًا؛ أي أضاء ما حوله، وفي هذا مبالغة في شدة الإضاءة حتى كأن ما حوله هو الذي أضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص219، تحت البقرة: 17.","url":""}]},{"id":"s2-63","number":63,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما سر قوله: ﴿ذهب الله بنورهم﴾ دون: أذهب الله نورهم؟","answer":"التعدية بالباء دون الهمزة تشعر بدوام ذهاب النور وملازمته؛ لما في الباء من معنى الإمساك، كأنه أُخذ فأُمسك ولم يُرسل بعده، فلا يُتصور رجوعه إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص219–220، تحت البقرة: 17.","url":""}]},{"id":"s2-64","number":64,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿بنورهم﴾ ولم يقل: بنارهم، مع أن المثل بدأ بالنار؟","answer":"لأن المقصود من إيقاد النار حصول النور، فأذهب الله مقصودهم منها. ولأن النار فيها إشراق وإحراق، فأذهب ما فيها من الإشراق وهو النور، وأبقى ما فيها من الإحراق وهو النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص220، تحت البقرة: 17.","url":""}]},{"id":"s2-65","number":65,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما دلالة تنكير الظلمات وجمعها في قوله: ﴿وتركهم في ظلمات﴾؟","answer":"نُكرت الظلمات وجُمعت للتهويل؛ أي تُركوا في ظلمات هائلة اختلت معها حواسهم وانتقصت قواهم، وليست ظلمة واحدة، بل ظلمات يعجز الواصف عن تصوير مبلغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص220–221، تحت البقرة: 17.","url":""}]},{"id":"s2-66","number":66,"surah":2,"verses":[17],"verseLabel":"البقرة: 17","question":"ما فائدة قوله: ﴿وتركهم في ظلمات لا يبصرون﴾ بعد قوله: ﴿ذهب الله بنورهم﴾؟","answer":"الجملة الثانية تقرير لمضمون الأولى وزيادة في كشف الحال التي صاروا إليها؛ فذهاب النور يدل على انعدام الفائدة، ثم جاء وصف تركهم في الظلمات لا يبصرون تذكيرًا بما آلوا إليه وتنبيهًا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص221، تحت البقرة: 17.","url":""}]},{"id":"s2-67","number":67,"surah":2,"verses":[18],"verseLabel":"البقرة: 18","question":"لماذا رتبت أوصاف المنافقين: ﴿صم بكم عمي﴾ بهذا الترتيب؟","answer":"روعي ترتيب ما يقع عند تلقي الوحي: يسمع الإنسان قول الرسول، ثم ينطق ويسأل عن دليل صدقه، ثم يرى الآية؛ فنُفي عن المنافقين الانتفاع بالسمع، ثم بالنطق، ثم بالبصر، وأثبتت لهم أضداد هذه الحواس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص225–226، تحت البقرة: 18.","url":""}]},{"id":"s2-68","number":68,"surah":2,"verses":[18],"verseLabel":"البقرة: 18","question":"ما معنى قوله: ﴿فهم لا يرجعون﴾ في ختام مثل النار؟","answer":"لا يرجعون إلى ضياء يدفع حيرتهم، ولا يرجعون إلى الإيمان بعد أن آمنوا ظاهرًا ثم كفروا. وجاءت الجملة اسمية لتفيد استمرارهم في باطلهم وإصرارهم على غيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص227، تحت البقرة: 18.","url":""}]},{"id":"s2-69","number":69,"surah":2,"verses":[39],"verseLabel":"البقرة: 18، والأنعام: 39","question":"لماذا جاءت صفات البقرة بلا عطف: ﴿صم بكم عمي﴾، وجاءت في الأنعام بالعطف: ﴿صم وبكم في الظلمات﴾؟","answer":"سيقت صفات البقرة بلا عطف لقصد اجتماعها في كل واحد من المنافقين، لا توزيعها بينهم. أما العطف في الأنعام فيحتمل معه التوزيع؛ فيكون بعض المكذبين كالصم وبعضهم كالبكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص624، تحت الأنعام: 39.","url":""}]},{"id":"s2-70","number":70,"surah":2,"verses":[73],"verseLabel":"البقرة: 18، والفرقان: 73","question":"ما سرّ التعبير بقوله تعالى: في البقرة: ﴿عمي﴾، وقيل في الفرقان: ﴿عميانًا﴾؟","answer":"جاءت صيغة ﴿عميانًا﴾ للمبالغة في تصوير عمى المشركين عن الانتفاع بآيات الذكر الحكيم، ودل على المبالغة زيادة النون في الجمع. وناسب ذلك سياق وصف عباد الرحمن بفعل مضاد لفعل المشركين المعرضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص268، تحت الفرقان: 73.","url":""}]},{"id":"s2-71","number":71,"surah":2,"verses":[19],"verseLabel":"البقرة: 19","question":"ماذا يضيف مثل الصيب إلى مثل النار في تصوير حال المنافقين؟","answer":"المثل الناري يبين ضياع أعمال المنافقين وجهودهم، أما المثل المائي فيبين أثر القرآن في فضحهم وكشف حقيقتهم؛ فالمثلان متكاملان، ولكل منهما وجه تشبيه مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص228–231، تحت البقرة: 19–20.","url":""}]},{"id":"s2-72","number":72,"surah":2,"verses":[19],"verseLabel":"البقرة: 19","question":"ما معنى ﴿صيّب﴾ في قوله: ﴿أو كصيّب من السماء﴾، وما دلالة تنكيره؟","answer":"الصيّب هو المطر، وأصل مادته يدل على نزول شيء واستقراره. ونُكّر للتعظيم وبيان النوع؛ أي مطر من نوع هائل كأنه جنس مستقل عن المعهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص229–232، تحت البقرة: 19.","url":""}]},{"id":"s2-73","number":73,"surah":2,"verses":[19],"verseLabel":"البقرة: 19","question":"لماذا رتبت عناصر المثل: ﴿ظلمات ورعد وبرق﴾ بهذا الترتيب؟","answer":"روعي في ترتيبها كثرة وجودها: فالظلام يوجد في الليل مع كل يوم، والرعد أكثر وجودًا من البرق؛ لأن البرق لا يكون إلا مع رعد، وقد يكون الرعد ولا برق معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص233، تحت البقرة: 19.","url":""}]},{"id":"s2-74","number":74,"surah":2,"verses":[19],"verseLabel":"البقرة: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿يجعلون أصابعهم في آذانهم﴾ مع أن الذي يدخل هو الأنامل؟","answer":"أطلق الأصابع وأريدت الأنامل، وهو مجاز مرسل علاقته الكلية؛ للمبالغة في شدة سد المسامع، فكأنهم لو استطاعوا إدخال الإصبع كلها لفعلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص233–234، تحت البقرة: 19.","url":""}]},{"id":"s2-75","number":75,"surah":2,"verses":[19],"verseLabel":"البقرة: 19","question":"ما الذي يصوره قوله: ﴿حذر الموت﴾ بعد جعل الأصابع في الآذان؟","answer":"يبين أن شدة حيرتهم وخوفهم أوهمتهم أن وضع الأصابع في الآذان قد يدفع عنهم الموت؛ فبلغ بهم الهلع أن بالغوا في سد المسامع فرارًا من الصواعق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص233–234، تحت البقرة: 19.","url":""}]},{"id":"s2-76","number":76,"surah":2,"verses":[19],"verseLabel":"البقرة: 19","question":"ما دلالة قوله: ﴿والله محيط بالكافرين﴾ في أثناء المثل؟","answer":"الإحاطة هي الاستيلاء على الشيء من جميع جوانبه بحيث لا يمكن فوته ولا التخلص منه؛ فالله محيط بهم قدرةً وعلمًا. وإظهار وصف ﴿الكافرين﴾ بدل الضمير يفيد الترهيب وبيان أن كفرهم سبب استحقاق العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص229 و234، تحت البقرة: 19.","url":""}]},{"id":"s2-77","number":77,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"ما أثر التعبير بالمضارع في قوله: ﴿يكاد البرق يخطف أبصارهم﴾؟","answer":"جاء ﴿يكاد﴾ مضارعًا لاستحضار قوة البرق وأثره في سلب الأبصار، وجاء ﴿يخطف﴾ مضارعًا لأنه خبر فعل المقاربة والمقصود بيان قرب وقوع الخطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص235–236، تحت البقرة: 20.","url":""}]},{"id":"s2-78","number":78,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا﴾، فاستعملت ﴿كلما﴾ مع الضوء و﴿إذا﴾ مع الظلمة؟","answer":"تدل ﴿كلما﴾ على حرصهم على انتهاز كل فرصة للمشي والمضي؛ فهم يترقبون أدنى فرصة للهرب. أما ﴿إذا﴾ فتفيد تحقق توقفهم عن المشي عند الإظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص236، تحت البقرة: 20.","url":""}]},{"id":"s2-79","number":79,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"ما سرّ التعبير بقوله تعالى: في الضوء: ﴿أضاء لهم﴾، وفي الظلمة: ﴿أظلم عليهم﴾؟","answer":"جاءت المقابلة بين ﴿لهم﴾ و﴿عليهم﴾؛ فالضوء منفعة لهم، والإظلام عقوبة واقعة عليهم. وتتكامل معها المقابلة بين ﴿أضاء﴾ و﴿أظلم﴾، وبين ﴿مشوا﴾ و﴿قاموا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص237، تحت البقرة: 20.","url":""}]},{"id":"s2-80","number":80,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"كيف قوّت المقابلات صورة المنافقين في قوله: ﴿كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا﴾؟","answer":"قابل التعبير بين ثلاثة أزواج: ﴿أضاء﴾ و﴿أظلم﴾، و﴿لهم﴾ و﴿عليهم﴾، و﴿مشوا﴾ و﴿قاموا﴾؛ فاجتماع هذه المقابلات يدل على شدة ما هم فيه من الظلمة والمخاوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص237، تحت البقرة: 20.","url":""}]},{"id":"s2-81","number":81,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"لماذا حُذف مفعول المشيئة في قوله: ﴿ولو شاء الله لذهب بسمعهم وأبصارهم﴾؟","answer":"حذف مفعول المشيئة بعد الشرط شائع لدلالة الجزاء عليه؛ أي: لو شاء الله إذهاب سمعهم لذهب به. والحذف يشوق المتلقي إلى معرفة الجواب، فإذا جاء وقع على نفس مستشرفة فتمكن منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص238، تحت البقرة: 20.","url":""}]},{"id":"s2-82","number":82,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"ما سرّ إفراد السمع وجُمعت الأبصار في ختام المثل؟","answer":"لأن السمع مصدر، والمصادر لا يحسن جمعها، والأبصار يراد بها الأعين الباصرة. ويلائم الجمع سياق المثل؛ فالإضاءة والإظلام والمشي والقيام من توابع البصر المتكررة المتفاوتة، فتعددت متعلقاته، بخلاف السمع فهو واحد باعتبار المسموع والسامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص238، تحت البقرة: 20.","url":""}]},{"id":"s2-83","number":83,"surah":2,"verses":[20],"verseLabel":"البقرة: 20","question":"ما سرّ ختم المثل بقوله: ﴿إن الله على كل شيء قدير﴾؟","answer":"جاءت الفاصلة مؤكدة لمضمون المثل ومبرزة قدرة الله على كل شيء؛ فتؤكد قدرته على إذهاب السمع والأبصار، وتتضمن التهديد والوعيد لمن يصر على باطله ونفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص238–239، تحت البقرة: 20.","url":""}]},{"id":"s2-84","number":84,"surah":2,"verses":[21],"verseLabel":"البقرة: 21","question":"ما مناسبة الانتقال من وصف المؤمنين والكافرين والمنافقين إلى قوله: ﴿يا أيها الناس اعبدوا ربكم﴾؟","answer":"بعد أن ذكر أحوال الأصناف الثلاثة وضرب الأمثال، صلح المقام لخطابهم جميعًا بما ينفعهم إرشادًا ورحمة. ولم يمنع سوء صنيع الكافرين والمنافقين من إعادة إرشادهم ووعظهم؛ ليعلموا أن الإغلاظ عليهم كان حرصًا على صلاحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص241، تحت البقرة: 21–22.","url":""}]},{"id":"s2-85","number":85,"surah":2,"verses":[21],"verseLabel":"البقرة: 21","question":"ما سرّ مجيء النداء عامًا بلفظ ﴿الناس﴾؟","answer":"لأن الخطاب لجميع الناس: مؤمنهم وكافرهم، وقد أُمروا جميعًا بعبادة الله ونُهوا عن الإشراك به. وهو أول نداء في القرآن، يشمل الإنس والجن على القول بعموم لفظ الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص243–245، تحت البقرة: 21.","url":""}]},{"id":"s2-86","number":86,"surah":2,"verses":[21],"verseLabel":"البقرة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿اعبدوا ربكم﴾ باسم الربوبية؟","answer":"لأن اسم الرب يشعر بالتربية بالإحسان والإنعام، وفي ذلك تهييج للمخاطبين على امتثال الأمر. وفيه أيضًا استدلال بربوبيته على استحقاقه العبادة وألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص245–246، تحت البقرة: 21.","url":""}]},{"id":"s2-87","number":87,"surah":2,"verses":[21],"verseLabel":"البقرة: 21","question":"ما فائدة وصف الرب بقوله: ﴿الذي خلقكم والذين من قبلكم﴾؟","answer":"أفاد الوصف وصلته زيادة بيان موجب العبادة، وهو خلق المخاطبين ومن قبلهم، وزاد بيان ما أفادته إضافة ﴿ربكم﴾ من اختصاص الله باستحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص246، تحت البقرة: 21.","url":""}]},{"id":"s2-88","number":88,"surah":2,"verses":[21],"verseLabel":"البقرة: 21","question":"ما فائدة ﴿من﴾ في قوله: ﴿والذين من قبلكم﴾؟","answer":"أفادت توكيد معنى القبلية وتقويته، وأشارت إلى أول الموصوفين بها لأن من معانيها الابتداء. فذِكر الحاضرين وأول المخلوقين يستحضر ما بينهما، فيجمع الخطاب البشرية من مبدئها إلى منتهاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص246، تحت البقرة: 21.","url":""}]},{"id":"s2-89","number":89,"surah":2,"verses":[21],"verseLabel":"البقرة: 21","question":"ما علاقة قوله: ﴿لعلكم تتقون﴾ بالأمر بالعبادة قبله؟","answer":"جاء قوله: ﴿لعلكم تتقون﴾ تعليلًا للأمر بالعبادة؛ أي اعبدوا الله لتحترزوا عن عقابه، أو لتحصل لكم التقوى. وحذف متعلَّق ﴿تتقون﴾ يجيز أن يراد عقابه خاصة أو جميع ما أُمر العبد باتقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص246–247، تحت البقرة: 21.","url":""}]},{"id":"s2-90","number":90,"surah":2,"verses":[22],"verseLabel":"البقرة: 22","question":"ما وجه تشبيه الأرض بالفراش والسماء بالبناء؟","answer":"شُبهت الأرض بالفراش للتمكن من الاستقرار عليها والانتفاع والراحة والسهولة، وشُبهت السماء بالبناء للوقاية من الأضرار النازلة؛ فكما يقي البناء مما يأتي من فوق تقي السماء أضرارًا نازلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص248–249، تحت البقرة: 22.","url":""}]},{"id":"s2-91","number":91,"surah":2,"verses":[22],"verseLabel":"البقرة: 22","question":"لماذا أُظهر لفظ السماء في قوله: ﴿وأنزل من السماء ماء﴾ بعد ذكرها، ولم يقل: وأنزل منها؟","answer":"أُظهر لفظ السماء لاختلاف المراد بالسماءين: فالأولى هي البناء الذي يظهر للناظر أزرق نهارًا، والثانية يراد بها السحاب الذي ينزل منه الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص249، تحت البقرة: 22.","url":""}]},{"id":"s2-92","number":92,"surah":2,"verses":[22],"verseLabel":"البقرة: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿الثمرات﴾ ولم يقل: الثمار أو الثمر؟","answer":"لأن المقصود بالثمرة جماعة الثمر؛ فـ﴿الثمرات﴾ أفراد، وكل فرد منها يشتمل على ثمار، ولذلك تفيد من الكثرة ما لا تفيده ﴿الثمار﴾ أو ﴿الثمر﴾. ثم إن الجمع المحلى باللام يخرج عن حد القلة، فلا يلزم أن يراد به عدد قليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص249–250، تحت البقرة: 22.","url":""}]},{"id":"s2-93","number":93,"surah":2,"verses":[22],"verseLabel":"البقرة: 22","question":"لماذا أُظهر اسم الله في قوله: ﴿فلا تجعلوا لله أندادًا﴾، ولم يقل: فلا تجعلوا له أندادًا؟","answer":"أُظهر اسم الله زيادةً في التقرير، ولتعيين المعبود بالذات بعد أن عُيّن بالصفات السابقة من الخلق والإنعام. وفي ذكر اسم الألوهية تعليل للنهي عن الشرك وبيان استحالة الشركة معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص250–251، تحت البقرة: 22.","url":""}]},{"id":"s2-94","number":94,"surah":2,"verses":[23],"verseLabel":"البقرة: 23","question":"لماذا عُبر بالريب دون الشك في قوله: ﴿وإن كنتم في ريب﴾؟","answer":"للتنبيه على أن جزمهم بمنزلة الريب المستضعف؛ لكمال وضوح أدلة الإعجاز وقوتها، أو للإشارة إلى أن أقصى ما يمكن أن يصدر منهم هو الريب وإن بلغوا غاية المكابرة والمعاندة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص254–255، تحت البقرة: 23.","url":""}]},{"id":"s2-95","number":95,"surah":2,"verses":[23],"verseLabel":"البقرة: 23","question":"ما دلالة قوله: ﴿إن كنتم في ريب﴾، فجعلهم كأنهم داخل الريب؟","answer":"يومئ حرف الجر ﴿في﴾ إلى انغماسهم في الريب وإحاطته بهم إحاطة الظرف بالمظروف. ومع ذلك فالريب واقع في عقولهم الفاسدة، لا في ذات القرآن الكريم، وفي التعبير مبالغة في تنزيه القرآن عن شائبة الريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص255، تحت البقرة: 23.","url":""}]},{"id":"s2-96","number":96,"surah":2,"verses":[23],"verseLabel":"البقرة: 23","question":"ما الفرق بين التعبير بـ﴿نزّلنا﴾ والتعبير بـ«أنزلنا»؟","answer":"التنزيل يكون لما ينزل مفرّقًا أو تدريجيًا، أما الإنزال فلما يكون دفعة واحدة؛ وقد نزل القرآن تدريجيًا بحسب الوقائع والأحداث.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص265، تحت البقرة: 23.","url":""}]},{"id":"s2-97","number":97,"surah":2,"verses":[23],"verseLabel":"البقرة: 23","question":"ما دلالة تنكير ﴿سورة﴾ في قوله: ﴿فأتوا بسورة من مثله﴾؟","answer":"نُكرت ﴿سورة﴾ لبيان النوع، والإيماء إلى اتساع مجال التحدي؛ فالمطلوب الإتيان بمثل أي سورة من سور القرآن، وفي عجزهم عن ذلك غاية التبكيت والتخجيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص257، تحت البقرة: 23.","url":""}]},{"id":"s2-98","number":98,"surah":2,"verses":[23],"verseLabel":"البقرة: 23","question":"ما دلالة قوله: ﴿وادعوا شهداءكم من دون الله﴾؟","answer":"الأمر في ﴿وادعوا شهداءكم﴾ للتعجيز والاستدراج إلى غاية التبكيت؛ فقد أُرخي لهم العنان ليستعينوا بمن يشهد لهم، ثم أُدمج في قوله ﴿من دون الله﴾ توبيخهم على شركهم في أثناء إظهار عجزهم عن معارضة القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص259، تحت البقرة: 23.","url":""}]},{"id":"s2-99","number":99,"surah":2,"verses":[38],"verseLabel":"البقرة: 23، ويونس: 38","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿بسورة من مثله﴾، وقوله تعالى في يونس: ﴿بسورة مثله﴾ من غير ﴿من﴾؟","answer":"وقع التحدي في يونس بسورة مماثلة للقرآن، أما آية البقرة ففيها تنزّل معهم من الإتيان بالمماثل إلى الإتيان بشيء مما يماثل؛ أي شيء من جنس المماثلة على وجه التقريب. وكانت آية البقرة آخر آيات التحدي الأربع نزولًا، فناسب زيادة ﴿من﴾ إظهارًا لعجزهم وتبكيتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص258، تحت البقرة: 23.","url":""}]},{"id":"s2-100","number":100,"surah":2,"verses":[24],"verseLabel":"البقرة: 24","question":"ما فائدة الاعتراض بقوله: ﴿ولن تفعلوا﴾ بين الشرط وجوابه؟","answer":"جيء به للمسارعة إلى بيان عجزهم وتسجيل عجزهم المطلق عن معارضة القرآن؛ فهو اعتراض يؤكد أنهم لن يتمكنوا مما طُلب منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص261، تحت البقرة: 24.","url":""}]},{"id":"s2-101","number":101,"surah":2,"verses":[24],"verseLabel":"البقرة: 24","question":"ما دلالة قرن الناس بالحجارة في وقود النار؟","answer":"في وصف النار بأن وقودها الناس والحجارة زيادة تهويل وتفظيع. وقرن الكافرين بالحجارة لأنهم لازموها في الدنيا حين نحتوها أصنامًا وعبدوها من دون الله، فكان جزاؤهم أن يُقرنوا بها في الآخرة؛ جزاءً من جنس العمل وزيادةً في حسرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص262، تحت البقرة: 24.","url":""}]},{"id":"s2-102","number":102,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"ما مناسبة ذكر جزاء المؤمنين بعد وعيد الكافرين؟","answer":"لما ذكر جزاء أعدائه من الكافرين بسبب موقفهم من القرآن، ناسب أن يذكر جزاء أوليائه من المؤمنين به، على طريقة القرآن في الجمع بين الترغيب والترهيب؛ ليتبين حال الفريقين في الآخرة بعد بيان حالهما في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص266، تحت البقرة: 25.","url":""}]},{"id":"s2-103","number":103,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"ما سرّ التعبير عن أهل البشارة بالموصول: ﴿الذين آمنوا وعملوا الصالحات﴾؟","answer":"للتنبيه على أن سبب التبشير هو ما جاءت به الصلة: الإيمان والعمل الصالح. ففي التعبير بالموصول إشعار بالسببية، وثناء عليهم بأعمالهم القلبية والبدنية؛ إذ البشارة نتيجة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص269، تحت البقرة: 25.","url":""}]},{"id":"s2-104","number":104,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"ما سرّ مجيء الأمر ﴿وبشّر﴾ مفردًا؟","answer":"يحتمل أن يكون الخطاب خاصًا بالنبي ﷺ، وهو الأصل في الخطاب، وفي اختصاصه بالبشارة تفخيم لأمرها وزيادة وثوق بها. ويحتمل أن يكون عامًا لكل من يتأتى خطابه؛ ليقوم كل قادر بهذه البشارة. والوجهان متكاملان: يبدأ النبي ﷺ وتقتدي به أمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص268–269، تحت البقرة: 25.","url":""}]},{"id":"s2-105","number":105,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿آمنوا وعملوا الصالحات﴾ بالماضي؟","answer":"لإفادة تحقق الإيمان والعمل الصالح لدى المؤمنين؛ فالعبارة إخبار عن إيمان وأعمال متحققة، لا عن تجدد ذلك منهم، وفيها تأكيد لسبب التبشير وغاية في الثناء الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص269، تحت البقرة: 25.","url":""}]},{"id":"s2-106","number":106,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"كيف يُفهم قول أهل الجنة عن الثمر: ﴿هَذَا الَّذِي رُزِقْنَا مِنْ قَبْلُ﴾، مع أنه ليس عينه؟","answer":"التقدير: «هذا مثل الذي رزقنا من قبل»، وحُذفت كلمة ﴿مثل﴾ لاستحكام الشبه حتى كأن هذه الثمرة هي تلك؛ فثمر الجنة يشبه بعضه بعضًا في اللون والشكل، ويختلف في الطعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص268 و275–276، تحت البقرة: 25.","url":""}]},{"id":"s2-107","number":107,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"لماذا بُني الفعل للمفعول في قوله: ﴿وأُتوا به متشابهًا﴾؟","answer":"حُذف الفاعل للعلم به، وهم الولدان والخدم بأمر الله تعالى، ولتوجيه النظر إلى الحدث وهو الإتيان وإلى المأتي به وهو الثمر. وفي إظهار الفعل دون الفاعل مزيد تكريم لأهل الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص276، تحت البقرة: 25.","url":""}]},{"id":"s2-108","number":108,"surah":2,"verses":[25],"verseLabel":"البقرة: 25","question":"ممّ طُهرت أزواج أهل الجنة في قوله: ﴿أزواج مطهرة﴾؟","answer":"طُهرت من كل ألوان الدنس الحسي، كالبول والحيض، والمعنوي، كالكذب وسوء الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص268، تحت البقرة: 25.","url":""}]},{"id":"s2-109","number":109,"surah":2,"verses":[100],"verseLabel":"البقرة: 25، والتوبة: 100","question":"ما الفرق بين ﴿تجري من تحتها الأنهار﴾ و﴿تجري تحتها الأنهار﴾؟","answer":"قوله ﴿تجري تحتها الأنهار﴾ يخبر عن مرور الأنهار تحت الأشجار، أما ﴿تجري من تحتها الأنهار﴾ فيفيد أن الماء ينبع ابتداءً من تحتها ثم يجري تحت أشجارها؛ فموضع أثبت ابتداء الجري، والآخر أثبت المرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص272–273، تحت البقرة: 25.","url":""}]},{"id":"s2-110","number":110,"surah":2,"verses":[26],"verseLabel":"البقرة: 26","question":"ما مناسبة ذكر المثل بالبعوضة بعد تحدي المعاندين بالقرآن؟","answer":"لما عجز المعاندون عن التحدي أخذوا يطعنون في القرآن بسبب اشتماله على أمثال بما صغر كالذباب والبعوض؛ فجاءت الآية تنزه الوحي عن طعنهم، وتقرر أن حكمة المثل لا يمنعها صغر الشيء المضروب به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص278، تحت البقرة: 26.","url":""}]},{"id":"s2-111","number":111,"surah":2,"verses":[26],"verseLabel":"البقرة: 26","question":"ما المراد بقوله: ﴿فما فوقها﴾: ما هو أكبر من البعوضة أم أصغر؟","answer":"يحتمل أن يراد ما فوقها في الحجم، أي ما هو أكبر منها، ويحتمل ما فوقها في الحقارة والصغر، أي ما هو أصغر منها. وعلى الوجهين يفيد القيد العموم: أن الله لا يستحيي أن يضرب مثلًا بما صغر أو كبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص282، تحت البقرة: 26.","url":""}]},{"id":"s2-112","number":112,"surah":2,"verses":[26],"verseLabel":"البقرة: 26","question":"ما سرّ قول المؤمنين: ﴿أنه الحق من ربهم﴾ باسم الربوبية؟","answer":"للإشارة إلى أن هذا المثل رحمة من الله ونعمة للمؤمنين؛ فمن ربوبيته الخاصة بهم أنه يربيهم بالإيمان، ويوفقهم له ويكمله لهم، ويدفع عنهم الصوارف الحائلة بينهم وبينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص283–284، تحت البقرة: 26.","url":""}]},{"id":"s2-113","number":113,"surah":2,"verses":[26],"verseLabel":"البقرة: 26","question":"كيف يكون المثل الواحد سببًا لهداية قوم وإضلال آخرين؟","answer":"جعل الله التمثيل سببًا لهداية من يطلب الحق ويقصد اتباعه، وجعله سببًا لإضلال من يطلب الوهم ويتبع هواه؛ ولذلك لا يضل به إلا الخارجين عن طاعته. فالفسق سبب كفرهم، وكفرهم حجبهم عن التفكر والتدبر في المثل حتى جحدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص281 و287، تحت البقرة: 26.","url":""}]},{"id":"s2-114","number":114,"surah":2,"verses":[27],"verseLabel":"البقرة: 27","question":"ما دلالة المضارع في ﴿ينقضون﴾ و﴿يفسدون﴾؟","answer":"يفيد تكرر النقض والإفساد وتجدد وقوعهما واستمرارهم عليهما؛ وفي ذلك تصوير لبشاعة النقض وعدم توانيهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص292 و295، تحت البقرة: 27.","url":""}]},{"id":"s2-115","number":115,"surah":2,"verses":[27],"verseLabel":"البقرة: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿ما أمر الله به أن يوصل﴾ بـ﴿ما﴾؟","answer":"لأن ﴿ما﴾ أعم من «الذي»، فتفيد قطعهم كل ما أمر الله بوصله. وقيل: المراد أصلًا قطع الرحم، ويدخل غيره بطريق الأولى؛ غير أن العموم أنسب بالسياق، وهو يدل على عدم مراعاة أي حق يتصور أن يأمر الله بوصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص294، تحت البقرة: 27.","url":""}]},{"id":"s2-116","number":116,"surah":2,"verses":[27],"verseLabel":"البقرة: 27","question":"ما دلالة القصر في قوله: ﴿أولئك هم الخاسرون﴾؟","answer":"قُصرت صفة الخسارة عليهم مبالغةً في عظم خسارتهم، حتى كأن خسارة غيرهم ليست شيئًا إلى جانبها. وفيه قلب لاعتقادهم؛ إذ ظنوا أنفسهم رابحين فأثبتت الآية لهم الخسران، وجاء ضمير الفصل لتأكيد القصر وتقويته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص296–298، تحت البقرة: 27.","url":""}]},{"id":"s2-117","number":117,"surah":2,"verses":[25],"verseLabel":"البقرة: 27، والرعد: 25","question":"ما سرّ مجيء ﴿الذين ينقضون عهد الله﴾ في البقرة بلا واو، وجاء في الرعد بالواو؟","answer":"في البقرة جاء الموصول بيانًا للفاسقين المذكورين قبله، فلم يحتج إلى الواو. أما في الرعد فانتقل السياق من صفات أولي الألباب الموفين بالعهد إلى أضدادهم الناقضين له، فعُطف الفريق المقابل بالواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص155–156، تحت الرعد: 25.","url":""}]},{"id":"s2-118","number":118,"surah":2,"verses":[25],"verseLabel":"البقرة: 27، والرعد: 25","question":"ما سرّ ختم ناقضو العهد في البقرة بـ﴿الخاسرون﴾، وفي الرعد بـ﴿لهم اللعنة ولهم سوء الدار﴾؟","answer":"قابلت البقرة حالهم بحال المهتدين قبلهم؛ أولئك مفلحون وهؤلاء خاسرون. أما الرعد فقابلت عاقبتهم بعاقبة الموفين بالعهد: لهؤلاء ﴿عقبى الدار﴾، ولأولئك ﴿سوء الدار﴾؛ فناسبت كل خاتمة المقابلة القائمة في سورتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص161–163، تحت الرعد: 25.","url":""}]},{"id":"s2-119","number":119,"surah":2,"verses":[28],"verseLabel":"البقرة: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف تكفرون بالله﴾ ولم يقل: «أتكفرون بالله»؟","answer":"لأن ﴿كيف﴾ تتناول جميع أحوال الشيء، فدل الاستفهام بها على إنكار أن يكون لكفرهم أي حال يصح وقوعه عليها؛ ولذلك كانت أبلغ وأعم في الإنكار من الهمزة. ويحمل الاستفهام كذلك على التعجب والتعجيب والتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص302–303، تحت البقرة: 28.","url":""}]},{"id":"s2-120","number":120,"surah":2,"verses":[28],"verseLabel":"البقرة: 28","question":"لماذا عُطف الإحياء الأول بالفاء، وما بعده بـ﴿ثم﴾؟","answer":"أفادت الفاء التعقيب؛ لأن المخاطبين لم يشعروا بحالهم قبل الإحياء الأول، بل وجدوا أنفسهم أحياء. أما الإماتة والإحياء الثاني والرجوع إلى الله فكل طور منها متراخٍ عما قبله، فناسبه حرف ﴿ثم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص304، تحت البقرة: 28.","url":""}]},{"id":"s2-121","number":121,"surah":2,"verses":[28],"verseLabel":"البقرة: 28","question":"ما دلالة تقديم ﴿إليه﴾ في قوله: ﴿ثم إليه ترجعون﴾؟","answer":"قُدّم الجار والمجرور لإفادة القصر؛ فالرجوع يوم القيامة إلى الله وحده للحساب والجزاء. وفيه إلزام لمن أنكر البعث، وقطع للطمع في الانتفاع بما عُبد من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص305، تحت البقرة: 28.","url":""}]},{"id":"s2-122","number":122,"surah":2,"verses":[17],"verseLabel":"البقرة: 28، والعنكبوت: 17","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ثم إليه ترجعون﴾، وفي العنكبوت: ﴿إليه ترجعون﴾ بلا ﴿ثم﴾؟","answer":"آية العنكبوت تعلل الأمر السابق: ﴿فاعبدوه واشكروا له﴾؛ أي اعبدوه لأنكم إليه ترجعون، فناسب الاتصال بلا عاطف. أما آية البقرة فتعدد أطوار الإنسان: الإحياء ثم الإماتة ثم الإحياء ثم الرجوع؛ فناسبت ﴿ثم﴾ ترتيب هذه الأطوار وتراخي بعضها عن بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص166–167، تحت العنكبوت: 17.","url":""}]},{"id":"s2-123","number":123,"surah":2,"verses":[29],"verseLabel":"البقرة: 29","question":"ما دلالة الانتقال من خلق ما في الأرض إلى تسوية السماوات؟","answer":"هو انتقال من الاستدلال بخلق الأرض إلى ما هو أعظم منه، وفيه ترقٍّ من الأدنى إلى الأعلى؛ لينتبه المخاطب بالمعلوم المشاهد إلى عظيم قدرة الخالق فيما لا يبلغه علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص309–310، تحت البقرة: 29.","url":""}]},{"id":"s2-124","number":124,"surah":2,"verses":[29],"verseLabel":"البقرة: 29","question":"ما دلالة تعدية ﴿استوى﴾ بـ﴿إلى﴾ في قوله: ﴿ثم استوى إلى السماء﴾؟","answer":"ضُمّن ﴿استوى﴾ معنى «قصد» مع بقاء دلالة العلو؛ فالمعنى: علا إلى السماء وقصد إليها. وقد عبّر بعض أهل التفسير عن ذلك بأن الاستواء تضمن معنى القصد والإقبال لأنه عُدي بـ﴿إلى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص310، تحت البقرة: 29.","url":""}]},{"id":"s2-125","number":125,"surah":2,"verses":[29],"verseLabel":"البقرة: 29","question":"كيف عاد ضمير الجمع في ﴿فسواهن﴾ على ﴿السماء﴾ المفردة لفظًا؟","answer":"لأن المراد بلفظ ﴿السماء﴾ الجنس؛ فهو مفرد في اللفظ، جمع في المعنى، ولذلك أعيد عليه الضمير مجموعًا في ﴿فسواهن﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص310، تحت البقرة: 29.","url":""}]},{"id":"s2-126","number":126,"surah":2,"verses":[30],"verseLabel":"البقرة: 30","question":"لماذا أعلم الله الملائكة بقوله: ﴿إني جاعل في الأرض خليفة﴾؟","answer":"إعلامهم ليس طلبًا للمشورة، وإنما هو تمهيد لما سيظهر من حكمة خلق آدم وفضله بالعلم، وتعليم للملائكة أن علمهم محدود بما علمهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص312–324، تحت البقرة: 30.","url":""}]},{"id":"s2-127","number":127,"surah":2,"verses":[30],"verseLabel":"البقرة: 30","question":"ما دلالة اسم الفاعل ﴿جاعل﴾ في قوله: ﴿إني جاعل في الأرض خليفة﴾؟","answer":"اسم الفاعل يدل على تحقق الجعل وثبوته؛ فجاء الخبر في مقام إعلام الملائكة بأمر مقضي، لا في مقام استشارتهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص318–319، تحت البقرة: 30.","url":""}]},{"id":"s2-128","number":128,"surah":2,"verses":[30],"verseLabel":"البقرة: 30","question":"كيف عرفت الملائكة أن الخليفة يفسد في الأرض ويسفك الدماء؟","answer":"ذكر أهل التفسير احتمالات، منها: أن الله أعلمهم بذلك، أو أنهم قاسوه على مخلوقات سبقت في الأرض، أو فهموه من خصائص من مُنح الإرادة والاختيار. فلا يجزم بواحد من هذه الأوجه بلا دليل، وسؤالهم كان لاستكشاف الحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص319–324، تحت البقرة: 30.","url":""}]},{"id":"s2-129","number":129,"surah":2,"verses":[30],"verseLabel":"البقرة: 30","question":"ماذا يصور التعبير بـ﴿يسفك الدماء﴾؟","answer":"السفك هو صب الدم وإراقته؛ فالتعبير يصور القتل في مشهد محسوس، ويكشف بشاعة الإفساد الواقع بإزهاق الأنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص321، تحت البقرة: 30.","url":""}]},{"id":"s2-130","number":130,"surah":2,"verses":[30],"verseLabel":"البقرة: 30","question":"هل كان قول الملائكة: ﴿أتجعل فيها من يفسد فيها... ونحن نسبح بحمدك ونقدس لك﴾ اعتراضًا؟","answer":"لم يكن اعتراضًا على حكم الله، وإنما سؤالًا عن الحكمة وطلبًا للعلم؛ وذكروا تسبيحهم وتقديسهم في سياق السؤال عمن يقع منه الإفساد وسفك الدماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص320–324، تحت البقرة: 30.","url":""}]},{"id":"s2-131","number":131,"surah":2,"verses":[31],"verseLabel":"البقرة: 31","question":"ما دلالة قوله: ﴿وعلم آدم الأسماء كلها﴾؟","answer":"يدل على اختصاص آدم بعلم أسماء المسميات التي عرضت على الملائكة، وهو العلم الذي ظهر به فضله عليهم في هذا المقام. وعموم ﴿كلها﴾ يؤكد شمول ما علّمه الله منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص324–329، تحت البقرة: 31.","url":""}]},{"id":"s2-132","number":132,"surah":2,"verses":[31],"verseLabel":"البقرة: 31","question":"ما دلالة قوله للملائكة: ﴿أنبئوني بأسماء هؤلاء﴾؟","answer":"الإنباء إخبار عن أمر ذي شأن، فجاء مناسبًا لمقام إظهار العلم الذي اختص الله به آدم، وإقامة الحجة على أن علم الملائكة مقصور على ما علمهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص329–333، تحت البقرة: 31.","url":""}]},{"id":"s2-133","number":133,"surah":2,"verses":[33],"verseLabel":"البقرة: 33","question":"ما أثر التصريح باسم آدم في قوله: ﴿يا آدم أنبئهم بأسمائهم﴾؟","answer":"فيه تشريف لآدم وتنويه به في مشهد الملائكة، وإظهار لفضله بالعلم حين أُمر أن ينبئهم بما عجزوا عن الإنباء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص327–333، تحت البقرة: 33.","url":""}]},{"id":"s2-134","number":134,"surah":2,"verses":[33],"verseLabel":"البقرة: 33","question":"ما دلالة ﴿كنتم﴾ في قوله: ﴿وما كنتم تكتمون﴾؟","answer":"تدل ﴿كنتم﴾ على أن الكتمان كان سابقًا مستمرًا قبل ظهور ما أظهره الله في هذا المقام، لا أمرًا نشأ في لحظة الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص334، تحت البقرة: 33.","url":""}]},{"id":"s2-135","number":135,"surah":2,"verses":[34],"verseLabel":"البقرة: 34","question":"كيف أُمر الملائكة بالسجود لآدم مع أن العبادة لا تكون إلا لله؟","answer":"كان السجود امتثالًا لأمر الله وتشريفًا لآدم، لا عبادةً لآدم؛ فالمعبود هو الآمر سبحانه. وكان سجود التحية جائزًا في شرائع سابقة ثم نُهي عنه في شريعة الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص336–342، تحت البقرة: 34.","url":""}]},{"id":"s2-136","number":136,"surah":2,"verses":[34],"verseLabel":"البقرة: 34","question":"كيف استُثني إبليس في قوله: ﴿فسجدوا إلا إبليس﴾ مع أنه ليس من الملائكة؟","answer":"لأنه كان داخلًا في جماعتهم ومأمورًا بالسجود معهم، فصح استثناؤه من جهة دخوله في الأمر وحضوره المشهد. وقيل: الاستثناء منقطع، أي سجد الملائكة لكن إبليس أبى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص339–342، تحت البقرة: 34.","url":""}]},{"id":"s2-137","number":137,"surah":2,"verses":[29,30],"verseLabel":"البقرة: 34، والحجر: 29–30","question":"لماذا أكّد سجود الملائكة في الحجر بقوله: ﴿كلهم أجمعون﴾، ولم يأت هذا التوكيد في البقرة؟","answer":"سبق الأمر في البقرة بيان فضل آدم وتعليمه الأسماء وظهور علمه، فكان امتثال الملائكة مفهومًا من السياق. أما الحجر فسبق السجود وصف مادة خلق آدم من صلصال وحمإ مسنون، فناسب توكيد امتثال الملائكة جميعًا، وألا يتخلف منهم أحد بسبب النظر إلى مادة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص339–340، تحت البقرة: 34.","url":""}]},{"id":"s2-138","number":138,"surah":2,"verses":[74],"verseLabel":"البقرة: 34، وص: 74","question":"ماذا تكشف التعبيرات المختلفة عن موقف إبليس من السجود، ولماذا اكتفت سورة ص بقوله: ﴿واستكبر﴾؟","answer":"تكشف عدم السجود بوصفه الفعل الظاهر، والإباء بوصفه امتناعًا مقصودًا، والاستكبار بوصفه الدافع الباطن. وجمعت البقرة الإباء وعلته، أما سورة ص فاكتفت بالاستكبار لأن سياقها في التحذير من عزة الكافرين وشقاقهم، فناسب ذكر أصل الداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص655–656، تحت ص: 74.","url":""}]},{"id":"s2-139","number":139,"surah":2,"verses":[35],"verseLabel":"البقرة: 35","question":"ماذا يظهر من إباحة الأكل من الجنة كلها، ثم النهي عن شجرة واحدة؟","answer":"يظهر سعة فضل الله ويسر التكليف؛ فقد أباح لهما الأكل الرغد من الجنة حيث شاءا، وقصر النهي على شجرة واحدة، فكان الامتثال يسيرًا والابتلاء بيّنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص342–350، تحت البقرة: 35.","url":""}]},{"id":"s2-140","number":140,"surah":2,"verses":[35],"verseLabel":"البقرة: 35","question":"ما سرّ مجيء النهي بقوله: ﴿ولا تقربا هذه الشجرة﴾، لا بالنهي عن الأكل منها؟","answer":"لأن النهي عن القرب أبلغ؛ فهو يمنع الأكل ويمنع مقدماته والأسباب الموصلة إليه، وفيه مبالغة في التحذير من موضع الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص342–350، تحت البقرة: 35.","url":""}]},{"id":"s2-141","number":141,"surah":2,"verses":[19],"verseLabel":"البقرة: 35، والأعراف: 19","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وكلا منها رغدًا﴾، وفي الأعراف: ﴿فكلا من حيث شئتما﴾؟","answer":"سياق البقرة سياق تعداد للنعم، فجعل السكن والأكل نعمتين مستقلتين فعطف بالواو، وزاد ﴿رغدًا﴾ لبيان سعة الإنعام. أما الأعراف فسياقها أسرع إلى التحذير من إبليس ووقوع الابتلاء، فجعل الأكل مترتبًا على الإسكان بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص43–46، تحت الأعراف: 19.","url":""}]},{"id":"s2-142","number":142,"surah":2,"verses":[36],"verseLabel":"البقرة: 36","question":"لماذا نُسبت زلة آدم وزوجه إلى الشيطان في قوله: ﴿فأزلهما الشيطان عنها﴾؟","answer":"لأنه كان سبب الزلة بوسوسته وتزيينه، فنُسب الفعل إلى سببه؛ ولا ينفي ذلك أن آدم وزوجه باشرا المخالفة ثم تابا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص350–355، تحت البقرة: 36.","url":""}]},{"id":"s2-143","number":143,"surah":2,"verses":[36],"verseLabel":"البقرة: 36","question":"ما سرّ مجيء الأمر بالهبوط للجمع: ﴿اهبطوا﴾ بعد خطاب آدم وزوجه؟","answer":"لأن الخطاب اتسع ليشمل آدم وزوجه وإبليس، وقيل: يشمل ذريتهما تبعًا لهما؛ ولذلك جاء بعده بيان العداوة والاستقرار في الأرض إلى حين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص354–356، تحت البقرة: 36.","url":""}]},{"id":"s2-144","number":144,"surah":2,"verses":[37],"verseLabel":"البقرة: 37","question":"ما دلالة ﴿تلقى﴾ في قوله: ﴿فتلقى آدم من ربه كلمات﴾؟","answer":"التلقي هو الاستقبال والأخذ بقبول؛ وفيه تصوير آدم متقبلًا كلمات ربه التي عُلّم بها طريق التوبة والرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص357، تحت البقرة: 37.","url":""}]},{"id":"s2-145","number":145,"surah":2,"verses":[37],"verseLabel":"البقرة: 37","question":"ما سرّ ذكر آدم وحده في قوله: ﴿فتاب عليه﴾ مع اشتراك زوجه في الزلة؟","answer":"خُص آدم بالذكر لأنه الأصل في القصة والخطاب، وتدخل زوجه معه تبعًا؛ وقد صرحت سورة الأعراف بدعائهما معًا: ﴿ربنا ظلمنا أنفسنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص358، تحت البقرة: 37.","url":""}]},{"id":"s2-146","number":146,"surah":2,"verses":[37],"verseLabel":"البقرة: 37","question":"ما مناسبة ختم قبول توبة آدم بقوله: ﴿إنه هو التواب الرحيم﴾؟","answer":"الفاصلة تعلل قبول التوبة وتفتح باب الرجاء؛ فهو كثير التوبة على عباده، رحيم بهم. وضمير الفصل وتعريف الخبر يفيدان قصر كمال هاتين الصفتين عليه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص358–359، تحت البقرة: 37.","url":""}]},{"id":"s2-147","number":147,"surah":2,"verses":[38],"verseLabel":"البقرة: 38","question":"ما سرّ تكرار الأمر بالهبوط في الآيتين 36 و38؟","answer":"الهبوط الأول متصل بإخراج آدم وزوجه من الجنة عقب الزلة، أما الثاني فاستئناف لبيان ما يترتب على الحياة في الأرض من مجيء الهدى وانقسام الناس إلى متبع ومكذب؛ فليس تكرارًا خاليًا من الفائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص360–369، تحت البقرة: 38.","url":""}]},{"id":"s2-148","number":148,"surah":2,"verses":[38],"verseLabel":"البقرة: 38","question":"ما سرّ إفراد ﴿هدى﴾ في قوله: ﴿فمن تبع هداي﴾؟","answer":"لأن الهدى في أصله واحد صادر من الله، وإن تعددت الكتب والرسل والشرائع؛ فالإفراد يجمع ما يأتي من عند الله في حقيقة واحدة تقابل طرق الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص360–369، تحت البقرة: 38.","url":""}]},{"id":"s2-149","number":149,"surah":2,"verses":[38],"verseLabel":"البقرة: 38","question":"ما دلالة قوله: ﴿فلا خوف عليهم ولا هم يحزنون﴾ بدل «لا يخافون ولا يحزنون»؟","answer":"نفي جنس الخوف أبلغ في استئصال الخوف عنهم، ثم جاءت جملة ﴿ولا هم يحزنون﴾ اسميةً لتقوية نفي الحزن واستمراره. والخوف يتعلق بما يستقبل، والحزن بما مضى، فاستوعب النفي جهتي الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص366–371، تحت البقرة: 38.","url":""}]},{"id":"s2-150","number":150,"surah":2,"verses":[38],"verseLabel":"البقرة: 38","question":"ما سرّ تقديم ﴿مني﴾ في قوله: ﴿فإما يأتينكم مني هدى﴾؟","answer":"الأصل: «يأتينكم هدى مني»، وقُدّم الجار والمجرور للعناية بمصدر الهدى، وللدلالة على أن الهدى الذي تنال به النجاة إنما يأتي من الله؛ فلا يُطلب من غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص364، تحت البقرة: 38.","url":""}]},{"id":"s2-151","number":151,"surah":2,"verses":[123],"verseLabel":"البقرة: 38، وطه: 123","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فمن تبع هداي﴾، وفي طه: ﴿فمن اتبع هداي﴾ بزيادة التاء؟","answer":"﴿تبع﴾ تفيد أصل الاتباع، أما زيادة المبنى في ﴿اتبع﴾ فتشعر بمزيد عناية وتعمل. ولما فصلت طه وسوسة الشيطان وحيلته في إغراء آدم، ناسبها ما يدل على مجاهدة التلبيس، بخلاف إجمال البقرة في قوله: ﴿فأزلهما الشيطان﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص365–366، تحت البقرة: 38.","url":""}]},{"id":"s2-152","number":152,"surah":2,"verses":[38],"verseLabel":"البقرة: 38","question":"ما سرّ تقديم نفي الخوف على نفي الحزن؟","answer":"لأن الخوف من مكروه مستقبل أشد تعلقًا بالنفس وأقوى أثرًا فيها من الحزن على ما فات، فقدم الأهم في مقام الوعد بالأمن، ثم نُفي الحزن ليكتمل الأمن من جهة الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص366–367، تحت البقرة: 38.","url":""}]},{"id":"s2-153","number":153,"surah":2,"verses":[39],"verseLabel":"البقرة: 39","question":"ما دلالة تقديم ﴿فيها﴾ في قوله: ﴿أولئك أصحاب النار هم فيها خالدون﴾؟","answer":"تقديم الجار والمجرور يفيد اختصاص خلودهم بالنار، ويقوي تصوير ملازمتهم لها؛ ثم جاءت الجملة الاسمية مؤكدةً لثبات هذا المصير ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص371–376، تحت البقرة: 39.","url":""}]},{"id":"s2-154","number":154,"surah":2,"verses":[40],"verseLabel":"البقرة: 40","question":"ما دلالة نداء اليهود باسم أبيهم في قوله: ﴿يا بني إسرائيل﴾؟","answer":"فيه تذكير لهم بنسبهم إلى نبي الله يعقوب، واستنهاض لأن يوافقوا سيرة أبيهم في الإيمان والوفاء، مع ما في النداء بهذا الاسم من تهيئة لقبول ما يذكّرون به من النعم والعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص377–384، تحت البقرة: 40.","url":""}]},{"id":"s2-155","number":155,"surah":2,"verses":[40],"verseLabel":"البقرة: 40","question":"ما دلالة المقابلة في قوله: ﴿أوفوا بعهدي أوف بعهدكم﴾؟","answer":"رُتب وفاء الله بوعده لهم على وفائهم بما عهد إليهم من الإيمان والطاعة؛ فجاء الجزاء من جنس العمل، وجمعت المقابلة بين التكليف والوعد في عبارة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص377–384، تحت البقرة: 40.","url":""}]},{"id":"s2-156","number":156,"surah":2,"verses":[40],"verseLabel":"البقرة: 40","question":"ما دلالة تقديم ﴿إياي﴾ في قوله: ﴿وإياي فارهبون﴾؟","answer":"قُدم المفعول لإفادة الاختصاص: لا ترهبوا إلا الله، وجاء تكرار ضمير المتكلم في المنفصل والمتصل لتقوية هذا المعنى وتثبيته في مقام النهي عن الخوف الذي يصد عن الوفاء بالعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص377–384، تحت البقرة: 40.","url":""}]},{"id":"s2-157","number":157,"surah":2,"verses":[40,41],"verseLabel":"البقرة: 40–41","question":"ما سرّ ختم الآية 40 بـ﴿فارهبون﴾، والآية 41 بـ﴿فاتقون﴾؟","answer":"جاءت ﴿فارهبون﴾ بعد التذكير بالنعمة والأمر بالوفاء بالعهد؛ فناسب مقام الترغيب والترهيب. أما الآية التالية فجمعت أمرًا بالإيمان ونواهي عن الكفر وبيع الآيات، وحقيقة التقوى امتثال الأمر واجتناب النهي؛ فناسبها ﴿فاتقون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص386–387، تحت البقرة: 40–41.","url":""}]},{"id":"s2-158","number":158,"surah":2,"verses":[41],"verseLabel":"البقرة: 41","question":"كيف نُهوا عن أن يكونوا ﴿أول كافر به﴾ وقد سبقهم مشركو مكة إلى الكفر؟","answer":"المراد: لا تكونوا أول كافر به من أهل الكتاب أو من قومكم؛ وكان سبقهم إلى الكفر أقبح لأنهم يعرفون صفات النبي ﷺ والكتاب الذي أنزل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص384–389، تحت البقرة: 41.","url":""}]},{"id":"s2-159","number":159,"surah":2,"verses":[41],"verseLabel":"البقرة: 41","question":"ما سرّ وصف ثمن آيات الله بأنه ﴿قليلًا﴾؟","answer":"لأن كل ما يؤخذ عوضًا عن آيات الله قليل، مهما عظم في أعين أصحابه؛ فهو متاع فانٍ، وما يترتب على كتمان الحق وترك الإيمان أعظم منه وأبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص384–389، تحت البقرة: 41.","url":""}]},{"id":"s2-160","number":160,"surah":2,"verses":[42],"verseLabel":"البقرة: 42","question":"ما الصورة في قوله: ﴿ولا تلبسوا الحق بالباطل﴾؟","answer":"أصل اللبس الخلط حتى يشتبه أحد الشيئين بالآخر؛ فصور خلط الحق بالباطل على نحو يمنع الناس من تمييزهما، ويجعل الباطل ساترًا لوجه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص389–397، تحت البقرة: 42.","url":""}]},{"id":"s2-161","number":161,"surah":2,"verses":[42],"verseLabel":"البقرة: 42","question":"ما سرّ الجمع بين لبس الحق وكتمانه؟","answer":"لأنهما طريقتان في إخفاء الهدى عن الناس: يُخلط الحق بالباطل حتى يشتبه، أو يُكتم الحق فلا يظهر أصلًا؛ فجمع النهيان وجهي التحريف والإخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص389–397، تحت البقرة: 42.","url":""}]},{"id":"s2-162","number":162,"surah":2,"verses":[43],"verseLabel":"البقرة: 43","question":"ما سرّ التعبير عن الصلاة بقوله: ﴿أقيموا الصلاة﴾؟","answer":"إقامة الصلاة هي الإتيان بها مستقيمةً مستوفيةً شروطها وأركانها وحقوقها، مع المحافظة عليها؛ فهي أبلغ من مجرد وقوع فعل الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص397، تحت البقرة: 43.","url":""}]},{"id":"s2-163","number":163,"surah":2,"verses":[43],"verseLabel":"البقرة: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿واركعوا مع الراكعين﴾ بعد الأمر بإقامة الصلاة؟","answer":"خُص الركوع بالذكر لأنه ركن ظاهر تتميز به صلاة المسلمين، وقوله ﴿مع الراكعين﴾ يدعوهم إلى الصلاة مع جماعة المؤمنين والدخول في عبادتهم، لا البقاء منفردين على ما ألفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص389–397، تحت البقرة: 43.","url":""}]},{"id":"s2-164","number":164,"surah":2,"verses":[44],"verseLabel":"البقرة: 44","question":"هل النسيان في قوله: ﴿وتنسون أنفسكم﴾ نسيان حقيقي؟","answer":"المراد ترك النفس وإهمالها من البر، فنُزل الترك المتعمد منزلة النسيان؛ وفي التعبير توبيخ على أن يأمروا الناس بالبر ثم يتركوا أنفسهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص398–405، تحت البقرة: 44.","url":""}]},{"id":"s2-165","number":165,"surah":2,"verses":[44],"verseLabel":"البقرة: 44","question":"ما سرّ ختم التوبيخ بقوله: ﴿أفلا تعقلون﴾؟","answer":"لأن العقل يقتضي أن ينتفع الإنسان بعلمه وأن يبدأ نفسه بما يأمر به غيره؛ أما تلاوة الكتاب مع مخالفة ما فيه فمناقضة لما يدل عليه العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص398–405، تحت البقرة: 44.","url":""}]},{"id":"s2-166","number":166,"surah":2,"verses":[45],"verseLabel":"البقرة: 45","question":"كيف تكون الاستعانة بالصبر والصلاة؟","answer":"الصبر يحمل النفس على الثبات أمام ما يشق عليها، والصلاة صلة بالله ومحل دعائه وطلب عونه؛ فجمعهما يهيئ القلب والجوارح للقيام بالتكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص405–412، تحت البقرة: 45.","url":""}]},{"id":"s2-167","number":167,"surah":2,"verses":[45],"verseLabel":"البقرة: 45","question":"إلى ماذا يعود الضمير المفرد في قوله: ﴿وإنها لكبيرة﴾ بعد ذكر الصبر والصلاة؟","answer":"أشهر الوجهين أنه يعود إلى الصلاة لقربها من الضمير، وقيل: يعود إلى الاستعانة المفهومة من قوله ﴿واستعينوا﴾؛ فهي خصلة واحدة وإن كانت بالصبر والصلاة. وعلى الوجهين فالمعنى أن ذلك شاق إلا على الخاشعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص405–412، تحت البقرة: 45.","url":""}]},{"id":"s2-168","number":168,"surah":2,"verses":[46],"verseLabel":"البقرة: 46","question":"ما سرّ التعبير عن يقين الخاشعين بلقاء ربهم بقوله: ﴿يظنون﴾؟","answer":"الظن في العربية يأتي بمعنى اليقين إذا دل السياق عليه، وهو المراد هنا؛ لأن الخشوع والاستعداد للرجوع إلى الله مبنيان على يقينهم باللقاء لا على مجرد الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص405–412، تحت البقرة: 46.","url":""}]},{"id":"s2-169","number":169,"surah":2,"verses":[47],"verseLabel":"البقرة: 47","question":"ما مناسبة إعادة نداء بني إسرائيل وتذكيرهم بالنعمة في الآية 47؟","answer":"استؤنف النداء بعد الأوامر والنواهي السابقة لتجديد تذكيرهم بأصل النعمة وما تقتضيه من امتثال، ثم وُصل ذلك بالتحذير من يوم لا تنفع فيه نفس نفسًا؛ فصار التذكير تمهيدًا للمحاسبة على شكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص412–415، تحت البقرة: 47.","url":""}]},{"id":"s2-170","number":170,"surah":2,"verses":[47,122],"verseLabel":"البقرة: 47 و122","question":"ما سرّ تكرار آية: ﴿يا بني إسرائيل اذكروا نعمتي... وأني فضلتكم على العالمين﴾ في الآيتين 47 و122؟","answer":"جاءت الأولى قبل تفصيل نعم الله عليهم ومواقفهم منها، ثم أعيدت بعد ذلك التفصيل لتختم المقطع بما افتتح به، وتربط تعداد النعم بما تقتضيه من الشكر والاستجابة قبل الانتقال إلى الحديث عن إبراهيم عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص219–223، تحت البقرة: 122.","url":""}]},{"id":"s2-171","number":171,"surah":2,"verses":[48],"verseLabel":"البقرة: 48","question":"ما دلالة تنكير ﴿نفس﴾ و﴿شيئًا﴾ في قوله: ﴿لا تجزي نفس عن نفس شيئًا﴾؟","answer":"التنكير في سياق النفي يفيد العموم؛ فلا تجزي أي نفس عن أي نفس شيئًا، قليلًا كان أو كثيرًا. وبذلك يُقطع التعلق بالنسب أو الجاه أو أي وسيلة يظن أنها تغني يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص415–420، تحت البقرة: 48.","url":""}]},{"id":"s2-172","number":172,"surah":2,"verses":[48,123],"verseLabel":"البقرة: 48 و123","question":"ما سرّ تقديم الشفاعة على الفدية في الآية 48، وقدمت الفدية على الشفاعة في الآية 123؟","answer":"تلحظ الآية الأولى النفس التي تريد إنقاذ غيرها؛ فتبدأ بالشفاعة بما لها من جاه، فإن لم تقبل عرضت الفدية. أما الثانية فتلحظ النفس المذنبة التي تريد إنقاذ نفسها؛ فتقدم ما تملك فدية، فإن لم يقبل التمست شفاعة غيرها. فتغير الترتيب بحسب الجهة الملحوظة في كل آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص230–231، تحت البقرة: 123.","url":""}]},{"id":"s2-173","number":173,"surah":2,"verses":[48,123],"verseLabel":"البقرة: 48 و123","question":"ما سرّ التعبير بقوله تعالى: في الشفاعة مرة: ﴿لا يقبل منها شفاعة﴾، ومرة: ﴿لا تنفعها شفاعة﴾، وقيل في الفدية: ﴿لا يؤخذ منها عدل﴾ و﴿لا يقبل منها عدل﴾؟","answer":"الشفاعة تُقبل من الشافع وتنفع المشفوع له؛ فاختير القبول حين لوحظت النفس المتقدمة بالشفاعة لغيرها، واختير النفع حين لوحظت النفس المحتاجة إليها. وكذلك الفدية تؤخذ ممن يعرضها عن غيره، وتقبل من المذنب إذا قدمها عن نفسه؛ فناسب كل فعل جهة الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص231–232، تحت البقرة: 123.","url":""}]},{"id":"s2-174","number":174,"surah":2,"verses":[49],"verseLabel":"البقرة: 49","question":"ما دلالة ﴿يذبحون أبناءكم ويستحيون نساءكم﴾ في تصوير سوء العذاب؟","answer":"﴿يذبحون﴾ يصور قتل الأبناء بذبحهم، وهي صورة مخصوصة شديدة البشاعة، و﴿يستحيون﴾ تعني يستبقون النساء أحياء للخدمة والإذلال. فجمع التعبيران قتل الأبناء وإبقاء النساء على وجه المهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص420–428، تحت البقرة: 49.","url":""}]},{"id":"s2-175","number":175,"surah":2,"verses":[49],"verseLabel":"البقرة: 49","question":"إلى ماذا يشير قوله: ﴿وفي ذلكم بلاء من ربكم عظيم﴾؟","answer":"يحتمل أن يشير إلى سوء العذاب الذي سامهم إياه آل فرعون، فيكون البلاء محنة، ويحتمل أن يشير إلى إنجاء الله لهم، فيكون البلاء اختبارًا بالنعمة. فالبلاء يكون بالضراء وبالسراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص428–430، تحت البقرة: 49.","url":""}]},{"id":"s2-176","number":176,"surah":2,"verses":[141],"verseLabel":"البقرة: 49، والأعراف: 141","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿نجيناكم﴾، وفي الأعراف: ﴿أنجيناكم﴾؟","answer":"صيغة التفعيل في ﴿نجيناكم﴾ تشعر بالمبالغة أو تكرر أسباب النجاة، فناسبت مقام تعداد النعم في البقرة. أما ﴿أنجيناكم﴾ فتدل على حصول أصل الإنجاء، وناسبت سرد القصة في الأعراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص439–440، تحت الأعراف: 141.","url":""}]},{"id":"s2-177","number":177,"surah":2,"verses":[6],"verseLabel":"البقرة: 49، والأعراف: 141، وإبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يذبحون أبناءكم﴾ في البقرة وإبراهيم، وقيل: ﴿يقتلون أبناءكم﴾ في الأعراف؟","answer":"التقتيل أعم من التذبيح؛ فكل ذبح قتل وليس كل قتل ذبحًا. و﴿يذبحون﴾ تستحضر الصورة الخاصة الأشد في معاملة الأبناء كالذبائح، أما ﴿يقتلون﴾ فتدل على جنس القتل الذي تدخل فيه صوره المختلفة؛ فتتكامل المواضع في تصوير المحنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص559، تحت إبراهيم: 6.","url":""}]},{"id":"s2-178","number":178,"surah":2,"verses":[6],"verseLabel":"البقرة: 49، وإبراهيم: 6","question":"ما سرّ التعبير بقوله تعالى: في البقرة: ﴿يسومونكم سوء العذاب يذبحون أبناءكم﴾ بلا واو، وفي إبراهيم: ﴿ويذبحون أبناءكم﴾ بالواو؟","answer":"في البقرة جاءت جملة ﴿يذبحون أبناءكم﴾ بيانًا وتفسيرًا لسوء العذاب، ففُصلت من غير واو. أما في إبراهيم فعُطفت بالواو لتجعل التذبيح محنة مضافة إلى سائر ألوان سوء العذاب في مقام تذكير موسى قومه بأيام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص424، تحت البقرة: 49.","url":""}]},{"id":"s2-179","number":179,"surah":2,"verses":[50],"verseLabel":"البقرة: 50","question":"ما دلالة الباء في قوله: ﴿فرقنا بكم البحر﴾؟","answer":"تحتمل الباء الملابسة والمصاحبة؛ أي فرقنا البحر وأنتم داخلون فيه، وتحتمل السببية؛ أي بسببكم ولأجل إنجائكم. وعلى الوجهين تربط المعجزة بهم ربطًا مباشرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص430–437، تحت البقرة: 50.","url":""}]},{"id":"s2-180","number":180,"surah":2,"verses":[50],"verseLabel":"البقرة: 50","question":"ما الذي أضافه قوله: ﴿وأنتم تنظرون﴾ إلى مشهد النجاة؟","answer":"أثبت أنهم عاينوا إغراق آل فرعون، فاجتمعت لهم نعمة النجاة ومشاهدة هلاك عدوهم، وكان ذلك أبلغ في اليقين بالمعجزة وأتم في المنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص430–437، تحت البقرة: 50.","url":""}]},{"id":"s2-181","number":181,"surah":2,"verses":[50],"verseLabel":"البقرة: 50","question":"لماذا عبّرت البقرة عن موضع النجاة والإغراق بـ﴿البحر﴾، ويكثر في مشاهد إغراق فرعون لفظ ﴿اليم﴾؟","answer":"يغلب لفظ ﴿اليم﴾ في سياقات الخوف والعقاب والإغراق، أما ﴿البحر﴾ فيناسب سياق النعمة والنجاة. ولما كانت آية البقرة تعدد نعم الله على بني إسرائيل، وجه اللفظ النظر إلى جهة إنجائهم وإن كان المشهد نفسه قد تضمن إغراق عدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص379–380، في الفرق بين البحر واليم.","url":""}]},{"id":"s2-182","number":182,"surah":2,"verses":[51],"verseLabel":"البقرة: 51","question":"ما المراد بقوله: ﴿ثم اتخذتم العجل من بعده﴾؟","answer":"المراد اتخاذ العجل إلهًا ومعبودًا من دون الله بعد غياب موسى؛ فدل السياق على متعلق الاتخاذ، ولم يحتج إلى التصريح بلفظ العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص437–445، تحت البقرة: 51.","url":""}]},{"id":"s2-183","number":183,"surah":2,"verses":[142],"verseLabel":"البقرة: 51، والأعراف: 142","question":"لماذا أجملت البقرة ميقات موسى في ﴿أربعين ليلة﴾، وفصلته الأعراف: ﴿ثلاثين ليلة وأتممناها بعشر﴾؟","answer":"مقام البقرة تعداد النعم والمواقف في إيجاز، فذُكر مجموع الميقات بعد تمامه: أربعين ليلة. أما الأعراف فسياقها تفصيل قصة موسى، فذكرت أصل الموعد ثلاثين ثم إتمامه بعشر؛ فناسب الإجمال مقام البقرة والتفصيل مقام الأعراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص440، تحت البقرة: 51.","url":""}]},{"id":"s2-184","number":184,"surah":2,"verses":[51],"verseLabel":"البقرة: 51","question":"لماذا عُبر عن مدة الميقات بقوله: ﴿أربعين ليلة﴾ لا «أربعين يومًا»؟","answer":"لأن العرب تؤرخ الشهور بالليالي، إذ يظهر الهلال ليلًا، فتجعل الأيام تابعة لليالي في عد المدد. ويلائم ذكر الليل كذلك مقام مناجاة موسى وعبادته؛ فالليل زمن صفاء وخلوة من الشواغل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص440–441، تحت البقرة: 51.","url":""}]},{"id":"s2-185","number":185,"surah":2,"verses":[52],"verseLabel":"البقرة: 52","question":"ما مناسبة قوله بعد اتخاذ العجل: ﴿ثم عفونا عنكم من بعد ذلك﴾؟","answer":"عدّ العفو نعمة أخرى عليهم بعد عظم جرمهم؛ فمع استحقاقهم العقوبة تجاوز الله عنهم وقبل رجوعهم، ليظهر فضله وتقوم عليهم الحجة في وجوب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص437–445، تحت البقرة: 52.","url":""}]},{"id":"s2-186","number":186,"surah":2,"verses":[52],"verseLabel":"البقرة: 52","question":"لماذا عُلّل العفو بقوله: ﴿لعلكم تشكرون﴾؟","answer":"لأن العفو نعمة عظيمة تقتضي الشكر؛ فبعد أن تجاوز الله عن جرمهم كان المنتظر أن يقابلوا هذه النعمة بالاعتراف والطاعة، لا أن يعودوا إلى المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص444، تحت البقرة: 52.","url":""}]},{"id":"s2-187","number":187,"surah":2,"verses":[53],"verseLabel":"البقرة: 53","question":"ما وجه عطف ﴿الفرقان﴾ على ﴿الكتاب﴾؟","answer":"قيل: الفرقان هو الكتاب نفسه، وعطفه من عطف الصفة على الموصوف لإبراز كونه فارقًا بين الحق والباطل. وقيل: المراد به ما أوتي موسى من الحجج والآيات الفارقة؛ فعلى هذا يكون المعطوف غير الكتاب. واللفظ يحتمل الوجهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص445–450، تحت البقرة: 53.","url":""}]},{"id":"s2-188","number":188,"surah":2,"verses":[54],"verseLabel":"البقرة: 54","question":"ما سرّ تقديم موسى قوله: ﴿إنكم ظلمتم أنفسكم باتخاذكم العجل﴾ على أمرهم بالتوبة؟","answer":"ليبين لهم سبب الأمر بالتوبة ويوقظ فيهم الندم؛ إذ لا تصح التوبة حتى يعرف العبد ذنبه ويقر بأنه ظلم نفسه، ثم يقبل على ما أمره الله به من إصلاحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص450–458، تحت البقرة: 54.","url":""}]},{"id":"s2-189","number":189,"surah":2,"verses":[54],"verseLabel":"البقرة: 54","question":"لماذا كانت توبة عبدة العجل أن يقتلوا أنفسهم؟","answer":"لأن عبادة العجل بعد ما شاهدوه من الآيات ذنب عظيم، فجعل الله توبتهم في امتثال هذا الحكم الشاق، وكان ذلك خيرًا لهم عند بارئهم لما يفضي إليه من قبول التوبة والنجاة من عقوبة الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص450–458، تحت البقرة: 54.","url":""}]},{"id":"s2-190","number":190,"surah":2,"verses":[54],"verseLabel":"البقرة: 54","question":"ما مناسبة تكرار اسم الله ﴿بارئكم﴾ في آية التوبة من عبادة العجل؟","answer":"تكراره أوكد وأعلق بالذهن، ويستحضر معنى البارئ الذي أنشأهم. وفيه تنبيه إلى أن الذي قضى بإنشائهم هو الذي أمرهم بهذه التوبة، فواجبهم التسليم له في حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص454، تحت البقرة: 54.","url":""}]},{"id":"s2-191","number":191,"surah":2,"verses":[150],"verseLabel":"البقرة: 54، والأعراف: 150","question":"ما سرّ ذكر قبول توبة عبدة العجل في البقرة ولم يذكر في مشهد رجوع موسى في الأعراف؟","answer":"مقام البقرة تعداد نعم الله على بني إسرائيل، فناسب التصريح بقبول التوبة نعمةً عليهم. أما الأعراف فتفصل غضب موسى وإنكاره على قومه عند رجوعه، فاقتصر ذلك الموضع على ما يلائم شدة المشهد، ويُعلم قبول التوبة من موضع البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص572، تحت الأعراف: 150.","url":""}]},{"id":"s2-192","number":192,"surah":2,"verses":[55],"verseLabel":"البقرة: 55","question":"ما دلالة اللام في قولهم: ﴿لن نؤمن لك حتى نرى الله جهرة﴾؟","answer":"ضُمّن ﴿نؤمن﴾ معنى الإقرار أو الإذعان، فعدي باللام؛ أي لن نقر لك بما تقول، أو لن نذعن لك، حتى نرى الله عيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص461، تحت البقرة: 55.","url":""}]},{"id":"s2-193","number":193,"surah":2,"verses":[55],"verseLabel":"البقرة: 55","question":"إلى ماذا يتعلق النظر في قوله: ﴿فأخذتكم الصاعقة وأنتم تنظرون﴾؟","answer":"حُذف المتعلق ليحتمل أنهم كانوا ينظرون إلى ما حل بهم من الصاعقة، أو ينظر بعضهم إلى بعض كيف يموت، أو إلى الإحياء بعد ذلك. واتساع الحذف يسمح بإرادة هذه المعاني غير المتعارضة، ويؤكد تحقق المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص463، تحت البقرة: 55.","url":""}]},{"id":"s2-194","number":194,"surah":2,"verses":[56],"verseLabel":"البقرة: 56","question":"ما مناسبة قوله بعد بعثهم: ﴿لعلكم تشكرون﴾؟","answer":"بعثهم الله بعد موتهم فكانت حياة جديدة ونعمة عظيمة بعد العقوبة، فناسب أن يُطلب منهم شكر هذه النعمة والاعتراف بفضل من أحياهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص458–466، تحت البقرة: 56.","url":""}]},{"id":"s2-195","number":195,"surah":2,"verses":[57],"verseLabel":"البقرة: 57","question":"ما دلالة ﴿من﴾ في قوله: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"تفيد ﴿من﴾ التبعيض؛ أي كلوا بعض ما رزقناكم من الطيبات، وفي ذلك توسعة وإباحة لا توجب استيعاب الرزق كله. وجمع ﴿طيبات﴾ يدل على تعدد ما أحله الله لهم من الرزق الطيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص466–474، تحت البقرة: 57.","url":""}]},{"id":"s2-196","number":196,"surah":2,"verses":[57],"verseLabel":"البقرة: 57","question":"ما دلالة قوله: ﴿وما ظلمونا ولكن كانوا أنفسهم يظلمون﴾؟","answer":"نفى أن يعود ضرر معصيتهم إلى الله؛ فهو غني عنهم، ثم قدّم ﴿أنفسهم﴾ لبيان أن ظلمهم مقصور عليهم وعاقبته راجعة إليهم. وجاء الاستدراك بـ﴿لكن﴾ لإثبات حقيقة ما وقع بعد نفي الوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص466–474، تحت البقرة: 57.","url":""}]},{"id":"s2-197","number":197,"surah":2,"verses":[160],"verseLabel":"البقرة: 57، والأعراف: 160","question":"ما سرّ مجيء في البقرة: ﴿ظللنا عليكم... وأنزلنا عليكم﴾، وفي الأعراف: ﴿ظللنا عليهم... وأنزلنا عليهم﴾؟","answer":"آية البقرة واقعة في خطاب متصل لبني إسرائيل بدأ بقوله: ﴿يا بني إسرائيل اذكروا نعمتي﴾، فاستمر ضمير الخطاب لمواجهتهم بالنعم. أما الأعراف فكانت الآيات تحكي أحوالهم بضمير الغائب، فجاء التظليل والإنزال على نسق الحكاية، ثم التفت إلى الخطاب في ﴿كلوا﴾ لأنه أمر موجه إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت البقرة: 57، وج14، ص748، تحت الأعراف: 160.","url":""}]},{"id":"s2-198","number":198,"surah":2,"verses":[161],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿خطاياكم﴾، وفي الأعراف: ﴿خطيئاتكم﴾؟","answer":"كلاهما جمع خطيئة، غير أن ﴿خطايا﴾ جمع تكسير يفيد الكثرة في مقام الامتنان بسعة المغفرة، و﴿خطيئات﴾ جمع بالألف والتاء يلائم نظم آية الأعراف. ولا يختلف أصل الوعد بالمغفرة في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص481–490، تحت البقرة: 58–59.","url":""}]},{"id":"s2-199","number":199,"surah":2,"verses":[161],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فكلوا﴾، وفي الأعراف: ﴿وكلوا﴾؟","answer":"في البقرة عُلق الأكل على الدخول، فناسبت الفاء الدالة على التعقيب. وفي الأعراف جاء الأمر بالسكن، والأكل حاصل في أثناء السكن لا مترتبًا عليه ترتبًا مباشرًا، فناسب العطف بالواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص774–776، تحت الأعراف: 161.","url":""}]},{"id":"s2-200","number":200,"surah":2,"verses":[161],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وإذ قلنا ادخلوا﴾، وفي الأعراف: ﴿وإذ قيل لهم اسكنوا﴾؟","answer":"صرحت البقرة بالقائل بإسناد القول إلى ضمير العظمة إظهارًا للمنة، أما الأعراف فبنت الفعل للمفعول للعلم بالقائل، إذ لا يكون هذا الأمر إلا من الله. ويمنع اختلاف الأسلوب تكرار القصة على صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص774، تحت الأعراف: 161.","url":""}]},{"id":"s2-201","number":201,"surah":2,"verses":[161],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ادخلوا هذه القرية﴾، وفي الأعراف: ﴿اسكنوا هذه القرية﴾؟","answer":"الدخول مبدأ الوصول إلى القرية، والسكن هو الإقامة فيها بعد الدخول؛ فذكر كل موضع مرحلة من الحدث، وتكامل التعبيران بدل أن تتكرر القصة بألفاظ واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص774، تحت الأعراف: 161.","url":""}]},{"id":"s2-202","number":202,"surah":2,"verses":[161],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ تقديم البقرة: ﴿وادخلوا الباب سجدًا﴾ على ﴿وقولوا حطة﴾، وعكست الأعراف الترتيب؟","answer":"عُطف الأمران بالواو، وهي لا تقتضي ترتيبًا بينهما؛ فالمطلوب اجتماعهما عند الدخول: خضوع الجسد بالسجود وطلب المغفرة بالقول. وتغيير ترتيب الذكر لا يغير ترتيب الامتثال، بل ينوع عرض القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص775، تحت الأعراف: 161.","url":""}]},{"id":"s2-203","number":203,"surah":2,"verses":[161],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وسنزيد المحسنين﴾ بالواو، وفي الأعراف: ﴿سنزيد المحسنين﴾ بلا واو؟","answer":"عُطف الوعد في البقرة على وعد المغفرة فجمع جزاءين. أما في الأعراف فجاءت الجملة مستأنفة، وفي الاستئناف إبراز للزيادة بوصفها فضلًا مستقلًا من الله بعد المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص775، تحت الأعراف: 161.","url":""}]},{"id":"s2-204","number":204,"surah":2,"verses":[59],"verseLabel":"البقرة: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿فبدل الذين ظلموا﴾، ولم يقل: «فبدلوا»؟","answer":"أظهر الموصول وصلته لتسجيل وصف الظلم عليهم وبيان أن التبديل صدر من الفريق المتصف به، وفيه تعليل لما استحقوه بعد ذلك من إنزال الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص482–484، تحت البقرة: 59.","url":""}]},{"id":"s2-205","number":205,"surah":2,"verses":[162],"verseLabel":"البقرة: 59، والأعراف: 162","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فأنزلنا﴾، وفي الأعراف: ﴿فأرسلنا﴾؟","answer":"﴿أنزلنا﴾ يلحظ جهة مجيء الرجز من السماء، وهو مناسب لتصريح البقرة بعدها بقوله: ﴿من السماء﴾. أما ﴿أرسلنا﴾ فيصور توجيه العذاب وتسليطه عليهم؛ فذكر كل موضع جانبًا من وقوع الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص776، تحت الأعراف: 162.","url":""}]},{"id":"s2-206","number":206,"surah":2,"verses":[162],"verseLabel":"البقرة: 59، والأعراف: 162","question":"ما سرّ إعادة الاسم الظاهر في البقرة: ﴿على الذين ظلموا﴾، وقوله تعالى في الأعراف: ﴿عليهم﴾؟","answer":"أعادت البقرة الموصول لتسجيل موجب العذاب وبيان أن الرجز نزل بسبب ظلمهم، وللمبالغة في تقبيح فعلهم، ولئلا يتوهم أن الرجز عم جميع بني إسرائيل. أما الأعراف فقد صرحت قبل ذلك مباشرةً بـ﴿الذين ظلموا منهم﴾، فكان الضمير كافيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص484، وج14، ص776، تحت الأعراف: 162.","url":""}]},{"id":"s2-207","number":207,"surah":2,"verses":[162],"verseLabel":"البقرة: 59، والأعراف: 162","question":"ما سرّ ختم البقرة بـ﴿بما كانوا يفسقون﴾، والأعراف بـ﴿بما كانوا يظلمون﴾؟","answer":"تكرر وصف الظلم في آية البقرة مرتين، فعدل في ختامها إلى ﴿يفسقون﴾ تجنبًا لتكراره ثالثة، مع أن الفسق يشمل خروجهم عن أمر الله. أما الأعراف فختمت بـ﴿يظلمون﴾ ملاءمة لوصفهم السابق بالظلم وتأكيدًا له في سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص776–777، تحت الأعراف: 162.","url":""}]},{"id":"s2-208","number":208,"surah":2,"verses":[160],"verseLabel":"البقرة: 60، والأعراف: 160","question":"ما الفرق بين ﴿فانفجرت﴾ في البقرة و﴿فانبجست﴾ في الأعراف؟","answer":"الانبجاس أول خروج الماء أو خروجه قليلًا، والانفجار خروجه بكثرة وقوة؛ فعبّرت آية الأعراف عن بداية خروج العيون، وعبّرت البقرة عن تمام تدفقها ووفرة النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص490–500، تحت البقرة: 60.","url":""}]},{"id":"s2-209","number":209,"surah":2,"verses":[60],"verseLabel":"البقرة: 60","question":"ما سرّ تحديد العيون في قوله: ﴿فانفجرت منه اثنتا عشرة عينًا﴾؟","answer":"كانت بعدد أسباط بني إسرائيل الاثني عشر، ليختص كل سبط بعين يعرف منها مشربه، كما دل عليه قوله: ﴿قد علم كل أناس مشربهم﴾؛ وبذلك اندفع التنازع بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص490–500، تحت البقرة: 60.","url":""}]},{"id":"s2-210","number":210,"surah":2,"verses":[160],"verseLabel":"البقرة: 60، والأعراف: 160","question":"ما سرّ اختلاف التعبير بين ﴿استسقى موسى لقومه﴾ في البقرة و﴿استسقاه قومه﴾ في الأعراف؟","answer":"ذكرت الأعراف بدء الحدث بطلب القوم من موسى السقيا، وذكرت البقرة ما ترتب عليه من استسقاء موسى ربه لهم. وناسب البقرة، وهي تعدد النعم، إبراز دعاء موسى وإجابة الله له، بينما فصلت الأعراف مجريات القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص497–498، تحت البقرة: 60.","url":""}]},{"id":"s2-211","number":211,"surah":2,"verses":[160],"verseLabel":"البقرة: 60، والأعراف: 160","question":"ما سرّ التعبير في البقرة بـ﴿فقلنا اضرب بعصاك الحجر﴾، وفي الأعراف بـ﴿وأوحينا إلى موسى... أن اضرب﴾؟","answer":"صرحت البقرة بالقول الإلهي المباشر في مقام تعداد النعم وتشريف موسى وسرعة إجابته، أما الأعراف فذكرت الطريق الذي وصل به الأمر، وهو الوحي، في سياق تفصيل القصة. والقول الإلهي وحي، فلا تعارض بين التعبيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص498، تحت البقرة: 60.","url":""}]},{"id":"s2-212","number":212,"surah":2,"verses":[61],"verseLabel":"البقرة: 61","question":"ما وجه وصف المن والسلوى بقوله: ﴿طعام واحد﴾ مع أنهما شيئان؟","answer":"المراد وحدة النوع المعتاد عندهم وتكرر الطعام على حال واحدة، لا أن المن والسلوى شيء واحد في العدد. وقيل: لأنهما كانا يؤكلان معًا فجعلا بمنزلة طعام واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص500–509، تحت البقرة: 61.","url":""}]},{"id":"s2-213","number":213,"surah":2,"verses":[61],"verseLabel":"البقرة: 61","question":"ما دلالة قولهم لموسى: ﴿ادع لنا ربك﴾ بدل «ربنا»؟","answer":"في إضافة الرب إلى موسى جفاء في الخطاب وضعف استحضار لربوبية الله لهم، وكأن الدعاء شأن موسى وحده؛ مع أن الله ربهم وربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص509، تحت البقرة: 61.","url":""}]},{"id":"s2-214","number":214,"surah":2,"verses":[61],"verseLabel":"البقرة: 61","question":"ما دلالة وصف ما طلبوه بـ﴿الذي هو أدنى﴾، والمن والسلوى بـ﴿الذي هو خير﴾؟","answer":"وصف مطلوبهم بأنه أدنى منزلةً وأقل قدرًا من الطعام الذي اختاره الله لهم وأنزله بلا كلفة؛ فأنكر عليهم استبدال المفضول الفاني بما هو خير منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص506–518، تحت البقرة: 61.","url":""}]},{"id":"s2-215","number":215,"surah":2,"verses":[61],"verseLabel":"البقرة: 61","question":"ما دلالة تنكير ﴿مصرًا﴾ في قوله: ﴿اهبطوا مصرًا﴾؟ وهل المراد مصر المعروفة؟","answer":"على قراءة التنوين يكون المراد أي مصر من الأمصار؛ ففي المدن يوجد ما طلبوه. وقيل: المراد مصر المعروفة، وصُرفت لاعتبارات لغوية. والأقرب مع التنكير حملها على بلد من البلدان، لأن الغرض أن مطلوبهم متيسر في الأمصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص510–518، تحت البقرة: 61.","url":""}]},{"id":"s2-216","number":216,"surah":2,"verses":[112],"verseLabel":"البقرة: 61، وآل عمران: 112","question":"ما سرّ اختلاف التعبير بين ﴿النبيين﴾ في البقرة و﴿الأنبياء﴾ في آل عمران؟","answer":"﴿الأنبياء﴾ جمع تكسير يُلحظ فيه معنى الكثرة، فناسب مقام آل عمران الأشد في تعداد قبائحهم والتشنيع عليهم. أما ﴿النبيين﴾ فجمع سالم جاء ملائمًا لسياق البقرة في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص517–518، تحت البقرة: 61.","url":""}]},{"id":"s2-217","number":217,"surah":2,"verses":[112],"verseLabel":"البقرة: 61، وآل عمران: 112","question":"ما سرّ تعريف ﴿الحق﴾ في البقرة: ﴿بغير الحق﴾، وتنكيره في آل عمران: ﴿بغير حق﴾؟","answer":"التعريف في البقرة يشير إلى الحق المعروف الذي تشرع به العقوبة إذا ثبت، فنفى أن يكون قتلهم داخلًا فيه. أما التنكير في سياق النفي بآل عمران فيعم نفي أي حق لقتلهم من كل وجه، فكان أبلغ في التشنيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص517–518، تحت البقرة: 61.","url":""}]},{"id":"s2-218","number":218,"surah":2,"verses":[62],"verseLabel":"البقرة: 62","question":"ما وجه جمع المؤمنين واليهود والنصارى والصابئين في هذا الوعد؟","answer":"الآية تقرر أن الأسماء والانتسابات وحدها لا تنفع، وإنما العبرة بالإيمان بالله واليوم الآخر والعمل الصالح وفق الوحي الواجب الاتباع. فمن كان قبل بعثة محمد ﷺ لزمه اتباع رسول زمانه، ومن أدرك بعثته فلا يصح إيمانه إلا باتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص523–538، تحت البقرة: 62.","url":""}]},{"id":"s2-219","number":219,"surah":2,"verses":[62],"verseLabel":"البقرة: 62","question":"ما مناسبة اقتران الإيمان بالله بالإيمان باليوم الآخر في الآية؟","answer":"لأن الإيمان بالله أصل التكليف، والإيمان باليوم الآخر يحمل على مراقبة الجزاء، ثم يصدقهما العمل الصالح؛ فجمعت الآية أصل الاعتقاد ومآله وثمرته العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص523–538، تحت البقرة: 62.","url":""}]},{"id":"s2-220","number":220,"surah":2,"verses":[69],"verseLabel":"البقرة: 62، والمائدة: 69","question":"ما سرّ نصب ﴿الصابئين﴾ في البقرة ورفع ﴿الصابئون﴾ في المائدة؟","answer":"نُصبت ﴿الصابئين﴾ في البقرة عطفًا على اسم ﴿إن﴾. أما رفع ﴿الصابئون﴾ في المائدة فعلى الاستئناف عند جمهور المعربين، وخبره محذوف دل عليه ما بعده؛ وفي إخراجه عن نسق المعطوفات تنبيه إلى دخول هذا الفريق، مع بعده، في الحكم إن صح إيمانه وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص538، تحت البقرة: 62.","url":""}]},{"id":"s2-221","number":221,"surah":2,"verses":[17],"verseLabel":"البقرة: 62، والمائدة: 69، والحج: 17","question":"ما سرّ تقديم النصارى على الصابئين في البقرة، وتقديم الصابئين في المائدة والحج؟","answer":"راعت البقرة الرتبة فقدمت النصارى لكونهم أهل كتاب، وراعت آية الحج الترتيب الزمني فقدمت الصابئين لأنهم أسبق. أما المائدة فرفع ﴿الصابئون﴾ على الاستئناف أخر اتصالهم النحوي بالمعطوفات وإن تقدم لفظهم، فاجتمع فيها التنبيه إلى شأنهم مع حفظ ترتيب أهل الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص390–391، تحت الحج: 17.","url":""}]},{"id":"s2-222","number":222,"surah":2,"verses":[69],"verseLabel":"البقرة: 62، والمائدة: 69","question":"ما سرّ ذكر ﴿فلهم أجرهم عند ربهم﴾ في البقرة وحذفه من نظير آية المائدة؟","answer":"أجملت البقرة الجزاء بهذه الجملة. أما المائدة فقد سبق نظيرها بقليل تفصيل الجزاء في قوله: ﴿لكفرنا عنهم سيئاتهم ولأدخلناهم جنات النعيم﴾، فاستغنى السياق عن إعادة الإجمال بعد أن فصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص537–538، تحت البقرة: 62، مع المائدة: 65 و69.","url":""}]},{"id":"s2-223","number":223,"surah":2,"verses":[63],"verseLabel":"البقرة: 63","question":"ما دلالة قوله: ﴿ورفعنا فوقكم الطور﴾ عند أخذ الميثاق؟","answer":"رُفع الطور فوقهم تخويفًا وحملًا لهم على أخذ الميثاق بجد، فصار الجبل المرفوع آية محسوسة على قدرة الله، وتأكيدًا لشدة ما أُخذ عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص545–556، تحت البقرة: 63.","url":""}]},{"id":"s2-224","number":224,"surah":2,"verses":[63],"verseLabel":"البقرة: 63","question":"ما دلالة إفراد ﴿ميثاقكم﴾ مع تعدد ما أُمروا به؟","answer":"لأن الأوامر والنواهي اجتمعت في عهد واحد أُخذ عليهم، فالإفراد باعتبار وحدة الميثاق، وإن تعددت بنوده وما يقتضيه من طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص550، تحت البقرة: 63.","url":""}]},{"id":"s2-225","number":225,"surah":2,"verses":[63],"verseLabel":"البقرة: 63","question":"ما معنى أخذ الكتاب بقوة في قوله: ﴿خذوا ما آتيناكم بقوة﴾؟","answer":"المراد أخذه بجد واجتهاد وعزم على حفظه والعمل بما فيه، لا مجرد حمله باليد أو تلقيه بفتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص545–556، تحت البقرة: 63.","url":""}]},{"id":"s2-226","number":226,"surah":2,"verses":[63,93],"verseLabel":"البقرة: 63 و93","question":"ما سرّ اختلاف التعبير بين ﴿واذكروا ما فيه﴾ عند الميثاق الأول و﴿واسمعوا﴾ عند الميثاق الآخر؟","answer":"سبق الميثاق الأول ذكر إيتاء موسى الكتاب والفرقان، فناسب أمرهم بذكر ما في الكتاب. أما الموضع الآخر فجاء بعد مواجهة اليهود المعاصرين بالقرآن وإعراضهم عنه، فكان ﴿واسمعوا﴾ تعريضًا بالخلف الذين لم يسمعوا سماع قبول، في أثناء حكاية ما قيل لأسلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص553–554، تحت البقرة: 63 و93.","url":""}]},{"id":"s2-227","number":227,"surah":2,"verses":[65],"verseLabel":"البقرة: 65","question":"ما دلالة الأمر في قوله: ﴿كونوا قردة خاسئين﴾؟","answer":"هو أمر تكوين يقع به المراد من غير تراخٍ، فدل على نفاذ القدرة وسرعة المسخ. وأضاف ﴿خاسئين﴾ معنى الصغار والذلة والطرد، فلم يقتصر العقاب على تغير الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص556–563، تحت البقرة: 65.","url":""}]},{"id":"s2-228","number":228,"surah":2,"verses":[66],"verseLabel":"البقرة: 66","question":"ما المراد بقوله: ﴿فجعلناها نكالًا لما بين يديها وما خلفها﴾؟","answer":"جُعلت العقوبة زاجرًا لمن عاصرها وشاهدها ولمن جاء بعدها وبلغه خبرها. وقيل: لما بين يدي القرية وما خلفها من القرى، أو لما تقدم من ذنوبهم وما تأخر؛ وأقرب المعاني امتداد العبرة إلى الحاضرين واللاحقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص556–563، تحت البقرة: 66.","url":""}]},{"id":"s2-229","number":229,"surah":2,"verses":[67],"verseLabel":"البقرة: 67","question":"ماذا يكشف قولهم لموسى: ﴿أتتخذنا هزوًا﴾؟","answer":"استبعدوا أن يكون ذبح البقرة طريقًا إلى كشف القاتل، فواجهوا الأمر بسوء ظن بدل التسليم. واستعاذ موسى أن يكون من الجاهلين؛ لأن الاستهزاء في مقام تبليغ حكم الله جهل لا يليق بنبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص563–568، تحت البقرة: 67.","url":""}]},{"id":"s2-230","number":230,"surah":2,"verses":[67,68,69,70,71,72,73],"verseLabel":"البقرة: 67–73","question":"ما سرّ تقديم قصة ذبح البقرة على ذكر جريمة القتل التي كانت سببًا لها؟","answer":"هذا تقديم في الذكر لا في الوقوع؛ فالقتل والتنازع سبقا الأمر بالذبح. وقُدمت قصة الذبح لأنها موضع المعجزة والنعمة، ولتشويق السامع إلى سبب هذا الأمر الغريب، ثم جاء ذكر القتل ليصل المقدمة بنتيجتها: إحياء القتيل وكشف القاتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص592، تحت البقرة: 72.","url":""}]},{"id":"s2-231","number":231,"surah":2,"verses":[67,68,69,70,71],"verseLabel":"البقرة: 67–71","question":"ما سرّ اختيار ذبح بقرة دون سائر الحيوان في كشف القاتل؟","answer":"اختيرت من جنس العجل الذي عظموه وعبدوه؛ فكان ذبحها إهانةً لما بقي في النفوس من تعظيم هذا الجنس، واختبارًا لامتثالهم، مع جعل جزء منها سببًا لإظهار آية إحياء القتيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص583–584، تحت البقرة: 71.","url":""}]},{"id":"s2-232","number":232,"surah":2,"verses":[68,69,70,71],"verseLabel":"البقرة: 68–71","question":"ما أثر أسئلتهم المتكررة عن صفات البقرة في التكليف؟","answer":"كان الأمر أولًا مطلقًا يصدق على أي بقرة، فلو بادروا لأجزأتهم، لكنهم شددوا بالسؤال فشُدد عليهم بتوالي الصفات حتى ضاقت دائرة الاختيار. وفي ذلك ذم للتعنت وكثرة السؤال بغير حاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص568–588، تحت البقرة: 68–71.","url":""}]},{"id":"s2-233","number":233,"surah":2,"verses":[69],"verseLabel":"البقرة: 69","question":"ما دلالة قوله في وصف البقرة: ﴿صفراء فاقع لونها تسر الناظرين﴾؟","answer":"﴿فاقع﴾ وصف لشدة صفرة لونها وخلوصه، وإسناد السرور إلى البقرة مجاز عقلي؛ لأنها سبب سرور الناظرين بحسن لونها وصفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص567–571، تحت البقرة: 69.","url":""}]},{"id":"s2-234","number":234,"surah":2,"verses":[70],"verseLabel":"البقرة: 70","question":"ما أثر قولهم: ﴿وإنا إن شاء الله لمهتدون﴾ بعد تكرر أسئلتهم؟","answer":"علقوا اهتداءهم إلى البقرة المطلوبة بمشيئة الله بعد أن تشابه البقر عليهم؛ فكان الاستثناء إظهارًا للافتقار إليه، وقيل: كان سببًا لأن ييسر الله لهم الاهتداء إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص576، تحت البقرة: 70.","url":""}]},{"id":"s2-235","number":235,"surah":2,"verses":[71],"verseLabel":"البقرة: 71","question":"ما سرّ تقديم الوصف ﴿لا ذلول﴾ على قوله: ﴿تثير الأرض ولا تسقي الحرث﴾؟","answer":"﴿لا ذلول﴾ هو الوصف العام؛ أي لم تذلل للعمل، ثم ذُكر من أفراد العمل إثارة الأرض وسقي الحرث. فقدم الأصل الجامع ثم فصل مظهرين منه، ليتبين أنها مصونة عن جنس الاستخدام كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص584–585، تحت البقرة: 71.","url":""}]},{"id":"s2-236","number":236,"surah":2,"verses":[73],"verseLabel":"البقرة: 73","question":"ما دلالة إبهام الجزء في قوله: ﴿اضربوه ببعضها﴾؟","answer":"لم يتعلق الغرض بتعيين جزء من البقرة، وإنما بإظهار قدرة الله على إحياء القتيل؛ فالإبهام يصرف النظر عن خصوص المادة إلى الآية الواقعة بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص593–600، تحت البقرة: 73.","url":""}]},{"id":"s2-237","number":237,"surah":2,"verses":[73],"verseLabel":"البقرة: 73","question":"ما دلالة الانتقال من إحياء القتيل إلى قوله: ﴿كذلك يحيي الله الموتى﴾؟","answer":"جعل إحياء القتيل دليلًا محسوسًا على إمكان البعث العام؛ فكما أحيا الله هذه النفس بعد موتها يحيي الموتى جميعًا، ثم يري عباده آياته ليعقلوا دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص593–600، تحت البقرة: 73.","url":""}]},{"id":"s2-238","number":238,"surah":2,"verses":[74],"verseLabel":"البقرة: 74","question":"ما سرّ تشبيه قلوبهم بالحجارة ثم الترقي إلى قوله: ﴿أو أشد قسوة﴾؟","answer":"الحجارة مضرب المثل في الصلابة، فشُبهت بها القلوب في قسوتها، ثم رُقي إلى أنها أشد؛ لأن من الحجارة ما يتفجر منه الماء أو يشقق أو يهبط من خشية الله، أما تلك القلوب فلا تلين للآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص600–615، تحت البقرة: 74.","url":""}]},{"id":"s2-239","number":239,"surah":2,"verses":[74],"verseLabel":"البقرة: 74","question":"ما دلالة إسناد الخشية إلى الحجارة في قوله: ﴿وإن منها لما يهبط من خشية الله﴾؟","answer":"أُسند الهبوط إلى خشية الله تصويرًا لخضوع الحجارة لأمره وانقيادها لما أودع فيها، وفي ذلك زيادة تقريع للقلوب التي عرفت الآيات ثم لم تلن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص615، تحت البقرة: 74.","url":""}]},{"id":"s2-240","number":240,"surah":2,"verses":[74],"verseLabel":"البقرة: 74","question":"ما دلالة ﴿أو﴾ في قوله: ﴿فهي كالحجارة أو أشد قسوة﴾؟","answer":"ليست للشك، وإنما هي باعتبار تقدير المخاطب: من رآها كالحجارة أصاب، ومن رآها أشد قسوة أصاب. وقيل: للإبهام على السامع في أول الأمر ثم الترقي به إلى الحكم الأشد، وفي الحالين لا تعلق لها بالشك في علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص607–608، تحت البقرة: 74.","url":""}]},{"id":"s2-241","number":241,"surah":2,"verses":[74],"verseLabel":"البقرة: 74","question":"ما سرّ التعبير بـ﴿أشد قسوة﴾ بدل «أقسى»؟","answer":"لأن ﴿أشد قسوة﴾ يبرز القسوة نفسها ويصف بلوغها مبلغًا شديدًا، وفي لفظ ﴿أشد﴾ معنى المبالغة من مادته وصيغته، بخلاف «أقسى» الذي يدل على التفضيل بصيغته وحدها؛ فكان التركيب أبلغ في التشنيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص608، تحت البقرة: 74.","url":""}]},{"id":"s2-242","number":242,"surah":2,"verses":[75],"verseLabel":"البقرة: 75","question":"ما سرّ التعبير في قوله: ﴿ثم يحرفونه من بعد ما عقلوه﴾، لا بمجرد السماع؟","answer":"لأن العقل هنا فهم الكلام وإدراك معناه؛ فتحريفه بعد فهمه أبلغ في الذم من تغييره بعد سماع لا يصحبه علم، إذ يثبت أنهم فعلوه عن معرفة وعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص616–623، تحت البقرة: 75.","url":""}]},{"id":"s2-243","number":243,"surah":2,"verses":[75],"verseLabel":"البقرة: 75","question":"ما سرّ تعدية ﴿يؤمنوا﴾ باللام في قوله: ﴿أفتطمعون أن يؤمنوا لكم﴾؟","answer":"ضُمّن الإيمان معنى الإقرار أو الإذعان، فعدي باللام؛ أي أتطمعون أن يقروا لكم ويذعنوا لما تدعونهم إليه؟ فالمقصود ليس مجرد المعرفة الباطنة، بل قبول الحق والانقياد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص621، تحت البقرة: 75.","url":""}]},{"id":"s2-244","number":244,"surah":2,"verses":[76],"verseLabel":"البقرة: 76","question":"ما دلالة ﴿خلا إلى﴾ في قوله: ﴿وإذا خلا بعضهم إلى بعض﴾؟","answer":"تدل على الانفراد والانصراف المقصود إلى بعضهم بعيدًا عن غيرهم؛ فصورت خلوهم في مجلس خاص يتراجعون فيه عما أظهروه للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص623–630، تحت البقرة: 76.","url":""}]},{"id":"s2-245","number":245,"surah":2,"verses":[77],"verseLabel":"البقرة: 77","question":"ما دلالة المضارع في قوله: ﴿يعلم ما يسرون وما يعلنون﴾؟","answer":"يفيد تجدد علمه بكل ما يجددونه من إسرار وإعلان، واستحضار إحاطته الدائمة بباطن قولهم وظاهره؛ فلا يخفى عليه اختلاف أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص630–637، تحت البقرة: 77.","url":""}]},{"id":"s2-246","number":246,"surah":2,"verses":[77],"verseLabel":"البقرة: 77","question":"ما سرّ مقابلة الإسرار بالإعلان في قوله: ﴿ما يسرون وما يعلنون﴾؟","answer":"بينهما طباق يستوعب طرفي الخفاء والظهور، فيدل على إحاطة العلم بما خفي في الصدور وما ظهر في القول والعمل. والإعلان إظهار الشيء وإشاعته، فهو مقابل مناسب للإسرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص637–639، تحت البقرة: 77.","url":""}]},{"id":"s2-247","number":247,"surah":2,"verses":[77,284],"verseLabel":"البقرة: 77 و284","question":"ما سرّ تقديم السر في ﴿ما يسرون وما يعلنون﴾، وتقديم الإبداء في ﴿وإن تبدوا ما في أنفسكم أو تخفوه﴾؟","answer":"آية 77 في بيان إحاطة العلم، فقدم الأخفى لأن العلم به أدل على الإحاطة، ولأن المعلن يسبقه غالبًا ما يضمر في النفس. أما آية 284 ففي مقام المحاسبة، فقدم الظاهر الذي تبدأ به المؤاخذة في تصور المخاطب، ثم شمل ما خفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص635–636، تحت البقرة: 77.","url":""}]},{"id":"s2-248","number":248,"surah":2,"verses":[78],"verseLabel":"البقرة: 78","question":"ما دلالة وصف الأميين بقوله تعالى: ﴿لا يعلمون الكتاب إلا أماني﴾، مع أن الأماني ليست علمًا؟","answer":"قيل: الاستثناء منقطع؛ أي لا يعلمون الكتاب، لكن غاية ما عندهم أماني وتلاوة بلا فهم. وقيل: متصل على سبيل التهكم، فنزلت أمانيهم منزلة العلم لأنها حظهم الوحيد منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص639–646، تحت البقرة: 78.","url":""}]},{"id":"s2-249","number":249,"surah":2,"verses":[79],"verseLabel":"البقرة: 79","question":"ما سرّ تكرار الوعيد في قوله: ﴿فويل لهم مما كتبت أيديهم وويل لهم مما يكسبون﴾؟","answer":"لأن الجريمة ذات جانبين: كتابة الباطل ونسبته إلى الله، ثم تحصيل الكسب المحرم به. فاستقل كل جانب بوعيد؛ الأول على الوسيلة المزورة، والثاني على ما اتخذوه منها من منفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص651، تحت البقرة: 79.","url":""}]},{"id":"s2-250","number":250,"surah":2,"verses":[79],"verseLabel":"البقرة: 79","question":"ما سرّ الماضي في ﴿مما كتبت أيديهم﴾ والمضارع في ﴿مما يكسبون﴾؟","answer":"جاءت الكتابة بالماضي لأنها وقعت وثبت بها استحقاق الوعيد، وجاء الكسب بالمضارع لتصوير تجدده واستمراره؛ إذ تتجدد منافع التحريف وآثاره ما دام الناس يعملون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص651–652، تحت البقرة: 79.","url":""}]},{"id":"s2-251","number":251,"surah":2,"verses":[80],"verseLabel":"البقرة: 80","question":"ما سرّ التعبير بالمس في قولهم: ﴿لن تمسنا النار إلا أيامًا معدودة﴾؟","answer":"اختاروا المس، وهو أخف اتصال، تهوينًا للعذاب في زعمهم؛ فلم يذكروا الدخول أو المكث، وزادوا قصره على أيام معدودة، فكشف التعبير مبلغ اغترارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص653–659، تحت البقرة: 80.","url":""}]},{"id":"s2-252","number":252,"surah":2,"verses":[80],"verseLabel":"البقرة: 80","question":"ما دلالة وصف الأيام بأنها ﴿معدودة﴾؟","answer":"يدل على القلة وسهولة الإحصاء، ويصور زعمهم أن مدة العذاب محددة تنقضي سريعًا؛ فجمعوا في دعواهم بين خفة المس وقصر الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص653–659، تحت البقرة: 80.","url":""}]},{"id":"s2-253","number":253,"surah":2,"verses":[24],"verseLabel":"البقرة: 80، وآل عمران: 24","question":"ما سرّ وصف ﴿أيامًا﴾ بالمفرد ﴿معدودة﴾ في البقرة، وبالجمع ﴿معدودات﴾ في آل عمران؟","answer":"جاء موضع البقرة أوجز في نقل دعواهم، فناسبه الوصف المفرد الذي يجوز مع جمع غير العاقل. أما آل عمران فبسطت قبائحهم وإعراضهم، فناسب البسط جمع الوصف في ﴿معدودات﴾، مع اتحاد أصل المعنى وهو ادعاء قلة الأيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص654–655، تحت البقرة: 80.","url":""}]},{"id":"s2-254","number":254,"surah":2,"verses":[81,82],"verseLabel":"البقرة: 81–82","question":"ما وجه المقابلة بين أصحاب السيئة وأصحاب الإيمان والعمل الصالح في الآيتين 81 و82؟","answer":"قابلت الآيتان من كسب السيئة حتى أحاطت به خطيئته بمن آمن وعمل الصالحات؛ فهناك سيئة مستولية تقود إلى النار، وهنا إيمان تصدقه الأعمال يقود إلى الجنة. وبالمقابلة يظهر اختلاف السبب والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص659–668، تحت البقرة: 81–82.","url":""}]},{"id":"s2-255","number":255,"surah":2,"verses":[81],"verseLabel":"البقرة: 81","question":"ما الصورة في قوله: ﴿وأحاطت به خطيئته﴾؟","answer":"صُورت الخطيئة بشيء يحيط بصاحبه من جميع الجهات فلا يترك له منفذًا؛ فالوعيد لمن استولت عليه خطيئته وملكته، لا لمن وقع في ذنب ثم تاب وأصلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص659–668، تحت البقرة: 81.","url":""}]},{"id":"s2-256","number":256,"surah":2,"verses":[83],"verseLabel":"البقرة: 83","question":"ما سرّ التعبير بالمصدر في قوله: ﴿وبالوالدين إحسانًا﴾؟","answer":"ناب المصدر ﴿إحسانًا﴾ عن فعل الأمر؛ أي أحسنوا بالوالدين إحسانًا. وفي العدول إلى المصدر مبالغة في طلب الإحسان وتوكيد له، كأن الإحسان نفسه هو المطلوب الثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص668–678، تحت البقرة: 83.","url":""}]},{"id":"s2-257","number":257,"surah":2,"verses":[83],"verseLabel":"البقرة: 83","question":"ما دلالة الإفراد في قوله: ﴿وذي القربى﴾؟","answer":"﴿ذو القربى﴾ اسم جنس يصدق على كل من له قرابة، فالمفرد هنا عام في أفراد الأقارب، ولم يُرد به قريب واحد بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص675، تحت البقرة: 83.","url":""}]},{"id":"s2-258","number":258,"surah":2,"verses":[36],"verseLabel":"البقرة: 83، والنساء: 36","question":"ما سرّ عدم إعادة الباء في البقرة: ﴿وبالوالدين إحسانًا وذي القربى﴾، وإعادتها في النساء: ﴿وبذي القربى﴾؟","answer":"أعادت النساء الباء لإبراز أن لذي القربى حقًا مستقلًا في الإحسان، غير تابع لوجود الوالدين، ولمزيد العناية بحق القريب. وناسب هذا التوكيد خطاب هذه الأمة، بينما جاءت البقرة في حكاية ميثاق بني إسرائيل فعطفت القريب على الوالدين من غير إعادة الحرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص140، تحت النساء: 36.","url":""}]},{"id":"s2-259","number":259,"surah":2,"verses":[83],"verseLabel":"البقرة: 83","question":"ما سرّ مجيء النهي في صورة الخبر: ﴿لا تعبدون إلا الله﴾؟","answer":"أُخرج التكليف في صورة خبر مبالغةً في توكيده، حتى كأن امتثالهم له أمر محقق يُخبر عنه. وفي ذلك حث على الوفاء بالميثاق، وإشعار بأن توحيد الله لا ينبغي أن يقع منهم خلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص671–672، تحت البقرة: 83.","url":""}]},{"id":"s2-260","number":260,"surah":2,"verses":[84],"verseLabel":"البقرة: 84","question":"ما سرّ التعبير عن دماء غيرهم وديارهم بقوله: ﴿دماءكم﴾ و﴿أنفسكم من دياركم﴾؟","answer":"جعل أهل الملة والجماعة بمنزلة النفس الواحدة؛ فمن سفك دم أخيه أو أخرجه فقد اعتدى على نفسه، لما بينهم من وحدة، ولما يجره الاعتداء من قصاص وتفكك يعود ضرره على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص678–700، تحت البقرة: 84–85.","url":""}]},{"id":"s2-261","number":261,"surah":2,"verses":[84,85],"verseLabel":"البقرة: 84–85","question":"ما سرّ التعبير أولًا بـ﴿لا تسفكون دماءكم﴾، ثم وصف فعلهم بقوله: ﴿تقتلون أنفسكم﴾؟","answer":"سفك الدم أعم، فيشمل القتل والجراح وكل إراقة للدم، فناسب الميثاق الذي يمنع جنس الاعتداء. ثم خُص القتل عند وصف فعلهم لأنه أقبح صور السفك التي انتهكوا بها العهد؛ فانتقل من العام إلى أشد أفراده.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص690–691، تحت البقرة: 84–85.","url":""}]},{"id":"s2-262","number":262,"surah":2,"verses":[84,85],"verseLabel":"البقرة: 84–85","question":"ما سرّ التعبير في الميثاق بـ﴿ولا تخرجون أنفسكم من دياركم﴾، وعند وصف الفعل بـ﴿وتخرجون فريقًا منكم من ديارهم﴾؟","answer":"صاغ الميثاق إخراج بعضهم كأنه إخراج للنفس لما بينهم من وحدة الدين والجماعة، ثم فصّل الواقع فبيّن أنهم أخرجوا فريقًا معينًا منهم من دياره. فانتقل من تصوير حرمة الفعل إلى تسجيل من وقع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص691–692، تحت البقرة: 84–85.","url":""}]},{"id":"s2-263","number":263,"surah":2,"verses":[85],"verseLabel":"البقرة: 85","question":"ما دلالة وصف أخذ بعض أحكام الكتاب وترك بعضها بالإيمان والكفر؟","answer":"لأن امتثال بعض الأحكام إقرار بها، وترك بعضها جحود لسلطانها أو إعراض عنه؛ فسمى الموقف بحسب حقيقته: إيمانًا ببعض الكتاب وكفرًا ببعض، لا مجرد طاعة ومعصية عارضتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص686–700، تحت البقرة: 85.","url":""}]},{"id":"s2-264","number":264,"surah":2,"verses":[70],"verseLabel":"البقرة: 85، والأنفال: 70","question":"ما الفرق بين ﴿أُسارى﴾ في البقرة و﴿أسرى﴾ في الأنفال؟","answer":"كلاهما جمع أسير، وقيل: ﴿أسرى﴾ لمن كان في الأسر، و﴿أُسارى﴾ لمن اشتد عليه الأسر والوثاق. فناسب ﴿أسرى﴾ أسرى بدر الذين صاروا في يد المسلمين، وناسب ﴿أُسارى﴾ من جيء بهم في حال الضعف ليفادوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص465–466، تحت الأنفال: 70.","url":""}]},{"id":"s2-265","number":265,"surah":2,"verses":[85],"verseLabel":"البقرة: 85","question":"ما دلالة توالي الأفعال المضارعة في وصف اعتدائهم في الآية 85؟","answer":"تستحضر صيغة المضارع أفعالهم كأنها تقع أمام السامع، وتدل على تجدد هذا المسلك واستمرارهم عليه: يقتلون ويخرجون ويتظاهرون ثم يفادون، ويؤمنون ببعض الكتاب ويكفرون ببعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص691، تحت البقرة: 85.","url":""}]},{"id":"s2-266","number":266,"surah":2,"verses":[85],"verseLabel":"البقرة: 85","question":"ما سرّ التعبير بنفي الغفلة في قوله: ﴿وما الله بغافل عما تعملون﴾؟","answer":"لأن تماديهم في المخالفة يشبه فعل من يظن أن عمله يفوت علم الله وجزاءه، فجاء نفي الغفلة تهديدًا بأن أعمالهم كلها محفوظة وسيحاسبون عليها. وهو أوقع في مقام الوعيد من مجرد الإخبار بالعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص698–699، تحت البقرة: 85.","url":""}]},{"id":"s2-267","number":267,"surah":2,"verses":[86],"verseLabel":"البقرة: 86","question":"ما الصورة في قوله: ﴿اشتروا الحياة الدنيا بالآخرة﴾؟","answer":"صُور إيثارهم الدنيا على الآخرة بصفقة جعلوا فيها الآخرة ثمنًا للدنيا؛ فدل الشراء على قصدهم واختيارهم، وكشف فداحة الخسارة في مبادلة الباقي بالفاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص700–705، تحت البقرة: 86.","url":""}]},{"id":"s2-268","number":268,"surah":2,"verses":[87],"verseLabel":"البقرة: 87","question":"ما الصورة في قوله: ﴿وقفينا من بعده بالرسل﴾؟","answer":"التقفية جعل الشيء في قفا الشيء؛ فصُور تتابع الرسل بعد موسى كأن كل رسول يتبع أثر من قبله. وفي ذلك بيان استمرار الحجة وعدم انقطاع إرسال الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص705–716، تحت البقرة: 87.","url":""}]},{"id":"s2-269","number":269,"surah":2,"verses":[70],"verseLabel":"البقرة: 87، والمائدة: 70","question":"ما سرّ خطاب بني إسرائيل في البقرة: ﴿ففريقًا كذبتم وفريقًا تقتلون﴾، والإخبار عنهم بالغائب في المائدة؟","answer":"واجهت البقرة اليهود الحاضرين بأفعال أسلافهم لأنهم رضوا طريقتهم واستمروا عليها، فناسب الخطاب في مقام التوبيخ. أما المائدة فحكت تاريخ بني إسرائيل في سياق الإخبار عنهم، فناسب ضمير الغائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص425–426، تحت المائدة: 70.","url":""}]},{"id":"s2-270","number":270,"surah":2,"verses":[87],"verseLabel":"البقرة: 87","question":"ما سرّ الماضي في ﴿ففريقًا كذبتم﴾ والمضارع في ﴿وفريقًا تقتلون﴾؟","answer":"جاء التكذيب بالماضي لإثبات ما وقع، وجاء القتل بالمضارع لاستحضار بشاعته كأنه يقع الآن، وللدلالة على استمرار طريقتهم واستعدادهم لقتل من خالف أهواءهم من الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص711–712، تحت البقرة: 87.","url":""}]},{"id":"s2-271","number":271,"surah":2,"verses":[87],"verseLabel":"البقرة: 87","question":"ما سرّ تقديم تكذيب الرسل على قتلهم؟","answer":"لأن التكذيب مبدأ الجريمة ومشترك بين الفريقين؛ فالذين قُتلوا قد كُذبوا أولًا. ثم ترقى التعبير من التكذيب إلى القتل، فانتقل من القبيح إلى ما هو أشد قبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص713–714، تحت البقرة: 87.","url":""}]},{"id":"s2-272","number":272,"surah":2,"verses":[87],"verseLabel":"البقرة: 87","question":"ما سرّ التعبير بـ﴿بما لا تهوى أنفسكم﴾ بدل «بما تكره أنفسكم»؟","answer":"عدم الهوى أعم من الكراهة؛ فقد لا تكره النفس الشيء ولكنها لا تميل إليه ولا يوافق غرضها. فدل التعبير على أنهم يردون كل ما لا يوافق أهواءهم، لا ما يكرهونه كراهة صريحة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص714، تحت البقرة: 87.","url":""}]},{"id":"s2-273","number":273,"surah":2,"verses":[88],"verseLabel":"البقرة: 88","question":"ما دلالة قوله: ﴿فقليلًا ما يؤمنون﴾؟","answer":"يحتمل أن المراد قلة من يؤمن منهم، أو قلة ما يؤمنون به مع كفرهم ببعض، وقيل: القلة مستعملة في معنى النفي؛ أي لا يؤمنون إيمانًا نافعًا. وتعدد الاحتمال لا يغير المقصود من ذم إيمانهم الناقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص716–722، تحت البقرة: 88.","url":""}]},{"id":"s2-274","number":274,"surah":2,"verses":[89],"verseLabel":"البقرة: 89","question":"ما فائدة قوله: ﴿مصدق لما معهم﴾ في إقامة الحجة على أهل الكتاب؟","answer":"لأن القرآن وافق ما في كتابهم من أصول الحق ومن البشارة بالنبي ﷺ، فكان مقتضى علمهم بما معهم أن يكونوا أول المؤمنين به؛ فلما كفروا قامت عليهم الحجة من الكتاب الذي يقرون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص722–733، تحت البقرة: 89.","url":""}]},{"id":"s2-275","number":275,"surah":2,"verses":[89],"verseLabel":"البقرة: 89","question":"ما دلالة قوله عن أهل الكتاب: ﴿وكانوا من قبل يستفتحون على الذين كفروا﴾؟","answer":"كانوا قبل بعثة النبي ﷺ يستنصرون على مشركي العرب بالنبي المنتظر، أو يخبرونهم بقرب مبعثه ويتوعدونهم باتباعه. فلما جاءهم ما عرفوا كفروا به، فكان فعلهم مناقضًا لعلمهم ودعواهم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص729–731، تحت البقرة: 89.","url":""}]},{"id":"s2-276","number":276,"surah":2,"verses":[90],"verseLabel":"البقرة: 90","question":"ما الصورة في قوله: ﴿بئسما اشتروا به أنفسهم﴾؟","answer":"صُور كفرهم بالوحي بيعًا لأنفسهم في صفقة مذمومة، وجُعل ما حصلوه من البغي والحسد عوضًا عنها. ثم جاءت ﴿بئس﴾ لإنشاء الذم وبيان غاية خسارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص733–743، تحت البقرة: 90.","url":""}]},{"id":"s2-277","number":277,"surah":2,"verses":[90],"verseLabel":"البقرة: 90","question":"ما سرّ التعبير بـ﴿بغيًا﴾ في قوله: ﴿بغيًا أن ينزل الله من فضله﴾ بدل الاقتصار على الحسد؟","answer":"البغي أعم من الحسد؛ فهو طلب التجاوز والظلم، ويتضمن هنا الحسد لخروج النبوة من بني إسرائيل وما نشأ عنه من رد الحق والعدوان. فعبّر بالأعم الذي جمع الدافع الباطن وأثره الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص737–738، تحت البقرة: 90.","url":""}]},{"id":"s2-278","number":278,"surah":2,"verses":[90],"verseLabel":"البقرة: 90","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿فباءوا بغضب على غضب﴾؟","answer":"يدل حرف ﴿على﴾ على اجتماع الغضبين وتضاعفهما من غير فتور بينهما، جزاءً لأعمالهم القبيحة المتوالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص740–741، تحت البقرة: 90.","url":""}]},{"id":"s2-279","number":279,"surah":2,"verses":[91],"verseLabel":"البقرة: 91","question":"ما دلالة بناء فعل القول للمفعول في قوله تعالى: ﴿وإذا قيل لهم آمنوا بما أنزل الله﴾؟","answer":"بُني ﴿قيل﴾ للمفعول لأن المقصود بيان ثبات موقفهم الرافض، بقطع النظر عن منزلة من يدعوهم إلى الإيمان؛ فحالهم واحدة سواء أكان الداعي نبيًا أم صحابيًا أم غيرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص745، تحت البقرة: 91.","url":""}]},{"id":"s2-280","number":280,"surah":2,"verses":[91],"verseLabel":"البقرة: 91","question":"ما الذي يفيده قولهم: ﴿نؤمن بما أنزل علينا﴾؟","answer":"جاء ﴿نؤمن﴾ بالمضارع للدلالة على ادعائهم استمرار الإيمان بالتوراة، واتخذوا اختصاصهم بإنزالها عليهم عذرًا لرفض الإيمان بالقرآن. وجاء ﴿أنزل علينا﴾ مبنيًا للمفعول موافقةً لعبارتهم، وفيه تعظيم لأنفسهم وعدم عناية بذكر المنزِّل سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص746–747، تحت البقرة: 91.","url":""}]},{"id":"s2-281","number":281,"surah":2,"verses":[91,97],"verseLabel":"البقرة: 91 و97","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الآية 91: ﴿مصدقًا لما معهم﴾، وقوله في الآية 97: ﴿مصدقًا لما بين يديه﴾؟","answer":"خُصَّ التصديق في الآية 91 بما مع اليهود من التوراة لأن المقام مقام مخاطبتهم وإلزامهم الحجة. أما الآية 97 فمقامها تفخيم القرآن وبيان موقف جبريل منه، فجيء بالوصف عامًا في تصديقه الكتب السابقة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص794، تحت البقرة: 97.","url":""}]},{"id":"s2-282","number":282,"surah":2,"verses":[91],"verseLabel":"البقرة: 91","question":"ما دلالة قوله تعالى عن القرآن: ﴿ويكفرون بما وراءه﴾؟","answer":"إن كانت ﴿وراء﴾ بمعنى الخلف، ففيها كناية أو استعارة عن طرح القرآن وراء ظهورهم وترك الإيمان به. وإن كانت بمعنى أمام، ففيها مدح للقرآن المهيمن على الكتب السابقة وذم لهم إذ كفروا به. وكلا الوجهين يذم عدم إيمانهم بالقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص747–748، تحت البقرة: 91.","url":""}]},{"id":"s2-283","number":283,"surah":2,"verses":[91],"verseLabel":"البقرة: 91","question":"ما سرّ مجيء ﴿تقتلون﴾ بالمضارع مع تقييده بقوله: ﴿من قبل﴾؟","answer":"جيء بالمضارع لاستحضار بشاعة قتل الأنبياء، وللدلالة على رضا المعاصرين بفعل أسلافهم واتباعهم منهجهم والعزم عليه. وجاء ﴿من قبل﴾ احتراسًا لئلا يُتوهم أنهم باشروا القتل، مع إبقاء نسبته إليهم بسبب رضاهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص751–752، تحت البقرة: 91.","url":""}]},{"id":"s2-284","number":284,"surah":2,"verses":[92],"verseLabel":"البقرة: 92","question":"ما سرّ استعمال ﴿ثم﴾ في قوله تعالى: ﴿ثم اتخذتم العجل﴾ بدل الواو؟","answer":"أفادت ﴿ثم﴾ أنهم اتخذوا العجل بعد مهلة مكّنتهم من تدبر البينات، فكان فعلهم بعد هذا البيان في غاية الاستبعاد، وفيه تعجيب وتقريع لا تؤديه الواو وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص756، تحت البقرة: 92.","url":""}]},{"id":"s2-285","number":285,"surah":2,"verses":[92],"verseLabel":"البقرة: 92","question":"ما سرّ التعبير بقوله تعالى: ﴿اتخذتم العجل﴾ بدل «عبدتم العجل»؟","answer":"الاتخاذ يتضمن حيازة الشيء وطلبه والرغبة فيه والاستمرار عليه، وهو أنسب بحالهم؛ لأنهم لم ينقادوا للعجل في جميع أمورهم، بل فيما وافق أهواءهم. وفي صيغة الاتخاذ كذلك تكلفٌ يشعر بمخالفة الفطرة، وحُذف مفعوله الثاني المقدر بـ«إلهًا» لظهوره ولصون العبارة عن التصريح بالوصف القبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص756–757، تحت البقرة: 92.","url":""}]},{"id":"s2-286","number":286,"surah":2,"verses":[93],"verseLabel":"البقرة: 93","question":"ما الصورة البيانية في قوله تعالى: ﴿وأشربوا في قلوبهم العجل﴾؟","answer":"حُذف «حب عبادة العجل»، وشُبّه تمكنه من قلوبهم بالشراب الذي يسري في البدن ويخالطه؛ فدل التعبير على رسوخ الحب وإغراقهم في الضلالة. وبناء ﴿أشربوا﴾ للمفعول يصور استيلاء الخرافة عليهم حتى كأنهم مقهورون عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص763–767، تحت البقرة: 93.","url":""}]},{"id":"s2-287","number":287,"surah":2,"verses":[94,95],"verseLabel":"البقرة: 94–95","question":"ما وجه الاحتجاج عليهم بقوله تعالى: ﴿فتمنوا الموت إن كنتم صادقين﴾؟","answer":"زعموا أن الجنة خالصة لهم، ومن أيقن بذلك أحب الانتقال إلى ما ادعاه لنفسه؛ فجُعل تمني الموت حجةً تكشف كذب دعواهم، ثم أخبر الله أنهم لن يتمنوه لما يعلمون من سوء أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص769–788، تحت البقرة: 94–96.","url":""}]},{"id":"s2-288","number":288,"surah":2,"verses":[6,7],"verseLabel":"البقرة: 94–95، والجمعة: 6–7","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ولن يتمنوه أبدًا﴾، وقوله في الجمعة: ﴿ولا يتمنونه أبدًا﴾؟","answer":"دعواهم في البقرة أن الدار الآخرة خالصة لهم من دون الناس هي غاية ما يدعيه المدعي، فناسبها النفي المؤكد بـ﴿لن﴾. أما دعواهم في الجمعة أنهم أولياء لله، فليست في قوة الدعوى الأولى؛ إذ يبقى بعدها إثبات استحقاق الآخرة، فجاء النفي بـ﴿لا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص680–682، تحت الجمعة: 6–7.","url":""}]},{"id":"s2-289","number":289,"surah":2,"verses":[96],"verseLabel":"البقرة: 96","question":"ما دلالة تنكير ﴿حياة﴾ في قوله تعالى: ﴿أحرص الناس على حياة﴾؟","answer":"يفيد التنكير أنهم حريصون على أي حياة، ولو كانت حقيرة ذليلة؛ فهي عندهم خير من الموت لما يتوقعونه من العذاب. ويحتمل أيضًا التعظيم، أي الحياة المتطاولة، فاجتمع في التنكير الوجهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص782–783، تحت البقرة: 96.","url":""}]},{"id":"s2-290","number":290,"surah":2,"verses":[96],"verseLabel":"البقرة: 96","question":"ما سرّ عطف قوله تعالى: ﴿ومن الذين أشركوا﴾ على ﴿الناس﴾ مع دخول المشركين فيهم؟","answer":"خُص المشركون بالذكر بعد عموم الناس لأنهم أشد الناس حرصًا على الحياة؛ إذ لا يؤمنون بالبعث. فالمعنى أن اليهود أحرص من الناس، بل ومن المشركين الذين بلغوا الغاية في حب الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص781–782، تحت البقرة: 96.","url":""}]},{"id":"s2-291","number":291,"surah":2,"verses":[96],"verseLabel":"البقرة: 96","question":"ما مناسبة التعبير بـ﴿ألف سنة﴾ بدل «ألف عام»؟","answer":"تستعمل «السنة» غالبًا للحول الذي فيه جدب وضيق وتعب، بخلاف «العام» الذي يغلب استعماله في الخصب والخير. فناسبت ﴿سنة﴾ ذم حرصهم على البقاء ولو في حياة بالغة الذل والشقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص784 و787، تحت البقرة: 96.","url":""}]},{"id":"s2-292","number":292,"surah":2,"verses":[96],"verseLabel":"البقرة: 96","question":"ما دلالة قوله تعالى: ﴿وما هو بمزحزحه من العذاب﴾؟","answer":"الزحزحة هي الإبعاد والتنحية، ونفت الباء في ﴿بمزحزحه﴾ نفيًا مؤكدًا مستغرقًا لأي نوع من الإبعاد عن العذاب؛ فلا ينفعه طول العمر مهما بلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص784–786، تحت البقرة: 96.","url":""}]},{"id":"s2-293","number":293,"surah":2,"verses":[97],"verseLabel":"البقرة: 97","question":"ما سرّ مجيء قوله تعالى: ﴿من كان عدوًّا لجبريل﴾ بصيغة عامة بدل خطاب اليهود مباشرة؟","answer":"جيء بالغيبة وبصيغة الشرط العامة ليشمل الحكم كل من عادى جبريل، مع إرادة اليهود أولًا؛ فمعاداته كفر لا يختص بشريعة ولا بقوم، وفي ذلك إعراض عن الاعتداد بهم مع بيان شمول غضب الله لكل من عادى رسولًا من رسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص790، تحت البقرة: 97.","url":""}]},{"id":"s2-294","number":294,"surah":2,"verses":[97],"verseLabel":"البقرة: 97","question":"ما سرّ حذف جواب الشرط في قوله تعالى: ﴿من كان عدوًّا لجبريل فإنه نزله على قلبك﴾؟","answer":"حُذف الجواب ليذهب ذهن السامع في الوعيد كل مذهب، فيعظم التخويف. ثم ذُكرت علة بطلان العداوة: أن جبريل نزّل القرآن بأمر الله، مصدقًا لكتابهم وهدًى وبشرى؛ فجمع السياق بين الوعيد وإقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص790–791، تحت البقرة: 97.","url":""}]},{"id":"s2-295","number":295,"surah":2,"verses":[193,194],"verseLabel":"البقرة: 97، والشعراء: 193–194","question":"ما سرّ اختلاف التعبير بين قوله تعالى هنا: ﴿فإنه نزله على قلبك﴾ بالتشديد، وقوله في الشعراء: ﴿نزل به الروح الأمين﴾ من غير تشديد؟","answer":"أفادت صيغة ﴿نزّل﴾ التفريق والتكثير، وناسبت مقام تثبيت قلب النبي ﷺ أمام أكاذيب اليهود وذكر أوصاف القرآن. أما آية الشعراء فمقامها الإنذار بجميع القرآن، فناسبها الفعل المجرد ﴿نزل﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص791–792، تحت البقرة: 97.","url":""}]},{"id":"s2-296","number":296,"surah":2,"verses":[97],"verseLabel":"البقرة: 97","question":"ما دلالة عود الضمير في قوله تعالى: ﴿فإنه نزله﴾ إلى القرآن مع عدم ذكره قبله صراحة؟","answer":"أُضمر القرآن من غير تقدم ذكره إيذانًا بفخامة شأنه واستغنائه عن الذكر لكمال شهرته؛ كما أن فعل التنزيل قرينة تدل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص792، تحت البقرة: 97.","url":""}]},{"id":"s2-297","number":297,"surah":2,"verses":[97],"verseLabel":"البقرة: 97","question":"ما سرّ تعدية فعل التنزيل بـ﴿على﴾ في قوله تعالى: ﴿نزله على قلبك﴾ بدل «إلى»؟","answer":"تفيد ﴿على﴾ استعلاء القرآن على القلب واستيعابه وتمكنه منه، وفي ذلك تشريف للنبي ﷺ. أما «إلى» فتفيد انتهاء الغاية من غير دلالة الاستيعاب والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص793، تحت البقرة: 97.","url":""}]},{"id":"s2-298","number":298,"surah":2,"verses":[97],"verseLabel":"البقرة: 97","question":"ما سرّ وصف القرآن بالمصدرين ﴿هدًى وبشرى﴾ بدل «هاديًا ومبشرًا»؟","answer":"عُدل عن اسمي الفاعل إلى المصدرين للمبالغة في وصف القرآن بالهداية والبشرى وتعظيم شأنه، حتى جُعل نفس الهدى والبشرى للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص795، تحت البقرة: 97.","url":""}]},{"id":"s2-299","number":299,"surah":2,"verses":[97],"verseLabel":"البقرة: 97","question":"ما مناسبة تقديم ﴿هدًى﴾ على ﴿بشرى للمؤمنين﴾؟","answer":"الهدى يبين الطريق الموصل، والبشرى تبين ثواب من سلكه؛ فالهدى مقدم على البشرى في الوجود، ولذلك قُدّم في الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص795، تحت البقرة: 97.","url":""}]},{"id":"s2-300","number":300,"surah":2,"verses":[97,99],"verseLabel":"البقرة: 97 و99","question":"ما سرّ اختلاف حرف التعدية بين قوله تعالى: ﴿نزله على قلبك﴾، وقوله: ﴿ولقد أنزلنا إليك آيات بينات﴾؟","answer":"عُدِّي التنزيل في الآية الأولى بـ﴿على﴾ للدلالة على استعلاء القرآن على القلب واستيعابه وتمكنه منه. وعُدِّي في الثانية بـ﴿إلى﴾ للدلالة على انتهاء الإنزال إلى النبي ﷺ، مع تقديم ﴿إليك﴾ للعناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص793، وج2، ص16–17، تحت البقرة: 97 و99.","url":""}]},{"id":"s2-301","number":301,"surah":2,"verses":[98],"verseLabel":"البقرة: 98","question":"ما سرّ تخصيص جبريل وميكال بالذكر بعد قوله تعالى: ﴿وملائكته﴾؟","answer":"ذُكرا بعد دخولهما في عموم الملائكة تشريفًا لهما وتفضيلًا، ولأن الآية نزلت في شأن عداوة اليهود المتعلقة بهما؛ فناسب النص على اسميهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص12–13، تحت البقرة: 98.","url":""}]},{"id":"s2-302","number":302,"surah":2,"verses":[98],"verseLabel":"البقرة: 98","question":"ما سرّ إظهار اسم الله ووصفهم بالكفر في قوله تعالى: ﴿فإن الله عدو للكافرين﴾ بدل «فإنه عدو لهم»؟","answer":"أُظهر اسم الله لدفع التباس مرجع الضمير بعد تعدد المذكورين، ولتفخيم الأمر وتعظيم الجزاء. ووُضع ﴿للكافرين﴾ موضع الضمير لبيان أن كفرهم سبب العداوة، ولجعل الجملة حكمًا عامًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص12–13، تحت البقرة: 98.","url":""}]},{"id":"s2-303","number":303,"surah":2,"verses":[98],"verseLabel":"البقرة: 98","question":"ما مناسبة تقديم الملائكة على الرسل في قوله تعالى: ﴿وملائكته ورسله﴾؟","answer":"جاء الترتيب اللفظي موافقًا للترتيب الوجودي؛ فالملائكة أسبق وجودًا عند ظهور الإرسال، وعداوة الرسل فرع عن عداوة من يبلغهم الوحي، والجميع تابعون لأمر الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص12، تحت البقرة: 98.","url":""}]},{"id":"s2-304","number":304,"surah":2,"verses":[99],"verseLabel":"البقرة: 99","question":"ما فائدة وصف الآيات بأنها ﴿بينات﴾؟","answer":"الوصف يدل على وضوح طريق معرفتها، وأنها تزيل الالتباس وتفصل بين الحق والباطل؛ فالقرآن بما اشتمل عليه من الآيات واضح الدلالة على معانيه وعلى صدق نزوله وصحة نبوة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص15 و17–18، تحت البقرة: 99.","url":""}]},{"id":"s2-305","number":305,"surah":2,"verses":[99],"verseLabel":"البقرة: 99","question":"ما دلالة وصف من يكفر بالآيات البينات بـ﴿الفاسقين﴾؟","answer":"الفسق هو الخروج، والمراد هنا الخارجون عن دين الله وطاعته، المتمردون في الكفر المتعدون حدوده. ووصفهم به يبين أن كفرهم بالآيات الواضحة ناشئ عن خروجهم وتمردهم، لا عن خفاء الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص15–19، تحت البقرة: 99.","url":""}]},{"id":"s2-306","number":306,"surah":2,"verses":[100],"verseLabel":"البقرة: 100","question":"ما الصورة في قوله تعالى عن العهد: ﴿نبذه فريق منهم﴾؟","answer":"صُوِّر العهد بشيء يُطرح ويُرمى احتقارًا له وعدم اعتداد به. وإسناد النبذ إلى ﴿فريق منهم﴾ يمنع تعميم مباشرة الفعل على جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص21–27، تحت البقرة: 100.","url":""}]},{"id":"s2-307","number":307,"surah":2,"verses":[100,101],"verseLabel":"البقرة: 100–101","question":"ما سرّ اختلاف التعبير بين قوله تعالى: ﴿نبذه فريق منهم﴾، وقوله بعدها: ﴿نبذ فريق من الذين أوتوا الكتاب كتاب الله﴾؟","answer":"الآية الأولى في نبذ عهد من العهود، فاقتصر على الضمير العائد إليه. أما الثانية ففي نبذ كتاب الله عند مجيء الرسول المصدق لما معهم، فصرّحت بوصفهم ﴿الذين أوتوا الكتاب﴾ وبالمنبوذ ﴿كتاب الله﴾؛ زيادةً في تقبيح فعل من أوتي الكتاب ثم طرحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص30–31، تحت البقرة: 101.","url":""}]},{"id":"s2-308","number":308,"surah":2,"verses":[100,101],"verseLabel":"البقرة: 100–101","question":"ما سرّ زيادة قوله تعالى: ﴿وراء ظهورهم﴾ في الآية 101 بعد الاكتفاء بالنبذ في الآية 100؟","answer":"في الآية الأولى دل النبذ على رفض العهد وعدم الاعتداد به. وفي الثانية زيد ﴿وراء ظهورهم﴾ لتصوير شدة استخفافهم بكتاب الله وإعراضهم عنه، فكأنهم طرحوه في موضع لا يرونه ولا يلتفتون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص30–31، تحت البقرة: 101.","url":""}]},{"id":"s2-309","number":309,"surah":2,"verses":[100],"verseLabel":"البقرة: 100","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أوكلما عاهدوا عهدًا نبذه فريق منهم﴾؟","answer":"الاستفهام للتعجيب من حالهم والتوبيخ والتقرير؛ فهو يحمل المخاطب على الإقرار بتكرر نقضهم العهود وقبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص22–23، تحت البقرة: 100.","url":""}]},{"id":"s2-310","number":310,"surah":2,"verses":[100],"verseLabel":"البقرة: 100","question":"ما دلالة تنكير ﴿عهدًا﴾ في قوله تعالى: ﴿كلما عاهدوا عهدًا﴾؟","answer":"يفيد التنكير العموم؛ أي كلما عاهدوا أي عهد نبذه فريق منهم، فلا يختص الحكم بعهد معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص23، تحت البقرة: 100.","url":""}]},{"id":"s2-311","number":311,"surah":2,"verses":[100],"verseLabel":"البقرة: 100","question":"ما دلالة الانتقال من قوله تعالى: ﴿نبذه فريق منهم﴾ إلى قوله: ﴿بل أكثرهم لا يؤمنون﴾؟","answer":"نسب النبذ إلى فريق احتراسًا من تعميم مباشرة الفعل، ثم أضرب بـ﴿بل﴾ لبيان أن عدم الإيمان أوسع؛ فأكثرهم لا يؤمنون، وإن لم يباشر كل واحد منهم نبذ كل عهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص24–25، تحت البقرة: 100.","url":""}]},{"id":"s2-312","number":312,"surah":2,"verses":[101],"verseLabel":"البقرة: 101","question":"ما سرّ التعبير بـ﴿يتلو﴾ بدل «يقرأ»؟","answer":"التلاوة أخص من القراءة؛ ففيها اتباع الكلمات بعضها بعضًا، وتغلب في قراءة الكتب المنزلة وما يُظن أنه منها، كما تتضمن اتباع المتلو بالعلم والعمل. ولذلك ناسبت مجيء الرسول بالكتاب، وناسبت أيضًا ما كانت الشياطين تزعم أنه من كتب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص47–49، تحت البقرة: 102، مع سياق البقرة: 101.","url":""}]},{"id":"s2-313","number":313,"surah":2,"verses":[101],"verseLabel":"البقرة: 101","question":"ما دلالة تنكير ﴿رسول﴾ في قوله تعالى: ﴿ولما جاءهم رسول من عند الله﴾؟","answer":"التنكير للتعظيم والتفخيم؛ فهو رسول عظيم القدر عند مرسله، وفي ذلك زيادة تقبيح لإعراضهم عنه ونبذهم كتاب الله عند مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص28، تحت البقرة: 101.","url":""}]},{"id":"s2-314","number":314,"surah":2,"verses":[101],"verseLabel":"البقرة: 101","question":"ما دلالة تشبيه أهل الكتاب بقوله تعالى: ﴿كأنهم لا يعلمون﴾؟","answer":"كانوا يعلمون صدق الرسول وموافقة القرآن لما معهم، لكنهم لم يعملوا بعلمهم؛ فنُزّل العالم الذي لا ينتفع بعلمه منزلة الجاهل، وفي التشبيه تعريض بمكابرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص29، تحت البقرة: 101.","url":""}]},{"id":"s2-315","number":315,"surah":2,"verses":[101],"verseLabel":"البقرة: 101","question":"ما دلالة مجيء ﴿يعلمون﴾ بالمضارع في قوله تعالى: ﴿كأنهم لا يعلمون﴾؟","answer":"يدل المضارع على تجدد حالهم واستمرارها؛ فهم يتظاهرون بعدم العلم ويعطلون أثره كلما جاءهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص29–30، تحت البقرة: 101.","url":""}]},{"id":"s2-316","number":316,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما دلالة اختيار لفظ ﴿المرء﴾ في قوله تعالى: ﴿يفرقون به بين المرء وزوجه﴾؟","answer":"اختير ﴿المرء﴾ لما يفيده من كمال القوة وحسن الأدب والمروءة؛ فإذا بلغ السحر أن يفرق بينه وبين زوجه مع قوة رابطة الزوجية، كان أثره فيما دونها أولى، وفي ذلك بيان لشناعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص42، تحت البقرة: 102.","url":""}]},{"id":"s2-317","number":317,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما سرّ مجيء ﴿تتلو الشياطين﴾ بالمضارع مع أن الحديث عن زمن سليمان؟","answer":"جاء المضارع لاستحضار الصورة، وللدلالة على تجدد تلاوة الشياطين وكثرة ما تتلوه وفشوه، وأن أحبار اليهود في زمن النزول واصلوا تلاوة ما ورثوه عن أسلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص36، تحت البقرة: 102.","url":""}]},{"id":"s2-318","number":318,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما سرّ التعبير بـ﴿تتلو الشياطين﴾ بدل «تقرأ الشياطين»؟","answer":"التلاوة أخص من القراءة؛ ففيها اتباع الكلمات بعضها بعضًا، وتستعمل في الكتب المنزلة أو ما يُتوهم أنه منها، وقد تحمل معنى اتباع المتلو بالعلم والعمل. فناسبت زعمهم أن ما تتلوه الشياطين من كتب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص36 و47–49، تحت البقرة: 102.","url":""}]},{"id":"s2-319","number":319,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما سرّ نفي الكفر عن سليمان في قوله تعالى: ﴿وما كفر سليمان﴾ بدل الاقتصار على نفي السحر؟","answer":"نفى القرآن عن سليمان الكفر لأن السحر الذي نسبوه إليه من الكفر، فنفي اللازم الأشد أبلغ في تبرئته وفي تقبيح ما نسبوه إليه. ثم قابل ذلك بقوله: ﴿ولكن الشياطين كفروا﴾ فنقل التهمة إلى أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص36–37، تحت البقرة: 102.","url":""}]},{"id":"s2-320","number":320,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما دلالة مجيء قوله تعالى: ﴿يعلمون الناس السحر﴾ بعد قوله: ﴿ولكن الشياطين كفروا﴾؟","answer":"جاءت جملة ﴿يعلمون الناس السحر﴾ حالًا تبين هيئة كفر الشياطين؛ فكفرهم مقترن بتعليم السحر ونشره بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص37–38، تحت البقرة: 102.","url":""}]},{"id":"s2-321","number":321,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"كيف كان تعليم الملكين فتنةً مع تحذيرهما: ﴿إنما نحن فتنة فلا تكفر﴾؟","answer":"كان أمرهما اختبارًا ظاهرًا للناس، فلا يعلمان أحدًا حتى يبينَا له أنهما فتنة ويحذراه من الكفر. فالتعليم في هذا السياق ابتلاء مع إقامة التحذير، لا دعوة إلى العمل بالسحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص39 و49، تحت البقرة: 102.","url":""}]},{"id":"s2-322","number":322,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما سرّ التعبير بالمصدر في قول الملكين: ﴿إنما نحن فتنة﴾ بدل «فاتنان»؟","answer":"جاء الخبر بالمصدر للمبالغة، فكأنهما نفس الفتنة والاختبار، وزاد القصر بـ﴿إنما﴾ وضوح أن مهمتهما في هذا المقام امتحان المكلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص39–40، تحت البقرة: 102.","url":""}]},{"id":"s2-323","number":323,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما دلالة الفاء في قوله تعالى بعد تحذير الملكين: ﴿فيتعلمون منهما﴾؟","answer":"تفيد الفاء التعقيب، فتصور مسارعتهم إلى التعلم عقب التحذير من الكفر، وفي ذلك تقريع لهم؛ إذ لم يردعهم الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص40، تحت البقرة: 102.","url":""}]},{"id":"s2-324","number":324,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما دلالة مجيء ﴿فيتعلمون﴾ و﴿يفرقون﴾ بالمضارع في سياق قصة ماضية؟","answer":"يستحضر المضارع صورة تعلمهم السحر والتفريق به، ويفيد تجدد الفعل واستمراره، لا كونه واقعة انقطعت.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص40–41، تحت البقرة: 102.","url":""}]},{"id":"s2-325","number":325,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما سرّ تخصيص التفريق بين المرء وزوجه بالذكر من آثار السحر؟","answer":"رابطة الزوجية من أشد أواصر الاتصال لما فيها من مودة ورحمة وتدبير وتربية؛ فإذا بلغ السحر أن يفسخ هذه الرابطة الوثيقة، كان تأثيره فيما دونها أولى. فذُكر هذا الأثر تنبيهًا على بقية آثاره وتحذيرًا من خطره في المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص41–42، تحت البقرة: 102.","url":""}]},{"id":"s2-326","number":326,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما دلالة أسلوب النفي والاستثناء في قوله تعالى: ﴿وما هم بضارين به من أحد إلا بإذن الله﴾؟","answer":"جاء الأسلوب بالقصر والنفي المؤكد؛ فالباء تؤكد النفي، و﴿من أحد﴾ تستغرق كل أحد، ثم حُصر وقوع الضرر في إذن الله. وبذلك يُدفع توهم أن للسحر تأثيرًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص42–43، تحت البقرة: 102.","url":""}]},{"id":"s2-327","number":327,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما دلالة تكرار ﴿فيتعلمون﴾ في الآية؟","answer":"أفاد التكرار اختلاف مآلَي التعلم: فالأول يبين التفريق بين المرء وزوجه، وهو ضرر يقع في المجتمع، والثاني يبين أن السحر يضر متعلمه ولا ينفعه. فلكل جملة غرض جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص43، تحت البقرة: 102.","url":""}]},{"id":"s2-328","number":328,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"ما فائدة التصريح بنفي النفع بعد إثبات الضرر في قوله تعالى: ﴿ما يضرهم ولا ينفعهم﴾؟","answer":"لا يلزم من ثبوت الضرر انتفاء النفع؛ فقد يجتمعان في الشيء. لذلك عُطفت ﴿ولا ينفعهم﴾ لتدل على أن السحر شر محض، منفي النفع بالكلية، وليس مما اختلط ضرره بنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص43–44، تحت البقرة: 102.","url":""}]},{"id":"s2-329","number":329,"surah":2,"verses":[102],"verseLabel":"البقرة: 102","question":"كيف أثبت لهم العلم في قوله تعالى: ﴿ولقد علموا﴾ ثم نفاه بقوله: ﴿لو كانوا يعلمون﴾؟","answer":"أثبت لهم العلم المؤكد بعاقبة السحر، لكنهم لم يعملوا به ولم ينتفعوا منه؛ فنُزّل العالم الذي لا ينتفع بعلمه منزلة الجاهل، ونُفي عنه العلم النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص47–48، تحت البقرة: 102.","url":""}]},{"id":"s2-330","number":330,"surah":2,"verses":[102,103],"verseLabel":"البقرة: 102–103","question":"ما دلالة تكرار قوله تعالى: ﴿لو كانوا يعلمون﴾ في ختام الآيتين 102 و103؟","answer":"في ختام الآية 102 نُفي عنهم العلم النافع بعد إثبات علمهم بعاقبة السحر، وفي الآية 103 عاد النفي لأنهم لم يعلموا علمًا يحملهم على الإيمان والتقوى وإيثار مثوبة الله. فتكرر اللفظ لاتصال المعنى مع اختلاف متعلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص54، تحت البقرة: 103.","url":""}]},{"id":"s2-331","number":331,"surah":2,"verses":[103],"verseLabel":"البقرة: 103","question":"ما دلالة الشرط بـ﴿لو﴾ في قوله تعالى: ﴿ولو أنهم آمنوا واتقوا﴾؟","answer":"أفادت ﴿لو﴾ امتناع حصول المثوبة المذكورة لهم لامتناع إيمانهم وتقواهم، فدلت على حرمانهم من الخير بسبب عدم تحقق الشرط. ودخول ﴿أن﴾ أكد الشرط وتقريره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص52، تحت البقرة: 103.","url":""}]},{"id":"s2-332","number":332,"surah":2,"verses":[103],"verseLabel":"البقرة: 103","question":"ما دلالة الجمع بين الإيمان والتقوى في قوله تعالى: ﴿آمنوا واتقوا﴾؟","answer":"لأنهم تركوا المأمورات وفعلوا المنهيات؛ فالإيمان يدل على فعل المأمور به، كالإيمان بالرسول ﷺ والكتاب، والتقوى تدل على ترك المنهيات، ومنها نبذ الكتاب واتباع السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص52، تحت البقرة: 103.","url":""}]},{"id":"s2-333","number":333,"surah":2,"verses":[103],"verseLabel":"البقرة: 103","question":"ما دلالة تنكير ﴿مثوبة﴾ في قوله تعالى: ﴿لمثوبة من عند الله خير﴾؟","answer":"أفاد التنكير التقليل؛ أي إن مثوبة قليلة من عند الله خير لهم، فإذا كان القليل خيرًا فكيف بالمثوبة الكثيرة؟ ففي ذكر القليل تنبيه على الكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص53، تحت البقرة: 103.","url":""}]},{"id":"s2-334","number":334,"surah":2,"verses":[103],"verseLabel":"البقرة: 103","question":"ما فائدة وصف المثوبة بقوله تعالى: ﴿من عند الله﴾؟","answer":"لما أفاد تنكير ﴿مثوبة﴾ التقليل، وُصفت بأنها ﴿من عند الله﴾ لتعظيمها وتفخيم شأنها؛ فما كان من عند الله عظيم وإن قل، و﴿من﴾ تفيد ابتداءها منه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص53–54، تحت البقرة: 103.","url":""}]},{"id":"s2-335","number":335,"surah":2,"verses":[103],"verseLabel":"البقرة: 103","question":"ما دلالة استعمال ﴿خير﴾ في قوله تعالى: ﴿لمثوبة من عند الله خير﴾ مع أنه لا خير في نبذ الكتاب وتعلم السحر؟","answer":"لم تستعمل ﴿خير﴾ هنا للمفاضلة بين شيئين فيهما خير، بل بمعنى الصفة الثابتة المقابلة للشر؛ فأثبتت الخير للمثوبة ونفته عن العمل المقابل، وفي صيغة التفضيل مبالغة في بيان شأن الخير المستحق للعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص54، تحت البقرة: 103.","url":""}]},{"id":"s2-336","number":336,"surah":2,"verses":[104],"verseLabel":"البقرة: 104","question":"ما سرّ النهي عن قول ﴿راعنا﴾ مع أن المؤمنين قصدوا بها معنى صحيحًا؟","answer":"كان المؤمنون يريدون بها الإمهال والإصغاء، لكنها تحتمل معنى المفاعلة والندية وفيها جفاء لا يليق بمقام النبي ﷺ، كما كان اليهود يلوون ألسنتهم بها ويقصدون الرعونة والسب؛ فنُهي عنها سدًّا لهذا الباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص56 و59–60، تحت البقرة: 104.","url":""}]},{"id":"s2-337","number":337,"surah":2,"verses":[104],"verseLabel":"البقرة: 104","question":"ما سرّ اختيار ﴿انظرنا﴾ بدل ﴿راعنا﴾؟","answer":"تؤدي ﴿انظرنا﴾ معنى الانتظار والإمهال والرفق، ولا تتضمن معنى المفاعلة والندية الذي في ﴿راعنا﴾، ولا توهم سوء الأدب الذي يتذرع به الكفار إلى أذى النبي ﷺ. وهي كذلك أخف صوتًا وأنسب معنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص56 و59–60، تحت البقرة: 104.","url":""}]},{"id":"s2-338","number":338,"surah":2,"verses":[104],"verseLabel":"البقرة: 104","question":"ما مناسبة تقديم النهي ﴿لا تقولوا راعنا﴾ على الأمر ﴿وقولوا انظرنا﴾؟","answer":"قُدّم النهي لأن اللفظ المنهي عنه كان موجودًا شائعًا في الاستعمال، فأُمروا بتركه أولًا، ثم أُقيم اللفظ البديل مكانه؛ فكانت التخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص57، تحت البقرة: 104.","url":""}]},{"id":"s2-339","number":339,"surah":2,"verses":[104],"verseLabel":"البقرة: 104","question":"ما دلالة حذف مفعول ﴿واسمعوا﴾؟","answer":"أفاد الحذف العموم: اسمعوا كلام النبي ﷺ سماع إصغاء وفهم وحفظ وطاعة وامتثال، ولا يختص الأمر بمسموع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص57–58، تحت البقرة: 104.","url":""}]},{"id":"s2-340","number":340,"surah":2,"verses":[104],"verseLabel":"البقرة: 104","question":"ما سرّ وضع الوصف الظاهر في قوله تعالى: ﴿وللكافرين عذاب أليم﴾ موضع الضمير؟","answer":"عُدل عن الضمير إلى وصف ﴿الكافرين﴾ لبيان سبب استحقاق العذاب، ولتعميم الحكم في كل من اتصف بالكفر، لا في جماعة مخصوصة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص58–59، تحت البقرة: 104.","url":""}]},{"id":"s2-341","number":341,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما سرّ التعبير بـ﴿يختص برحمته﴾ بدل «يخص برحمته»؟","answer":"﴿يختص﴾ تدل على الانفراد بالشيء لنفسه، فهي أوكد في الخصوصية من «يخص». وفيها أن الله يصطفي من يشاء برحمته وفضله، خلافًا لما يتمناه الحاسدون لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص61–62 و65، تحت البقرة: 105.","url":""}]},{"id":"s2-342","number":342,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما سرّ التعبير بقوله تعالى: ﴿ما يود الذين كفروا﴾ بدل «ما يحب»؟","answer":"الود يجمع محبة الشيء وتمني حصوله، فجاء هنا ليصور موافقة تمنيهم لطباعهم السيئة وحسدهم، وليفيد أن ما يتمنونه من انقطاع الخير عن المؤمنين لا مطمع في وقوعه. كما أفاد المضارع تجدد نفي ودهم واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص62–63 و68، تحت البقرة: 105.","url":""}]},{"id":"s2-343","number":343,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما دلالة قوله تعالى: ﴿الذين كفروا من أهل الكتاب﴾؟","answer":"جاء الموصول وصلته ليشمل الحكم الكافرين من اليهود والنصارى، وليومئ إلى أن كفرهم هو سبب كراهتهم الخير للمؤمنين. و﴿من﴾ بيانية تبين صنف هؤلاء الكافرين، وقيل: تبعيضية؛ أي بعض أهل الكتاب ممن كفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص63–64، تحت البقرة: 105.","url":""}]},{"id":"s2-344","number":344,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما مناسبة تقديم أهل الكتاب على المشركين في قوله تعالى: ﴿من أهل الكتاب ولا المشركين﴾؟","answer":"قُدّم أهل الكتاب لأن السياق فيهم، ولأن الجحود ممن أوتي علمًا أشد من جحود الجاهل؛ فقد عرفوا ثم لم ينتفعوا بعلمهم، وكان حسدهم أن تكون الرسالة في ولد إسماعيل أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص64–65، تحت البقرة: 105.","url":""}]},{"id":"s2-345","number":345,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما سرّ بناء ﴿ينزل﴾ للمفعول في قوله تعالى: ﴿أن ينزل عليكم من خير من ربكم﴾؟","answer":"أُوثر البناء للمفعول للإشعار بأن ابتداء الخير من الله تعالى، ولإبراز تكريم المؤمنين بتنزيله عليهم؛ ثم دل قوله ﴿من ربكم﴾ على مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص65، تحت البقرة: 105.","url":""}]},{"id":"s2-346","number":346,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿أن ينزل عليكم﴾؟","answer":"أفادت ﴿على﴾ عظمة الخير المنزل وعلوه، كما أفادت استيعابه للمؤمنين وتمكنه فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص65، تحت البقرة: 105.","url":""}]},{"id":"s2-347","number":347,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما دلالة حذف مفعول ﴿يشاء﴾ في قوله تعالى: ﴿والله يختص برحمته من يشاء﴾؟","answer":"دل السياق على المفعول المحذوف، أي: من يشاء اختصاصه برحمته. وحذفه أفاد العموم مع الاختصار؛ لأن مشيئة الله لا يحصرها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص66، تحت البقرة: 105.","url":""}]},{"id":"s2-348","number":348,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من خير من ربكم﴾؟","answer":"الأولى في ﴿من خير﴾ لاستغراق جنس الخير؛ فهم لا يودون أن ينزل على المؤمنين أي نوع منه ولو قليلًا. والثانية في ﴿من ربكم﴾ لابتداء الغاية؛ أي إن ابتداء تنزيل الخير من الله تعالى، وفي ذلك تكريم للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص66، تحت البقرة: 105.","url":""}]},{"id":"s2-349","number":349,"surah":2,"verses":[105],"verseLabel":"البقرة: 105","question":"ما سرّ التعبير بقوله تعالى: ﴿والله ذو الفضل العظيم﴾ بدل «صاحب الفضل»؟","answer":"التعبير بـ﴿ذو﴾ أشرف في الاستعمال من «صاحب»، ويفيد أن الفضل العظيم وصف ملازم لله غير مفارق له. وتذييل الآية بهذه الجملة يدل على عموم فضله ودوامه، وأن اختصاص بعض عباده بالرحمة ليس لضيق فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص67، تحت البقرة: 105.","url":""}]},{"id":"s2-350","number":350,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما معنى النسخ والإنساء في قوله تعالى: ﴿ما ننسخ من آية أو ننسها﴾؟","answer":"النسخ إزالة حكم آية بحكم يتعقبه. وعلى قراءة الجمهور ﴿ننسها﴾ يكون معناها نزيلها من قلوب العباد أو نترك العمل بها، وعلى قراءة ﴿ننسأها﴾ يكون معناها نؤخر تلاوتها أو العمل بحكمها. والنسخ والإنساء طريقان ينتهيان إلى إزالة الحكم بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص69–70 و74–76، تحت البقرة: 106.","url":""}]},{"id":"s2-351","number":351,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما مناسبة ختم آية النسخ بقوله تعالى: ﴿ألم تعلم أن الله على كل شيء قدير﴾؟","answer":"ختمت الآية بإثبات القدرة لأن النسخ والإتيان بخير من الآية أو مثلها صادر عن قدرة الله، ولتقرير أن النسخ تكميل وتشريع محكم لا يعجزه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص72–73 و76–80، تحت البقرة: 106.","url":""}]},{"id":"s2-352","number":352,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما سرّ استعمال ﴿ما﴾ الشرطية في قوله تعالى: ﴿ما ننسخ من آية﴾ بدل «إن»؟","answer":"أفادت ﴿ما﴾ العموم؛ فالنسخ متصور الوقوع في كل آية، ثم جاءت ﴿من﴾ لتبين هذا العموم. كما حسنت الوقع الصوتي؛ لأن «إن ننسخ» تجمع نونات متوالية فيها ثقل، مع بقاء المعنى هو الأصل والصوت تابعًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص73، تحت البقرة: 106.","url":""}]},{"id":"s2-353","number":353,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما دلالة قوله تعالى: ﴿من آية﴾ مع إفراد ﴿آية﴾؟","answer":"جاءت ﴿من﴾ بيانًا للاسم الشرطي المبهم ﴿ما﴾، ووقعت ﴿آية﴾ نكرة في سياق الشرط فعمّت كل آية. وأفادت ﴿من﴾ أيضًا أن وقوع النسخ إنما يكون في بعض الآيات، مع إمكان تعلق الحكم بأي فرد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص74، تحت البقرة: 106.","url":""}]},{"id":"s2-354","number":354,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما معنى الخيرية في قوله تعالى عن الآية البديلة: ﴿نأت بخير منها﴾؟","answer":"تكون الآية البديلة خيرًا إما بخفة تكليفها مع ثبات الثواب، وإما بكثرة ثوابها وإن كان تكليفها أثقل. فالخيرية في حكمها للمكلفين، ولا تعني القدح في الآية المنسوخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص70–71 و79–80، تحت البقرة: 106.","url":""}]},{"id":"s2-355","number":355,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما فائدة قوله تعالى: ﴿أو مثلها﴾ بعد قوله: ﴿بخير منها﴾؟","answer":"بيّن العطف أن البديل قد يكون خيرًا من المنسوخ بما فيه من خفة أو زيادة ثواب، وقد يكون مماثلًا له في القدر والحكم؛ فشملت الآية القسمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص71 و75–76، تحت البقرة: 106.","url":""}]},{"id":"s2-356","number":356,"surah":2,"verses":[106],"verseLabel":"البقرة: 106","question":"ما سرّ التعبير بصفة ﴿قدير﴾ بدل «قادر» في ختام الآية؟","answer":"﴿قدير﴾ على وزن «فعيل»، وهي صيغة تدل على المبالغة وكثرة آثار القدرة وتكررها، بخلاف «قادر» الدال على مجرد صدور الفعل. وهذا أنسب بإحاطة قدرة الله بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص72 و77–78، تحت البقرة: 106.","url":""}]},{"id":"s2-357","number":357,"surah":2,"verses":[107],"verseLabel":"البقرة: 107","question":"ما دلالة الجمع بين ﴿ولي﴾ و﴿نصير﴾ في قوله تعالى: ﴿وما لكم من دون الله من ولي ولا نصير﴾؟","answer":"الولي هو القريب الذي يتولى أمر صاحبه ويرعاه، والنصير من يعينه ويدفع عنه ولو لم يكن وليًا. فنفى النص جهتي الحماية: الولاية القريبة والنصرة عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص86–87، تحت البقرة: 107.","url":""}]},{"id":"s2-358","number":358,"surah":2,"verses":[107],"verseLabel":"البقرة: 107","question":"ما دلالة تقديم ﴿له﴾ في قوله تعالى: ﴿أن الله له ملك السماوات والأرض﴾؟","answer":"يفيد تقديم الجار والمجرور الاختصاص؛ فملك السماوات والأرض لله وحده، وفيه تقرير سلطانه في التشريع والنسخ والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص84–85، تحت البقرة: 107.","url":""}]},{"id":"s2-359","number":359,"surah":2,"verses":[107],"verseLabel":"البقرة: 107","question":"ما مناسبة تقديم ﴿ولي﴾ على ﴿نصير﴾؟","answer":"الولي أقرب وأشمل؛ فهو يتولى أمر صاحبه ملازمةً، أما النصير فقد يكون من غير دائرة الولاية ولا يظهر إلا عند الحاجة. فنُفي الأقرب أولًا ثم ما قد يُتوهم من نصرة غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص86–87، تحت البقرة: 107.","url":""}]},{"id":"s2-360","number":360,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أم تريدون أن تسألوا رسولكم كما سئل موسى من قبل﴾؟","answer":"﴿أم﴾ للإضراب والانتقال إلى استفهام إنكاري عن إرادة السؤال المتعنت. وتوجيه الإنكار إلى الإرادة أبلغ في التحذير؛ لأن الإرادة تسبق الفعل، فنُهوا عن مبدئه قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص93–94، تحت البقرة: 108.","url":""}]},{"id":"s2-361","number":361,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما سرّ التعبير بـ﴿رسولكم﴾ بدل «نبيكم»؟","answer":"وُصف بالرسالة لأن السؤال المقترح متعلق برسالته، ولا سيما القرآن، لا بذاته ولا بثبوت نبوته؛ فناسب وصف الرسالة موضع التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص94–95، تحت البقرة: 108.","url":""}]},{"id":"s2-362","number":362,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما دلالة إضافة الرسول إلى المخاطبين في قوله تعالى: ﴿رسولكم﴾؟","answer":"تزيد الإضافة تبشيع سؤال التعنت؛ فهو رسولهم الذي يعرفون حرصه عليهم وحبه لهم ورحمته بهم، وفيها تحذير من مشابهة منهج بني إسرائيل في سؤال رسلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص95، تحت البقرة: 108.","url":""}]},{"id":"s2-363","number":363,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما سرّ بناء ﴿سئل موسى﴾ للمفعول؟","answer":"بُني الفعل للمفعول لأن السائلين لشناعة فعلهم يستحقون ألا يُذكروا، وفي ذلك تشنيع على حالهم وزيادة تحذير للمخاطبين من صنيعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص96، تحت البقرة: 108.","url":""}]},{"id":"s2-364","number":364,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما فائدة زيادة قوله تعالى: ﴿من قبل﴾ بعد قوله: ﴿كما سئل موسى﴾؟","answer":"زيد الظرف للتشنيع على سؤال التعنت، وهو يطلق ذهن السامع في تقدير السابقية: من قبل رسولكم، أو قبل نزول كتابكم، أو قبل ضلال السائلين وكفرهم؛ فالإطناب به أبلغ في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص96، تحت البقرة: 108.","url":""}]},{"id":"s2-365","number":365,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما معنى الباء في قوله تعالى: ﴿ومن يتبدل الكفر بالإيمان﴾؟","answer":"تحتمل الباء البدل والمقابلة، والمعنيان متقاربان: من يأخذ الكفر بدل الإيمان أو عوضًا عنه. وفي جمع الكفر والإيمان طباق يبرز قبح الكفر وجمال الإيمان وشدة خسارة من آثر الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص97–98، تحت البقرة: 108.","url":""}]},{"id":"s2-366","number":366,"surah":2,"verses":[108],"verseLabel":"البقرة: 108","question":"ما دلالة التعبير بقوله تعالى: ﴿فقد ضل سواء السبيل﴾؟","answer":"سواء السبيل وسط الطريق وأعدله، وهو الموضع الواضح الميسر. فمن استبدل الكفر بالإيمان لم يخطئ طرفًا من الطريق فحسب، بل ضل وسطه الواضح؛ وفي ذلك توبيخ وتشنيع أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص98، تحت البقرة: 108.","url":""}]},{"id":"s2-367","number":367,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما دلالة قوله تعالى: ﴿يردونكم من بعد إيمانكم كفارًا﴾؟","answer":"أفاد فعل الرد أنهم يودون إرجاع المؤمنين إلى حال الكفر السابقة، ولفظ ﴿كفارًا﴾ بصيغة جمع الكثرة يدل على تمني ردهم جميعًا. أما ﴿من بعد إيمانكم﴾ فتصور رغبتهم في إزالة ما اكتسبه المؤمنون بالإسلام حتى يرجعوا إلى حالهم الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص105–106، تحت البقرة: 109.","url":""}]},{"id":"s2-368","number":368,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما سرّ الجمع بين العفو والصفح في قوله تعالى: ﴿فاعفوا واصفحوا﴾؟","answer":"العفو ترك عقاب المذنب، والصفح ترك لومه وتثريبه والإعراض عن ذنبه. فالجمع بينهما يحقق الشمول في الجانب المادي بترك العقوبة، وفي الجانب النفسي والمعنوي بترك اللوم، والصفح أبلغ من العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص111–112، تحت البقرة: 109.","url":""}]},{"id":"s2-369","number":369,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما دلالة التعبير بـ﴿كثير﴾ في قوله تعالى: ﴿ود كثير من أهل الكتاب﴾؟","answer":"يدل ﴿كثير﴾ على أن هذا الود صدر عن عدد كثير من أهل الكتاب، لا عن جميعهم ولا عن أكثرهم، مع أنهم ليسوا عددًا قليلًا. وفي ذلك دقة وعدل في نسبة الموقف إلى أصحابه، وإشارة إلى وجود من يُرجى إيمانه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص105، تحت البقرة: 109.","url":""}]},{"id":"s2-370","number":370,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿كُفَّارًا﴾ بصيغة الجمع المكثّر، دون أن يقال: «كافرين»؟","answer":"﴿كفار﴾ من صيغ جمع التكسير الدالة على الكثرة، فناسبت تمنيهم رد المؤمنين جميعًا إلى الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص105، تحت البقرة: 109، في بلاغة اختيار صيغة ﴿كفارًا﴾.","url":""}]},{"id":"s2-371","number":371,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ إِيمَانِكُمْ﴾، ولم يكتفِ بقوله: «بعد إيمانكم»؟","answer":"دخول ﴿من﴾ على ﴿بعد﴾ يصور إرادتهم إرجاع المؤمنين من حال الإيمان إلى حالة الكفر الأولى، بحيث لا يبقى معهم أثر مما اكتسبوه بالإسلام؛ وفيه بيان عمق حسدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص105–106، تحت البقرة: 109، في حرف ابتداء الغاية.","url":""}]},{"id":"s2-372","number":372,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿حَسَدًا مِنْ عِنْدِ أَنْفُسِهِمْ﴾، أليس الحسد بطبيعته صادرًا من النفس؟","answer":"أكد قوله ﴿من عند أنفسهم﴾ أن الحسد متأصل في نفوسهم وصادر منها، لا عن حجة أو شبهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص107–108، تحت البقرة: 109، في تصوير ﴿من عند أنفسهم﴾.","url":""}]},{"id":"s2-373","number":373,"surah":2,"verses":[109],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْحَقُّ﴾، ولم يكتفِ بذكر حسدهم؟","answer":"بيّن القيد أنهم تمنوا رد المؤمنين بعد أن ظهر لهم الحق، فكان فعلهم عنادًا وحسدًا لا التباسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص108–110، تحت البقرة: 109، في قيد ﴿من بعد ما تبين لهم الحق﴾.","url":""}]},{"id":"s2-374","number":374,"surah":2,"verses":[110],"verseLabel":"البقرة: 110","question":"ما مناسبة تقديم الصلاة على الزكاة في قوله: ﴿وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ﴾؟","answer":"الصلاة أصل يومي عام لكل مسلم وعماد قبول سائر العمل، أما الزكاة فلا تجب إلا على من ملك النصاب وحال عليه الحول. وهي تصلح الفرد أولًا بصلته بربه، ثم تأتي الزكاة لتصلح علاقة المجتمع؛ فقدم الأعم والأصل وما يتكرر في الزمن على الفرع الأخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص118–120، تحت البقرة: 110، في نكات تقديم الصلاة على الزكاة.","url":""}]},{"id":"s2-375","number":375,"surah":2,"verses":[110],"verseLabel":"البقرة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿وَآتُوا الزَّكَاةَ﴾ ولم يذكر من تُعطى لهم؟","answer":"حُذف المفعول الثاني ليتجه الاهتمام إلى إيتاء الزكاة نفسه، مع العلم بمستحقيها من أحكام الشرع، وليعم الأمر أداءها إلى كل مستحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص118–119، تحت البقرة: 110، في حذف المفعول الثاني لفعل ﴿آتوا﴾.","url":""}]},{"id":"s2-376","number":376,"surah":2,"verses":[110],"verseLabel":"البقرة: 110","question":"ما سرّ تعميم قوله تعالى: ﴿وما تقدموا لأنفسكم من خير﴾ بعد الأمر بالصلاة والزكاة؟","answer":"ذكر الصلاة والزكاة بوصفهما أصلين عظيمين، ثم عمم بعد الخاص ليشمل كل بر: فرضًا أو نافلة، بدنيًا أو ماليًا، كثيرًا أو قليلًا. فالجملة لا تكرر ما قبلها، بل تفتح الباب من المثالين الأبرز إلى بنك العمل الصالح كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص119–120، تحت البقرة: 110، في عطف العام على الخاص.","url":""}]},{"id":"s2-377","number":377,"surah":2,"verses":[110],"verseLabel":"البقرة: 110","question":"ما مناسبة تقديم ﴿لِأَنْفُسِكُمْ﴾ على ﴿مِنْ خَيْرٍ﴾؟","answer":"قدم الغاية على الوسيلة لتحريك أقوى باعث في النفس: كل خير تبذله يعود نفعه إليك أنت. فقبل أن يذكر نوع الخير نبّه إلى صاحبه الحقيقي، وبذلك يحض الإنسان على العمل من باب حرصه الفطري على ما ينجيه وينفعه في آخرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص120–121، تحت البقرة: 110، في تقديم الغاية على الوسيلة.","url":""}]},{"id":"s2-378","number":378,"surah":2,"verses":[110],"verseLabel":"البقرة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجِدُوهُ عِنْدَ اللَّهِ﴾، دون أن يقال: «تجدوا ثوابه»؟","answer":"صُوّر الخير نفسه محفوظًا حاضرًا عند الله، لا مجرد وعد غائب بنتيجته؛ وفي ذلك تجسيم معنوي للثواب يزيد اليقين والترغيب. وحذف كلمة «ثوابه» يجعل الصلة بين العمل والجزاء أشد: ما قدمته لا يضيع ولا يتبدل، بل تلقاه كأنه هو بعينه محفوظ في أشرف موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص121–122، تحت البقرة: 110، في فائدة التعبير بالظرف ﴿عند الله﴾.","url":""}]},{"id":"s2-379","number":379,"surah":2,"verses":[110],"verseLabel":"البقرة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ﴾ فقدم ﴿بما تعملون﴾، دون أن يقال: «إن الله بصير بما تعملون»؟","answer":"قدم العمل لأنه محور الآية من الصلاة والزكاة وكل خير يُقدَّم، فناسب أن يبقى في واجهة الخاتمة. وفي التقديم تقوية للعناية والمراقبة: أعمالكم كلها هي محل البصر الإلهي، فيستوي ظاهرها وخفيها ولا يضيع منها شيء، ثم جاءت ﴿بصير﴾ فاصلةً ثابتة تناسب هذا المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص122–123، تحت البقرة: 110، في تقديم ﴿بما تعملون﴾ على ﴿بصير﴾.","url":""}]},{"id":"s2-380","number":380,"surah":2,"verses":[111],"verseLabel":"البقرة: 111","question":"ما سرّ جمع اليهود والنصارى في ضمير واحد في قوله تعالى: ﴿وقالوا﴾، ثم تفريق قولهما: ﴿إلا من كان هودًا أو نصارى﴾؟","answer":"جمعهما أولًا لأنهما اشتركا في أصل الباطل: احتكار الجنة وإقصاء غيرهما، ثم نشر القول على الفريقين؛ فاليهود تزعمها لليهود، والنصارى تزعمها للنصارى. وهذا اللف والنشر يوجز عبارتين متقابلتين، ويبقي ذهن القارئ متيقظًا ليرد كل دعوى إلى صاحبها، ويكشف أن الخصمين متفقان في الهوى وإن تناقضا في التعيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص127–128، تحت البقرة: 111، في بلاغة اللف والنشر والجمع في الضمير.","url":""}]},{"id":"s2-381","number":381,"surah":2,"verses":[111],"verseLabel":"البقرة: 111","question":"ما دلالة قولهم: ﴿لَنْ يَدْخُلَ الْجَنَّةَ﴾ بـ﴿لن﴾ دون «لا يدخل الجنة»؟","answer":"لأن دعواهم متعلقة بالمستقبل الأخروي، فجاءت ﴿لن﴾ لتصوغ ادعاءهم في صورة نفي قاطع ممتد إلى الآخرة، لا نفي حالة حاضرة فحسب. والمبالغة في القطع تناسب جرأتهم على الغيب واحتكارهم المصير بغير برهان؛ ولذلك أعقبتها الآية بتحديهم أن يأتوا بالحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص127–130، تحت البقرة: 111، في بناء دعوى حصر دخول الجنة ومناقضتها بالبرهان.","url":""}]},{"id":"s2-382","number":382,"surah":2,"verses":[111],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ أَمَانِيُّهُمْ﴾ باسم الإشارة للبعيد، دون أن يقال: «هذه أمانيهم»؟","answer":"أشير إلى أمانيهم باسم البعيد لتحقيرها وإبعادها عن الحق والواقع، وللتنبيه إلى بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص128–129، تحت البقرة: 111، في استعمال اسم الإشارة للبعيد دون القريب.","url":""}]},{"id":"s2-383","number":383,"surah":2,"verses":[111],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمَانِيُّهُمْ﴾ بالجمع، مع أن المذكور أمنية واحدة هي دخول الجنة؟","answer":"جُمعت ﴿أماني﴾ لأن الدعوى صدرت من فريقين، ولكل فريق أمنيته، ولأنها جنس يضم أمانيهم الباطلة المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص126–130، تحت البقرة: 111، في العدول من الإفراد إلى الجمع في ﴿أمانيهم﴾.","url":""}]},{"id":"s2-384","number":384,"surah":2,"verses":[111],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿هَاتُوا بُرْهَانَكُمْ﴾، دون أن يقال: «هاتوا دليلكم»؟","answer":"البرهان أخص من مطلق الدليل وأقوى ظهورًا في إثبات صدق الدعوى؛ فالدليل قد يكون علامة أو قولًا يُستدل به، أما البرهان فلا يسمى كذلك إلا إذا أظهر صحة المدعى. ولأنهم حكموا في أعظم الغيوب حكمًا قاطعًا، طولبوا بأقوى درجات الحجة لا بمجرد شبهة يحتجون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص130–131، تحت البقرة: 111، في الفرق بين البرهان والدليل.","url":""}]},{"id":"s2-385","number":385,"surah":2,"verses":[111],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ كُنْتُمْ صَادِقِينَ﴾، دون أن يقال مباشرة: «وأنتم كاذبون»؟","answer":"الشرط يضع دعواهم أمام اختبار عملي: إن كان الصدق قائمًا فموضعه البرهان. وفيه تعريض بالكذب أبلغ من التصريح؛ لأن عجزهم عن إحضار الحجة هو الذي يكشفهم، كما أن تقديم جواب الشرط ﴿هاتوا برهانكم﴾ يجعل مدار المحاجة كله على الدليل لا على مجرد تبادل الاتهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص129–130، تحت البقرة: 111، في بلاغة الجملة الشرطية والتعريض بكذبهم.","url":""}]},{"id":"s2-386","number":386,"surah":2,"verses":[112],"verseLabel":"البقرة: 112","question":"ما سرّ ابتداء الرد بقوله: ﴿بَلَى﴾، ولم يقل: «نعم»؟","answer":"لأن كلامهم تضمن نفي دخول الجنة عن غير اليهود أو النصارى، و﴿بلى﴾ هي التي تنقض النفي وتثبت ضده؛ أما «نعم» فتصدق الكلام السابق على وجهه وقد توهم إقرار النفي. فجاء حرف واحد يهدم الاحتكار كله، ثم يقرر المعيار الصحيح لدخول الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص132 و135، تحت البقرة: 112، في مناسبة ﴿بلى﴾ لما قبلها ودلالتها على إبطال النفي.","url":""}]},{"id":"s2-387","number":387,"surah":2,"verses":[112],"verseLabel":"البقرة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿أَسْلَمَ وَجْهَهُ لِلَّهِ﴾، دون أن يقال: «أسلم نفسه لله»؟","answer":"عُبّر بالوجه عن الذات كلها لأنه أشرف ما يظهر من الإنسان وأول ما يتجه به إلى مقصده؛ فإذا سلّم وجهه لله دل ذلك على إخلاص توجهه وانقياد ذاته بلا التفات إلى غيره. فذكر الجزء الأظهر يصور استسلام الكل تصويرًا محسوسًا، ويضيف معنى القصد والتوجه الذي لا تؤديه «نفسه» بالقوة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص132–133، تحت البقرة: 112، في دلالة ﴿أسلم وجهه﴾ والتعبير بالجزء عن الذات.","url":""}]},{"id":"s2-388","number":388,"surah":2,"verses":[112],"verseLabel":"البقرة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ أَسْلَمَ﴾ بالماضي، دون أن يقال: «من يُسلم وجهه»؟","answer":"جاء ﴿أسلم﴾ بالماضي للدلالة على تحقق الإسلام وثبوته، لا على مجرد دعوى أو نية مؤجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص132 و136، تحت البقرة: 112، في التعبير بالفعل الماضي ﴿أسلم﴾.","url":""}]},{"id":"s2-389","number":389,"surah":2,"verses":[112],"verseLabel":"البقرة: 112","question":"إذا أسلم الإنسان وجهه لله، فلماذا زاد: ﴿وَهُوَ مُحْسِنٌ﴾؟","answer":"لأن مجرد الانقياد الظاهر لا يكفي حتى يكون العمل حسنًا موافقًا للحق؛ فقد يتواضع المرء أو يتعبد على صورة فاسدة. فجمعت الآية إخلاص الوجه لله مع إحسان العمل، أي صحة القصد وصحة الفعل، وبذلك أبطلت النجاة بالانتساب المجرد من جهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص133 و136–137، تحت البقرة: 112، في فائدة الحال ﴿وهو محسن﴾.","url":""}]},{"id":"s2-390","number":390,"surah":2,"verses":[112],"verseLabel":"البقرة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَهُ أَجْرُهُ عِنْدَ رَبِّهِ﴾، دون أن يقال: «فسيؤتيه الله أجرًا»؟","answer":"اللام تفيد أن الأجر صار حقًا موعودًا مختصًا بصاحبه، وإضافة الأجر إليه تشعر بأنه الجزاء الموافق لعمله، و﴿عند ربه﴾ تصوره محفوظًا في أضمن موضع. واختيار «ربه» يفتح معنى الرعاية والتربية والتدبير؛ فالذي ربّاه في الدنيا لا يضيّع إحسانه في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص133–137، تحت البقرة: 112، في ألفاظ الأجر والرب وبناء جملة الجزاء.","url":""}]},{"id":"s2-391","number":391,"surah":2,"verses":[112],"verseLabel":"البقرة: 112","question":"ما دلالة الانتقال من الإفراد في قوله تعالى: ﴿من أسلم وجهه... فله أجره﴾ إلى الجمع في قوله: ﴿عليهم... هم يحزنون﴾؟","answer":"روعي أولًا لفظ ﴿من﴾ المفرد لتصوير مسؤولية كل إنسان وحده: إسلامه وإحسانه وأجره، ثم روعي معناها العام فانتقل إلى الجمع عند الحديث عن المآل الذي تشترك فيه الجماعة كلها. فالتحول ليس اضطرابًا، بل انتقال من عمل الفرد وحسابه إلى أمان المؤمنين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص139–140، تحت البقرة: 112، في المغايرة بين الإفراد والجمع ومراعاة لفظ ﴿من﴾ ومعناها.","url":""}]},{"id":"s2-392","number":392,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿قَالَتِ الْيَهُودُ﴾ و﴿قَالَتِ النَّصَارَى﴾ بتأنيث الفعل؟","answer":"لأن اسمي اليهود والنصارى أُخذا هنا باعتبار الجماعة أو الطائفة، فأنّث الفعل مراعاة لهذا المعنى. وهذا التصوير ينسب القول إلى الطائفة بوصفه موقفًا جماعيًا متداولًا فيها، لا زلة فرد منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص143–144، تحت البقرة: 113، في تأنيث الفعل المسند إلى اليهود والنصارى.","url":""}]},{"id":"s2-393","number":393,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ صياغة قول اليهود والنصارى في عبارتين متطابقتين تقريبًا: ﴿لَيْسَتِ النَّصَارَى عَلَى شَيْءٍ﴾ و﴿لَيْسَتِ الْيَهُودُ عَلَى شَيْءٍ﴾؟","answer":"التماثل اللفظي يجعل كل فريق مرآة للآخر: العبارة نفسها والحكم المتعجل نفسه، ولا يختلف إلا اسم الخصم. وبذلك يكشف النظم تناقضهما وعدله في نقل القولين، ويبين أن التعصب يعيد المنطق ذاته على لسان فريقين يزعم كل منهما احتكار الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص143–145، تحت البقرة: 113، في عطف القول على القول وبيان الأقوال المتناقضة.","url":""}]},{"id":"s2-394","number":394,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُمْ يَتْلُونَ الْكِتَابَ﴾ بعد حكاية إنكار كل فريق للآخر؟","answer":"لأن موضع الدهشة ليس مجرد اختلافهما، بل أنهما يطلقان هذا النفي الشامل وهما يقرآن كتابًا يهدي إلى التثبت ويشهد بأصول من الحق عرفها الطرفان. فجاءت الحال لتضاعف التوبيخ: الجاهل قد يتعجل، أما من يتلو الوحي ثم يتكلم بمنطق الهوى فمناقضته أفضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص141 و146–147، تحت البقرة: 113، في دلالة الحال ﴿وهم يتلون الكتاب﴾.","url":""}]},{"id":"s2-395","number":395,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يَعْلَمُونَ﴾، ولم يسمِّ المشركين صراحة؟","answer":"الوصف يعلّق الذم بعلته: قولهم ناشئ عن الجهل، ويدخل فيه كل من يكرر الحكم نفسه بلا علم، لا جماعة تاريخية واحدة فقط. كما أن تسوية أهل الكتاب، مع ما عندهم من علم، بمن لا يعلم أشد تقريعًا لهم من مجرد تسمية المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص141 و147–148، تحت البقرة: 113، في التعبير بالموصول ﴿الذين لا يعلمون﴾ والتسوية بأهل الجهل.","url":""}]},{"id":"s2-396","number":396,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ الجمع بين ﴿كَذَلِكَ﴾ و﴿مِثْلَ قَوْلِهِمْ﴾؛ أليس أحد التعبيرين كافيًا للدلالة على التشابه؟","answer":"﴿كذلك﴾ تربط طريقة القول وحال قائليه بما سبق، ثم يحدد ﴿مثل قولهم﴾ موضع المماثلة فلا يتوهم أن التشبيه في كل الأحوال والصفات. فالأول يلفت إلى تكرار النمط، والثاني يضبطه في القول المتعصب نفسه، فيجتمع التأكيد مع الدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص147–149، تحت البقرة: 113، في بناء التشبيه بقوله ﴿كذلك... مثل قولهم﴾.","url":""}]},{"id":"s2-397","number":397,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاللَّهُ يَحْكُمُ بَيْنَهُمْ﴾، ولم يجعل الحكم للكتاب الذي كانوا يتلونه؟","answer":"أسند الحكم إلى الله لأنه الحكم الفصل الذي لا يدخله تحريف ولا هوى، وجاءت الفاء لتفريع هذا الحكم على تناقض الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص149–151، تحت البقرة: 113، في ترتيب جملة الحكم واتصالها بتناقض الفريقين.","url":""}]},{"id":"s2-398","number":398,"surah":2,"verses":[113],"verseLabel":"البقرة: 113","question":"ما سرّ تأخير الفصل في اختلافهم إلى ﴿يَوْمَ الْقِيَامَةِ﴾؟","answer":"خُص يوم القيامة لأن الحكم فيه يقترن بإظهار الجزاء وانقطاع الخصومة، مع أن الحجة قائمة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص141–142 و149–151، تحت البقرة: 113، في معنى الحكم يوم القيامة ومناسبة ختم الآية به.","url":""}]},{"id":"s2-399","number":399,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما وجه وصف أكثر من جريمة في القرآن بأنها الأظلم في قوله ﴿وَمَنْ أَظْلَمُ﴾؛ مع أن «الأظلم» واحد؟","answer":"الاستفهام ينفي أن يوجد من هو أشد ظلمًا من صاحب الجريمة في بابها وسياقها، ولا يلزم أن تكون كل الآيات ترتيبًا حسابيًا لجميع الجرائم في قائمة واحدة. وقد تتساوى صور متعددة في بلوغ الغاية من الظلم، أو يكون كل وصف أظلم من جهة مخصوصة؛ وهنا بلغ الظلم ذروته لأنه صدّ الناس عن بيوت الله وعمل في خرابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص155–158، تحت البقرة: 114، في أسلوب ﴿ومن أظلم﴾ وتعدد وروده في القرآن.","url":""}]},{"id":"s2-400","number":400,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يُذْكَرَ فِيهَا اسْمُهُ﴾، دون أن يقال: «أن يُعبد الله فيها»؟","answer":"ذكر اسم الله أوسع من صورة عبادة واحدة؛ فهو يشمل الصلاة والتلاوة والدعاء والتعليم وكل ما يعمر المسجد بذكره. كما أن إضافة الاسم إلى ضميره تستحضر أن المساجد إنما شرفت بمن يُذكر فيها، فيبدو منع أي مظهر من هذه المظاهر اعتداءً على الغاية التي بنيت لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص152 و158–159، تحت البقرة: 114، في دلالة ﴿أن يذكر فيها اسمه﴾.","url":""}]},{"id":"s2-401","number":401,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يُذْكَرَ﴾ بالبناء للمجهول، دون أن يقال: «أن يذكر المؤمنون»؟","answer":"حُذف الذاكر ليعم الحكم كل ذاكر وكل لون مشروع من الذكر؛ فالجريمة ليست منع فئة مسماة، بل منع أن يقع ذكر الله أصلًا في مساجده. كما تتجه العناية إلى الفعل الممنوع وإلى قدسية المكان، لا إلى هوية من يؤديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص158–159، تحت البقرة: 114، في حذف الفاعل من ﴿يذكر﴾ وعموم المعنى.","url":""}]},{"id":"s2-402","number":402,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما مناسبة تقديم ﴿فِيهَا﴾ فقال: ﴿أَنْ يُذْكَرَ فِيهَا اسْمُهُ﴾، ولم يقل: «أن يذكر اسمه فيها»؟","answer":"لأن المساجد هي محور الجريمة والسياق؛ فقدم مكان الذكر لتبقى حرمتها في الواجهة، ولينبه إلى فظاعة أن يقع المنع في الموضع المعد أصلًا لهذه الغاية. ثم جاء ﴿اسمه﴾ بعد تشويق السامع: ما الذي مُنع في هذه البيوت؟","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص159، تحت البقرة: 114، في تقديم ﴿فيها﴾ على نائب الفاعل ﴿اسمه﴾.","url":""}]},{"id":"s2-403","number":403,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَعَى فِي خَرَابِهَا﴾، دون أن يقال: «وخرّبها»؟","answer":"السعي يصور قصدًا وحركةً وبذل جهد في الوصول إلى الخراب، فيشمل الهدم الحسي وتعطيل العبادة وصد الناس وكل مقدمة توصل إلى ذلك. أما «خربها» فتحصر النظر غالبًا في النتيجة الواقعة؛ فجاء اللفظ ليجرّم المشروع والمسار ولو لم يكتمل أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص159–161، تحت البقرة: 114، في دلالة ﴿سعى في خرابها﴾ واتساع معنى الخراب.","url":""}]},{"id":"s2-404","number":404,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا كَانَ لَهُمْ أَنْ يَدْخُلُوهَا إِلَّا خَائِفِينَ﴾، دون أن يقال: «لا يدخلونها إلا خائفين»؟","answer":"﴿ما كان لهم﴾ تنفي الاستحقاق واللياقة، لا مجرد وقوع الدخول؛ أي ما صح ولا استقام لهؤلاء أن يدخلوها آمنين بعد أن منعوا أهلها وسعوا في خرابها. والاستثناء يقلب صورة قوتهم: المكان الذي استباحوه ينبغي أن لا يدخلوه إلا في ذلة وخوف من المؤمنين أو من عقاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص160–162، تحت البقرة: 114، في تركيب ﴿ما كان لهم﴾ والاستثناء بـ﴿إلا خائفين﴾.","url":""}]},{"id":"s2-405","number":405,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما دلالة تكرار ﴿لَهُمْ﴾ فقال: ﴿لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ﴾؟","answer":"أعيد الجار والمجرور ليجعل كل جزاء حكمًا مستقلًا محققًا لهم: خزي في دار، وعذاب في دار أخرى؛ فلا يكون الثاني تابعًا لفظيًا عابرًا للأول. والتكرار يقابل جريمتهم المزدوجة، منع الذكر والسعي في الخراب، بجزاء يلاحقهم في المرحلتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص162–164، تحت البقرة: 114، في تكرير ﴿لهم﴾ وتوزيع الجزاء بين الدارين.","url":""}]},{"id":"s2-406","number":406,"surah":2,"verses":[114],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿خِزْيٌ﴾ بالتنكير، دون أن يقال: «الخزي»؟","answer":"التنكير يفخم خزيًا لا يحيط السامع بمقداره، ويترك صوره مفتوحة: ذلة وفضيحة وقهر بعد استعلاء. فهو لا يشير إلى خزي معروف محدود، بل يوحي بنوع عظيم من الهوان يناسب شناعة منع بيوت الله من وظيفتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص162–163، تحت البقرة: 114، في تنكير ﴿خزي﴾.","url":""}]},{"id":"s2-407","number":407,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"كيف يُفهم قوله تعالى: ﴿فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ﴾ مع وجود قبلة مأمور بها؟","answer":"تقرر الآية أن الجهات كلها لله، وأن التوجه المأذون فيه حيثما كان لا يخرج عن ملكه. وحُملت عند المفسرين على أحوال منها النافلة في السفر وحال العذر، من غير أن تبطل حكم القبلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص165–171، تحت البقرة: 115.","url":""}]},{"id":"s2-408","number":408,"surah":2,"verses":[17],"verseLabel":"البقرة: 115 و142، الرحمن: 17","question":"ما سرّ الإفراد في قوله تعالى في البقرة: ﴿ولله المشرق والمغرب﴾، والتثنية في الرحمن: ﴿رب المشرقين ورب المغربين﴾؟","answer":"أفردت البقرة المشرق والمغرب باعتبار الجهتين العامتين اللتين تحيطان بكل مواضع الشروق والغروب؛ وهو الأنسب في حجة القبلة: الجهات كلها لله، فأينما وُجّه العبد فهو داخل ملكه. أما التثنية في الرحمن فتلحظ مشرق الشمس ومغربها في أقصى الصيف وأقصى الشتاء، أو مشرقي الشمس والقمر ومغربيهما؛ فتفصّل آية كونية متجددة في سورة تعداد النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص742–744، تحت الرحمن: 17، في بيان الإفراد والتثنية والجمع في المشارق والمغارب، مع المقارنة بالبقرة: 115 و142.","url":""}]},{"id":"s2-409","number":409,"surah":2,"verses":[17],"verseLabel":"البقرة: 115 و142، الرحمن: 17","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ولله المشرق والمغرب﴾، وقوله في الرحمن: ﴿رب المشرقين ورب المغربين﴾؟","answer":"مقام البقرة في تحويل القبلة وإبطال تعلق الاعتراض بجهة بعينها؛ فناسب إسناد المشرق والمغرب إلى الله بلام الملك والاختصاص: الجهات كلها له وهو الذي يهدي إلى القبلة التي يشاء. أما الرحمن فسورة امتنان متتابع على الإنس والجن، فاختير لفظ ﴿رب﴾ الدال على التدبير والتربية، وكرر مع الطرفين لتأكيد أن تدبير المشارق والمغارب وما ينشأ عنهما من المنافع نعمة ربانية شاملة للجنسين المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص744–745، تحت الرحمن: 17، في مبحث إضافة المشرقين إلى الربوبية وتكرار لفظ ﴿رب﴾، مع المقارنة بالبقرة: 115 و142.","url":""}]},{"id":"s2-410","number":410,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"ما مناسبة تقديم ﴿الْمَشْرِقُ﴾ على ﴿الْمَغْرِبُ﴾؟","answer":"لأن الشروق بداية الحركة والضياء، والغروب نهايتها وبداية الظلمة؛ فوافق الترتيب مسار اليوم من المبدأ إلى المنتهى. كما أن مواقيت الصلاة تتبع هذه الدورة، فجرى اللفظ على النظام الكوني والشرعي الذي يبدأ بالظهور ثم ينتهي بالأفول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص168–169، تحت البقرة: 115، في دلالة تقديم المشرق على المغرب.","url":""}]},{"id":"s2-411","number":411,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَيْنَمَا تُوَلُّوا﴾ ولم يذكر ما الذي يولّون إليه وجوههم؟","answer":"حذف جهة التولية ليعم كل اتجاه تصح إليه الصلاة في الأحوال التي تبينها الشريعة؛ فلا يحبس المعنى في جهة واحدة مذكورة. والسياق نفسه يملأ المحذوف: أي جهة تستقبلونها أو تنصرفون إليها، فهي داخل ملك الله وعلمه، لا تخرجون بالتوجه عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص165–168، تحت البقرة: 115، في الإيجاز بالحذف ودلالة فعل ﴿تولوا﴾.","url":""}]},{"id":"s2-412","number":412,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"ما معنى قوله تعالى: ﴿فثم وجه الله﴾، وما سرّ هذا التعبير؟","answer":"ذُكرت في معنى ﴿وجه الله﴾ أقوال، منها: الجهة التي أمر الله بالتوجه إليها، ومنها رضاه وقبوله وثوابه، وكلها تنزه الله عن الحلول في جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص165–166 و169، تحت البقرة: 115، في المعنى المعجمي والبياني لـ﴿وجه الله﴾.","url":""}]},{"id":"s2-413","number":413,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله واسع عليم﴾ وترتيب الاسمين على هذا الوجه؟","answer":"﴿واسع﴾ تناسب أولًا اتساع الجهات والمشرق والمغرب وسعة الرحمة والرخصة، ثم تأتي ﴿عليم﴾ لتقرر أنه يعلم وجهة كل مصلٍّ ونيته وعذره فلا يلتبس عليه اختلاف الأماكن. فبدأ بالصفة التي تجيب عن ضيق الجهة، ثم ختم بالعلم الذي يحيط بمن يتوجه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص166–170، تحت البقرة: 115، في مناسبة اسمي الله ﴿واسع عليم﴾ وترتيبهما للسياق.","url":""}]},{"id":"s2-414","number":414,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ﴾ فقدم ﴿لله﴾، دون أن يقال: «والمشرق والمغرب لله»؟","answer":"التقديم يفيد الاختصاص والقصر: الجهات كلها ملك لله وتحت تدبيره، فلا تستقل جهة بقداسة من ذاتها ولا يملك معترض أن يحجر أمر القبلة عليها. وفيه تشويق أيضًا؛ فبعد ذكر خزي الظالمين يتطلع السامع إلى ما اختص الله به، فإذا الجواب محيط بطرفي الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص167، تحت البقرة: 115، في تقديم الجار والمجرور للاختصاص والقصر والتشويق.","url":""}]},{"id":"s2-415","number":415,"surah":2,"verses":[115],"verseLabel":"البقرة: 115","question":"ما سرّ الاقتصار على ﴿المشرق والمغرب﴾ مع أن بينهما جهات كثيرة؟","answer":"عطف الطرف المقابل على مقابله يفيد الإحاطة بما بينهما؛ فذكر المشرق والمغرب يغني عن تعداد الشمال والجنوب وسائر الجهات، وكأن التقدير: لله المشرق والمغرب وما بينهما. وهذا الإيجاز يخدم المقصود مباشرة: أينما يقع التوجه فهو داخل هذا الملك الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص167–168، تحت البقرة: 115، في عطف المتقابلين وتقدير المحذوف الدال على الشمول.","url":""}]},{"id":"s2-416","number":416,"surah":2,"verses":[116],"verseLabel":"البقرة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿اتخذ الله ولدًا﴾ لا: وَلَد الله ولدًا؟","answer":"اختير ﴿اتخذ﴾ لأن الدعوى باطلة مصنوعة لا حقيقة لها، ولأن الاتخاذ أعم من الولادة؛ ثم أبطلها دليل الملك والقنوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص171–178، تحت البقرة: 116.","url":""}]},{"id":"s2-417","number":417,"surah":2,"verses":[68],"verseLabel":"البقرة: 116، يونس: 68","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا﴾ بالواو، وقوله تعالى في يونس: ﴿قَالُوا اتَّخَذَ اللَّهُ وَلَدًا﴾ دون واو؟","answer":"عطفت البقرة هذه المقالة على سلسلة أقوال سبقتها، وهي تشمل افتراءات فرق متعددة: اليهود والنصارى والمشركين؛ فناسب وصلها بالواو بما قبلها. أما آية يونس ففي كفار قريش خاصة، وجاءت بيانًا مستقلًا لما سبق من حالهم، ففُصلت الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص172–173، تحت البقرة: 116، في المقارنة بيونس: 68.","url":""}]},{"id":"s2-418","number":418,"surah":2,"verses":[116],"verseLabel":"البقرة: 116","question":"ما سرّ مجيء التنزيه فور دعواهم فقال: ﴿وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا سُبْحَانَهُ﴾، ولم يبدأ بإقامة الدليل على بطلانها؟","answer":"لأن الدعوى من الشناعة بحيث لا تنتظر تفصيل الرد؛ فبادر القرآن بتنزيه الله عنها قبل مناقشتها، وفي ﴿سبحانه﴾ تعجب من جرأتهم مع إعلان براءة الله من النقص. ثم جاءت الحجة بعدها: من يملك السماوات والأرض ويقنت له الجميع لا يحتاج إلى ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص171–173، تحت البقرة: 116، في مناسبة ﴿سبحانه﴾ وبناء الرد على دعوى الولد.","url":""}]},{"id":"s2-419","number":419,"surah":2,"verses":[116],"verseLabel":"البقرة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿بَلْ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، ولم يكتفِ بقوله: «ليس له ولد»؟","answer":"لم يكتفِ بنفي الدعوى، بل انتقل بـ﴿بل﴾ إلى حقيقة تهدم أصلها: كل من زعموه ولدًا داخل في ملك الله وعبوديته. فالولد يكون من جنس والده ويشاركه، أما المملوك القانت فلا يكون ولدًا لمالكه؛ وهكذا صار الإثبات أبلغ من مجرد النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص172–175، تحت البقرة: 116، في الإضراب بـ﴿بل﴾ والاستدلال بالملك والقنوت.","url":""}]},{"id":"s2-420","number":420,"surah":2,"verses":[116],"verseLabel":"البقرة: 116","question":"ما مناسبة تقديم ﴿لَهُ﴾ فقال: ﴿لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، ولم يقل: «ما في السماوات والأرض له»؟","answer":"التقديم يفيد اختصاص الملك بالله: كل ما في الكون له وحده خلقًا وتدبيرًا وعبودية. وهذه الخصوصية هي قلب الحجة؛ إذ تنفي أن يكون في ملكه شريك أو ولد يخرج عن سلطان العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص174–175، تحت البقرة: 116، في تقديم الخبر ﴿له﴾ للاختصاص.","url":""}]},{"id":"s2-421","number":421,"surah":2,"verses":[116],"verseLabel":"البقرة: 116","question":"ما مناسبة تقديم السماوات على الأرض في قوله: ﴿مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"لأنها أعلى وأعظم وأوسع، وتحوي من المخلوقات ما لا تحويه الأرض، فبدأ بالأعظم الحاوي ثم عطف عليه ما دونه. كما جرى أكثر القرآن على هذا الترتيب الموافق لما يشاهده الإنسان من علو السماء وإحاطتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص175–176، تحت البقرة: 116، في نكتة تقديم السماوات على الأرض.","url":""}]},{"id":"s2-422","number":422,"surah":2,"verses":[116],"verseLabel":"البقرة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلٌّ لَهُ قَانِتُونَ﴾ بالجمع، مع أن لفظ ﴿كل﴾ مفرد؟","answer":"روعي معنى ﴿كل﴾ لا لفظها؛ فهي تستغرق مخلوقات كثيرة، فجاء الخبر جمعًا ليظهر هذا العموم. والتعبير بـ﴿قانتون﴾ يصورهم عقلاء خاضعين طائعين، وفي ذلك تشريف لمن أطاع وتغليب لذوي الإدراك، مع تقرير أن الجميع تحت أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص175–177، تحت البقرة: 116، في الجمع في ﴿قانتون﴾ ومراعاة معنى ﴿كل﴾.","url":""}]},{"id":"s2-423","number":423,"surah":2,"verses":[117],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ﴾، دون أن يقال: «خالق السماوات والأرض»؟","answer":"الخلق قد يُطلق على الإيجاد وفق تقدير أو مثال، أما الإبداع فيبرز الإنشاء الأول من غير مثال سابق ولا مادة يحتذيها. وهو أنسب للرد على دعوى الولد: من أبدع الكون كله ابتداءً لا يحتاج إلى التناسل ولا إلى معين يمده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص178–180، تحت البقرة: 117، في معنى إضافة ﴿بديع﴾ ودلالتها على الإنشاء بلا مثال.","url":""}]},{"id":"s2-424","number":424,"surah":2,"verses":[117],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ﴾ من غير أن يقول: «هو بديع السماوات والأرض»؟","answer":"حُذف المبتدأ لأن المرجع إلى الله معلوم من الآية السابقة، فجاء الوصف مستقلًا كحجة مباغتة لا تحتاج إلى تمهيد: بديع السماوات والأرض! وهذا القطع يشبه إبراز النعت وحده لتعظيمه، ويجعل الدليل أسرع وقوعًا في السمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص178–179، تحت البقرة: 117، في براعة حذف المسند إليه واستقلال الحجة.","url":""}]},{"id":"s2-425","number":425,"surah":2,"verses":[117],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا قَضَى أَمْرًا﴾ بـ﴿إذا﴾، مع أن قضاء الله سابق لوجود الزمان؟","answer":"تفيد ﴿إذا﴾ تحقق وقوع المقضي كلما تعلق به قضاؤه سبحانه، ولا يراد بها تقييد قدرته بزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص179–180، تحت البقرة: 117، في معنى ﴿إذا﴾ في سياق قضاء الله.","url":""}]},{"id":"s2-426","number":426,"surah":2,"verses":[117],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿قَضَى أَمْرًا﴾، دون أن يقال: «حكم أمرًا»؟","answer":"القضاء يجمع إحكام الأمر وإمضاءه وإتمامه حتى يتحقق، أما الحكم فقد يلحظ صدور القرار دون إبراز نفاذه. والمقام مقام قدرة تخلق بلا مهلة؛ فناسب اللفظ الذي يشير إلى أن المراد قد حُسم ومضى إلى الوجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص178–180، تحت البقرة: 117، في إيثار ﴿قضى﴾ على «حكم».","url":""}]},{"id":"s2-427","number":427,"surah":2,"verses":[117],"verseLabel":"البقرة: 117","question":"هل يقول الله للأشياء حقيقةً: ﴿كُنْ﴾ قبل وجودها؟ وكيف تسمع وهي معدومة؟","answer":"الكلام تمثيل لسرعة نفاذ إرادة الله وتكوينه من غير مهلة ولا عائق، لا لاحتياج الإيجاد إلى صوت تسمعه الموجودات قبل وجودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص178 و180–182، تحت البقرة: 117، في تمثيل الإيجاد بقوله ﴿كن فيكون﴾.","url":""}]},{"id":"s2-428","number":428,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يَعْلَمُونَ﴾، دون أن يقال: «المشركون»؟","answer":"سمّاهم بوصف يكشف علة مقالتهم: الجهل الذي يولد الاقتراح على الله، ويدخل في الوصف كل من يتكلم بهذه الطريقة بلا علم. كما أن ترك الاسم يوجه النظر من هوية القائل إلى خلل التفكير نفسه، فيظل التحذير صالحًا لكل قارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص183–187، تحت البقرة: 118، في إسناد القول إلى ﴿الذين لا يعلمون﴾.","url":""}]},{"id":"s2-429","number":429,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ مجيء نفي العلم بالمضارع: ﴿لَا يَعْلَمُونَ﴾، ولم يقل: «لم يعلموا»؟","answer":"المضارع يصور جهلهم متجددًا يصاحب كل اعتراض، لا واقعةً مضت وانتهت. وحتى لو عرفوا بعض الحقائق، فإن عدم الانتفاع بعلمهم أنزلهم منزلة من يتجدد منه الجهل قولًا وعملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص186–187، تحت البقرة: 118، في التعبير بالمضارع المنفي.","url":""}]},{"id":"s2-430","number":430,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما دلالة قولهم: ﴿لَوْلَا يُكَلِّمُنَا اللَّهُ﴾ دون «هل يكلمنا الله؟»؟","answer":"﴿لولا﴾ هنا للتحضيض الممزوج بالاعتراض؛ فهم لا يسألون طالبين الهداية، بل يطالبون أن يقع الأمر وفق اقتراحهم كأنه كان ينبغي أن يحدث. لذلك تكشف الأداة استكبار النية قبل أن تكشف مضمون الطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص187–188، تحت البقرة: 118، في دلالة ﴿لولا﴾ على التحضيض.","url":""}]},{"id":"s2-431","number":431,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما دلالة تقديمهم طلب كلام الله مباشرة: ﴿يُكَلِّمُنَا اللَّهُ﴾ على طلب الآية: ﴿أَوْ تَأْتِينَا آيَةٌ﴾؟","answer":"بدأوا بالأعظم والأجرأ: مساواتهم بالرسول في تلقي الكلام من الله، ثم نزلوا إلى طلب آية حسية خارقة. فالترتيب يكشف تضخم الاستكبار؛ لم يطلبوا مجرد دليل، بل رفعوا أنفسهم أولًا إلى مقام النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص187–189، تحت البقرة: 118، في المقابلة بين مطلوبيهم ودلالة ترتيب الكلام والآية.","url":""}]},{"id":"s2-432","number":432,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"لماذا نكّروا الآية فقالوا: ﴿أَوْ تَأْتِينَا آيَةٌ﴾، مع أن بين أيديهم آيات كثيرة؟","answer":"التنكير يفيد أنهم يريدون أي نوع من الخوارق الحسية يوافق هواهم، لا آية مخصوصة يبحثون عن دلالتها. وكأن القرآن والحجج القائمة لا تسمى عندهم آيات؛ فالمشكلة ليست غياب الدليل، بل اشتراط صورة يتعنتون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص188–189، تحت البقرة: 118، في تنكير ﴿آية﴾ وتحديد مرادهم بالمقابلة.","url":""}]},{"id":"s2-433","number":433,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ قَالَ الَّذِينَ مِنْ قَبْلِهِمْ مِثْلَ قَوْلِهِمْ﴾، فجمع بين ﴿كذلك﴾ و﴿مثل قولهم﴾؟","answer":"﴿كذلك﴾ تربط طريقتهم النفسية بطريقة السابقين، ثم يحدد ﴿مثل قولهم﴾ موضع التشابه في المقالة نفسها. فليس التشبيه حشوًا؛ الأول يعرض النمط المتكرر، والثاني يثبت تطابق القول الذي نتج عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص189–190، تحت البقرة: 118، في غرض التشبيه وبناء العبارة.","url":""}]},{"id":"s2-434","number":434,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ مِنْ قَبْلِهِمْ﴾ بـ﴿من﴾، دون أن يقال: «الذين قبلهم»؟","answer":"﴿من﴾ تفتح ابتداء الغاية إلى الأمم السابقة كلها، فلا تقصر التشابه على الجيل الأقرب زمنًا. فكأن هذا الاعتراض سلسلة قديمة تبدأ قبلهم وتمتد عبر أقوام متباعدين، كلما تشابهت دوافعهم أعادوا العبارة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص189–190، تحت البقرة: 118، في دلالة حرف ابتداء الغاية ﴿من﴾.","url":""}]},{"id":"s2-435","number":435,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿تَشَابَهَتْ قُلُوبُهُمْ﴾، دون أن يقال: «تشابهت أقوالهم» وقد ذكر تشابه القول قبلها؟","answer":"لأن تماثل الأقوال عرضٌ لسبب أعمق: تماثل القلوب في الجهل والعناد والاستكبار. انتقل القرآن من الظاهر إلى المنبع؛ فالكلمات تتكرر عبر القرون لأن المرض الداخلي واحد، ولذلك لا تعالج كثرة الآيات من أغلق قلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص189–191، تحت البقرة: 118، في الجمع بين تشابه الأقوال وتشابه القلوب.","url":""}]},{"id":"s2-436","number":436,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ مجيء الرد بالجمع في قوله تعالى: ﴿قد بينا الآيات﴾ مع طلبهم ﴿آية﴾ واحدة؟","answer":"زادهم القرآن فوق مقترحهم: لم تأتهم علامة واحدة بل دلائل كثيرة متنوعة عقلية ووحيية وكونية. فالعدول إلى الجمع يرد التعنت بسعة البيان، ويكشف أن العائق ليس قلة الآيات وإنما غياب اليقين الذي ينتفع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص190–192، تحت البقرة: 118، في العدول عن طلب السائلين والتعبير بالجمع.","url":""}]},{"id":"s2-437","number":437,"surah":2,"verses":[118],"verseLabel":"البقرة: 118","question":"ما سرّ تخصيص الانتفاع بالآيات بقوله: ﴿لِقَوْمٍ يُوقِنُونَ﴾، ولم يقل: «لقوم يعلمون»؟","answer":"لأن العلم قد يبقى معلومة لا تحرك صاحبها، أما اليقين فيستقر في القلب ويقطع التردد فيثمر قبولًا وعملًا. والآيات مبينة للجميع، لكن الذي يفتح لها قلبًا يريد الحق هو الذي تتحول عنده من مشهد إلى هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص191–192، تحت البقرة: 118، في ختم الآية بقوله ﴿لقوم يوقنون﴾.","url":""}]},{"id":"s2-438","number":438,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿إنا أرسلناك بالحق﴾ لا بالصدق؟","answer":"الحق أعم من الصدق؛ فالصدق يكون في الخبر، أما الحق فيشمل صدق الرسالة وثباتها وموافقتها لما يجب أن يكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص196، تحت البقرة: 119.","url":""}]},{"id":"s2-439","number":439,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما دلالة الجمع بين البشارة والنذارة، ثم نفي سؤال النبي ﷺ عن أصحاب الجحيم؟","answer":"استوعب وظيفته مع القابلين والمعاندين، ثم رفع عنه تبعة من اختار الجحيم؛ عليه البلاغ المتوازن لا إجبار القلوب ولا تحمل مصيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص192–198، تحت البقرة: 119.","url":""}]},{"id":"s2-440","number":440,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّا أَرْسَلْنَاكَ﴾ بهذه المؤكدات، مع أن النبي ﷺ لا يشك في رسالته؟","answer":"جاء التأكيد تنويهًا بعظم الخبر وتثبيتًا للنبي أمام تشكيك المعاندين، لا إزالةً لشك عنده. فاجتمعت ﴿إن﴾ وضمير العظمة وإعادة الضمير في الفعل لتعلن أن الرسالة صادرة من الله يقينًا، وأن اقتراحات المكذبين لا تنقص منها شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص192–196، تحت البقرة: 119، في تعدد المؤكدات في ﴿إنا أرسلناك﴾.","url":""}]},{"id":"s2-441","number":441,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما مناسبة تقديم ﴿بِالْحَقِّ﴾ فقال: ﴿أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا﴾؟","answer":"لأن كون الرسالة حقًا هو الأساس الذي تقوم عليه البشارة والنذارة؛ فقدم متعلق الإرسال لتثبيت صدق المصدر والمضمون قبل بيان وظيفتي الرسول. وفي التقديم مواجهة مباشرة لمن طلب آيات جديدة: الحق الذي يبحثون عنه حاضر في الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص192–195، تحت البقرة: 119، في تقديم المتعلق ﴿بالحق﴾ وبناء الجملة المؤكدة.","url":""}]},{"id":"s2-442","number":442,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما مناسبة تقديم ﴿بَشِيرًا﴾ على ﴿نَذِيرًا﴾؟","answer":"قُدمت البشارة لأنها أقرب إلى قبول النفوس وأليق بفتح باب الرجاء، ثم ذُكرت النذارة ليجتمع الترغيب والترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص192–195، تحت البقرة: 119، في ترتيب صفتي البشارة والنذارة ومناسبة الرسالة.","url":""}]},{"id":"s2-443","number":443,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿أَصْحَابِ الْجَحِيمِ﴾، دون أن يقال: «أهل الجحيم» أو «الداخلين فيها»؟","answer":"الصحبة تفيد الملازمة والاستقرار؛ فليسوا عابرين في النار ثم يفارقونها، بل صاروا أصحابها المختصين بها. واللفظ يصور مآلهم في صورة حال ملازمة، فيزيد الإنذار رهبة ويكشف قبح الإصرار الذي أوصلهم إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص196–197، تحت البقرة: 119، في فائدة التعبير بأصحاب الجحيم.","url":""}]},{"id":"s2-444","number":444,"surah":2,"verses":[119],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ﴾؛ أهو نفي للسؤال أم نهي عنه؟","answer":"تحتمل القراءات المعنيين: خبرًا بأن الرسول لا يُسأل عن مصير من رفض الحق، ونهيًا له عن السؤال عنهم لهول ما أُعد لهم. ويلتقي الوجهان في تسليته ﷺ: وظيفته البلاغ بالبشارة والنذارة، وليس عليه إيمان من اختار الجحيم ولا تبعة مصيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص195–197، تحت البقرة: 119، في توجيه قراءتي النفي والنهي.","url":""}]},{"id":"s2-445","number":445,"surah":2,"verses":[120,145],"verseLabel":"البقرة: 120 و145","question":"ما سرّ اختلاف التعبير والوعيد بين الآيتين 120 و145 من سورة البقرة؟","answer":"في الآية 120 جاء ﴿بعد الذي جاءك من العلم﴾ لأن المقام في أصل الهدى والملة، فناسب العلم المعهود الشامل، وجاء الوعيد بنفي الولي والنصير. وفي الآية 145 تعلق السياق بحكم القبلة، فجاء ﴿من بعد ما جاءك﴾، وناسب العدول عنه وصف الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص454–456، تحت البقرة: 145، في المقارنة بالبقرة: 120.","url":""}]},{"id":"s2-446","number":446,"surah":2,"verses":[73],"verseLabel":"البقرة: 120، آل عمران: 73","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَى﴾، وقوله تعالى في آل عمران: ﴿قُلْ إِنَّ الْهُدَى هُدَى اللَّهِ﴾ فعكس ترتيب كلمتي الهدى؟","answer":"في البقرة المقام رد على من زعم أن الهدى في ملته، فقُدّم ﴿هدى الله﴾ وقُصر عليه جنس الهدى. وفي آل عمران كان المقصود تقرير أن الهدى المعروف إنما هو هدى الله، فناسب تقديم ﴿الهدى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص206–207، تحت البقرة: 120، في المقارنة بآل عمران: 73.","url":""}]},{"id":"s2-447","number":447,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَنْ تَرْضَى عَنْكَ الْيَهُودُ وَلَا النَّصَارَى﴾ بـ﴿لن﴾، دون أن يقال: «لا ترضى»؟","answer":"﴿لن﴾ تمد النفي إلى المستقبل وتقطع انتظار رضا يقوم على تنازل ناقص؛ فهم لا يطلبون تعديلًا جزئيًا بل اتباع ملتهم. والعبارة تحرر المؤمن من مطاردة رضا لا نهاية لشروطه ما دام ثابتًا على الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص201–204، تحت البقرة: 120، في دلالة النفي بـ﴿لن﴾.","url":""}]},{"id":"s2-448","number":448,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿تَرْضَى عَنْكَ﴾ بحرف ﴿عن﴾، دون أن يقال: «ترضى بك»؟","answer":"الرضا بـ﴿عن﴾ يتجه إلى موقفهم من الشخص وسلوكه، وفيه معنى انصراف السخط عنه؛ أما الرضا بالشيء فيغلب أن يكون قبولًا له واختيارًا. والسياق يصور أسبابًا في نظرهم تمنع رضاهم عن الرسول حتى يترك استقلاله ويتبع ملتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص202–203، تحت البقرة: 120، في تعدية فعل الرضا بـ﴿عن﴾.","url":""}]},{"id":"s2-449","number":449,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما مناسبة تقديم اليهود على النصارى؟","answer":"لأن اليهود أسبق زمنًا وأشد عداوةً للمؤمنين كما يبين القرآن، فقدم الفريق الأقدم والأغلظ في هذا المقام. ثم عطف النصارى لتكتمل صورة أهل الكتاب الذين لا يجمعهم رضا واحد إلا مطالبة الرسول باتباع ما هم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص203–204، تحت البقرة: 120، في نكتة تقديم اليهود على النصارى.","url":""}]},{"id":"s2-450","number":450,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿اليهود ولا النصارى﴾ بدل عطف الاسمين من غير تكراره؟","answer":"تكرار ﴿لا﴾ يجعل نفي الرضا مستقلًا عن كل فريق؛ فلا يتوهم أن اجتماعهما وحده هو المنفي أو أن أحدهما قد يرضى منفردًا. كما يفصل الصوت بين الخصمين اللذين تختلف ملتاهما، مع اتحادهما في الضغط على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص203–204، تحت البقرة: 120، في إيراد ﴿لا﴾ قبل النصارى.","url":""}]},{"id":"s2-451","number":451,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى تَتَّبِعَ مِلَّتَهُمْ﴾، دون أن يقال: «إلى أن تتبع ملتهم»؟","answer":"﴿حتى﴾ لا تذكر نهايةً زمنية فحسب، بل تشعر بأن اتباع ملتهم هو الغاية الوحيدة التي يقفون عندها؛ وكل ما قبلها من مجاملة أو مداهنة لا يحقق الرضا. فهي تصور مطالبهم طريقًا متصاعدًا لا ينتهي إلا بالتخلي الكامل عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص204–205، تحت البقرة: 120، في اختيار ﴿حتى﴾ دون «إلى».","url":""}]},{"id":"s2-452","number":452,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿تَتَّبِعَ مِلَّتَهُمْ﴾، دون أن يقال: «تدخل في ملتهم»؟","answer":"الاتباع أوسع وأدق في كشف مرادهم؛ فهم يريدون أن يقفو الرسول تصوراتهم وأحكامهم خطوةً خطوة حتى لا يبقى له استقلال في دينه. وقد يبدأ الانحراف بالموافقة العملية قبل إعلان الدخول، فجاء اللفظ ليحذر الطريق كله لا نهايته فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص198 و204–205، تحت البقرة: 120، في إيثار فعل ﴿تتبع﴾.","url":""}]},{"id":"s2-453","number":453,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ إفراد ﴿ملتهم﴾ مع أن اليهود والنصارى ملتان متعارضتان؟","answer":"أُفردت ﴿ملتهم﴾ لأن اليهود والنصارى اجتمعوا في هذا المقام على مخالفة الإسلام وطلب اتباع غيره، وإن اختلفت ملتاهما في التفاصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص205–206، تحت البقرة: 120، في إفراد الملة وإضافتها إلى الفريقين.","url":""}]},{"id":"s2-454","number":454,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَى﴾، مع أن معنى الجملة يبدو معلومًا؟","answer":"أسلوب القصر يقلب دعوى من زعم أن الهدى حكر على ملته: الهدى الكامل حقًا هو ما جاء من الله، لا ما بدلته الجماعات بحسب أهوائها. وضمير الفصل والتعريف يجعلان سائر ما خالف الوحي ساقطًا عن رتبة الهداية مهما رفع أصحابه شعاراتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص205–208، تحت البقرة: 120، في القصر وتوالي المؤكدات في ﴿إن هدى الله هو الهدى﴾.","url":""}]},{"id":"s2-455","number":455,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما دلالة إضافة الهدى إلى الله فقال: ﴿هُدَى اللَّهِ﴾؟","answer":"الإضافة تشرف الهدى بمصدره وتضع معيارًا لا يتغير بتغير الجماعات: ما كان وحيًا من الله فهو الهدى، وما خالفه لا يكتسب قيمته من كثرة أتباعه. وفيها تحقير ضمني للبدائل البشرية التي نسبها أصحابها إلى الدين بعد التحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص206–207، تحت البقرة: 120، في دلالة إضافة الهدى إلى لفظ الجلالة.","url":""}]},{"id":"s2-456","number":456,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ تسمية ملتهم ﴿أَهْوَاءَهُمْ﴾، ولم يقل: «ولئن اتبعت ملتهم»؟","answer":"لأن ما خالف الوحي فيها لم يعد شريعةً من الله، بل صار اختيارات تميل إليها النفوس طلبًا للرئاسة أو موافقة للرغبة. فالعدول إلى ﴿الأهواء﴾ ينزع عن الباطل قناع الدين، ويكشف أن مطالبتهم الرسول ليست طلبًا للحقيقة بل طلبًا لأن يخضع لرغباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص208–210، تحت البقرة: 120، في التعبير بالأهواء بدل الدين أو الملة.","url":""}]},{"id":"s2-457","number":457,"surah":2,"verses":[120],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿أَهْوَاءَهُمْ﴾ بالجمع، مع أنه قال قبلها: ﴿مِلَّتَهُمْ﴾ بالإفراد؟","answer":"أُفردت ﴿ملتهم﴾ لاجتماعهم في مخالفة الحق، وجُمعت ﴿أهواءهم﴾ لأن أهواءهم متعددة متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص208–210، تحت البقرة: 120، في جمع ﴿الأهواء﴾ ومقابلته بإفراد الملة.","url":""}]},{"id":"s2-458","number":458,"surah":2,"verses":[120,145],"verseLabel":"البقرة: 120 و145","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿بَعْدَ الَّذِي جَاءَكَ مِنَ الْعِلْمِ﴾، ثم قال في الآية 145: ﴿مِنْ بَعْدِ مَا جَاءَكَ مِنَ الْعِلْمِ﴾؟","answer":"﴿الذي﴾ أعرق في التعريف من ﴿ما﴾، فناسب المقام الأول الذي فُصّل فيه الهدى والعلم المعلوم وصفه. وأما ﴿ما﴾ فناسبت الموضع الثاني المتعلق بعلم جزئي، هو أمر القبلة. ودخول ﴿من﴾ الابتدائية يدل على أن هذا العلم جزئي من عموم العلم الذي جاء النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص209–210، تحت البقرة: 120 و145، في توجيه المتشابه بين الآيتين.","url":""}]},{"id":"s2-459","number":459,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿يتلونه حق تلاوته﴾؟ وكيف تكون للكتاب تلاوة حق؟","answer":"حق التلاوة يجمع ضبط اللفظ، وفهم المعنى، ولزوم العمل؛ فليس المراد مجرد القراءة باللسان، بل قراءة يتبعها التصديق والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص213–219، تحت البقرة: 121.","url":""}]},{"id":"s2-460","number":460,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ﴾، دون أن يقال: «أهل الكتاب»؟","answer":"لأن الوصف لا يشمل كل منتسب إلى الكتاب؛ بل يخص الذين تلقوه حقًا وحفظوا عهد الله فيه، ومنهم من آمن بالنبي ﷺ. فصلة الموصول تجعل استحقاق المدح متعلقًا بالإيتاء والتلاوة الصحيحة، لا بلقب موروث قد يحمله من كتم وحرّف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص213–216، تحت البقرة: 121، في التعبير بالاسم الموصول وتعيين المستحقين للمدح.","url":""}]},{"id":"s2-461","number":461,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ تعريف ﴿الكتاب﴾ في قوله تعالى: ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ﴾، دون أن يقال: «كتابًا»؟","answer":"يجوز أن يراد بالكتاب العهد، ويجوز أن يراد جنس الكتاب المنزل الذي يجمع التوراة والإنجيل والقرآن في أصل الوحي؛ فالتعريف يعيّن الكتاب الإلهي المعروف الذي يجب الوفاء به والإيمان بما يصدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص215–216، تحت البقرة: 121، في معنى التعريف في ﴿الكتاب﴾.","url":""}]},{"id":"s2-462","number":462,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتْلُونَهُ﴾، دون أن يقال: «يقرؤونه»؟","answer":"التلاوة تجمع القراءة والاتباع؛ أصلها أن يتلو الشيءُ الشيءَ، فكأن عملهم يأتي خلف ألفاظ الكتاب ولا ينفصل عنها. أما القراءة وحدها فقد تقع باللسان مع ترك الحكم، وهو الخلل الذي ذمته الآيات السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص216–218، تحت البقرة: 121، في دلالة ﴿يتلونه﴾ على القراءة والاتباع.","url":""}]},{"id":"s2-463","number":463,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتْلُونَهُ﴾ بالمضارع؟","answer":"ليصور التلاوة والاتباع عادة متجددة لا موقفًا وقع مرة ثم انقطع؛ فهم يرجعون إلى الكتاب في أحوالهم ويلازمون هديه. وهذا الاستمرار هو الذي يميز من يعيش بالوحي عمن عرف دلالته لحظة ثم كتمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص217–218، تحت البقرة: 121، في التعبير بالفعل المضارع.","url":""}]},{"id":"s2-464","number":464,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما دلالة اسم الإشارة للبعيد في قوله تعالى: ﴿أُولَئِكَ يُؤْمِنُونَ بِهِ﴾؟","answer":"البعد هنا لعلو المنزلة، لا لبعد المكان؛ رفع الذين جمعوا التلاوة والعمل حتى كأنهم في مقام يشار إليه من بعيد. كما يربط اسم الإشارة الحكم بالصفات السابقة: بسبب إيتائهم الكتاب وتلاوته حقًا استحقوا وصف الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص218، تحت البقرة: 121، في استعمال اسم الإشارة للبعيد.","url":""}]},{"id":"s2-465","number":465,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ يَكْفُرْ بِهِ فَأُولَئِكَ هُمُ الْخَاسِرُونَ﴾، فبدأ بالمفرد ثم انتقل إلى الجمع؟","answer":"روعي لفظ ﴿من﴾ أولًا في فعل الفرد واختياره، ثم روعي معناها العام في الحكم الذي يشمل كل من اتصف بالكفر. فيضع التركيب المسؤولية على كل شخص، ثم يجمع أصحاب النتيجة الواحدة في مصير الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص218–219، تحت البقرة: 121، في الانتقال من لفظ ﴿من﴾ إلى معنى الجمع.","url":""}]},{"id":"s2-466","number":466,"surah":2,"verses":[121],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿هُمُ الْخَاسِرُونَ﴾، دون أن يقال: «فأولئك خاسرون»؟","answer":"ضمير الفصل وتعريف الخبر في ﴿هُمُ الْخَاسِرُونَ﴾ يفيدان اختصاصهم بالخسران الكامل؛ لأنهم باعوا العظيم الباقي بالحقير الفاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص218–219، تحت البقرة: 121، في ضمير الفصل والتعريف والثبات في جملة الخسران.","url":""}]}];
